                                                                                                                                               > ###############################################################################
                                                                                                                                             > # UCSC CHEM 124 - Bioanalytical Chemistry
                                                                                                                                               > # LAB 3: Metabolomics of Coffee Beans Using 1H NMR and PCA
                                                                                                                                               > # Official ACS Publication-Grade Application Note Graphics Engine
                                                                                                                                               > ###############################################################################
                                                                                                                                             > 
                                                                                                                                               > # ---- 0. Packages & Library Initialization ----------------------------------
                                                                                                                                             > pkgs <- c("ggplot2", "dplyr", "tidyr", "ggrepel", "ggdendro")
                                                                                                                                             > for (p in pkgs) {
                                                                                                                                               +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                               +     library(p, character.only = TRUE)
                                                                                                                                               + }
                                                                                                                                             > 
                                                                                                                                               > # ---- 1. Experimental Settings & Parameters ---------------------------------
                                                                                                                                             > cat("Please select your 'arabica_raw.csv' file...\n")
                                                                                                                                             Please select your 'arabica_raw.csv' file...
                                                                                                                                             > arabica_file <- file.choose()
                                                                                                                                             > 
                                                                                                                                               > cat("Please select your 'robusta_raw.csv' file...\n")
                                                                                                                                             Please select your 'robusta_raw.csv' file...
                                                                                                                                             > robusta_file <- file.choose()
                                                                                                                                             > 
                                                                                                                                               > cat("Please select your 'unknown_raw.csv' file...\n")
                                                                                                                                             Please select your 'unknown_raw.csv' file...
                                                                                                                                             > unknown_file <- file.choose()
                                                                                                                                             > 
                                                                                                                                               > out_dir <- file.path(dirname(arabica_file), "pca_output")
                                                                                                                                             > dir.create(out_dir, showWarnings = FALSE)
                                                                                                                                             > 
                                                                                                                                               > bin_width <- 0.04           # ppm per bin
                                                                                                                                             > ppm_range <- c(0.5, 10.0)    # region of the spectrum to keep
                                                                                                                                             > keep_classes <- c("Compound", "Impurity", "Unknown") 
                                                                                                                                             > max_width <- 20             # drop broad baseline humps
                                                                                                                                             > 
                                                                                                                                               > # Professional Colorblind-Friendly ACS Palette
                                                                                                                                               > class_cols <- c(
                                                                                                                                                 +     arabica = "#2a6f97",   # Deep Ocean Blue
                                                                                                                                                 +     robusta = "#ca6702",   # Terracotta Copper
                                                                                                                                                 +     unknown = "#9a031e"    # Ruby Wine Red
                                                                                                                                                 + )
                                                                                                                                             > 
                                                                                                                                               > # ---- 2. Flexible Raw Data Ingestion Function --------------------------------
                                                                                                                                             > read_raw <- function(file, class_label) {
                                                                                                                                               +     if (!file.exists(file)) stop(paste("Could not find file:", file))
                                                                                                                                               +     lines <- readLines(file, warn = FALSE, encoding = "UTF-8")
                                                                                                                                               +     lines <- sub("^\ufeff", "", lines)
                                                                                                                                               +     lines <- lines[nzchar(trimws(gsub("[,\t]", "", lines)))] 
                                                                                                                                               +     
                                                                                                                                                 +     is_header <- grepl("\\.fid", lines, ignore.case = TRUE)
                                                                                                                                                 +     spec_name <- sub("[,\t].*$", "", lines[is_header]) 
                                                                                                                                                 +     spec_id   <- cumsum(is_header)
                                                                                                                                                 +     
                                                                                                                                                   +     body  <- lines[!is_header]
                                                                                                                                                   +     idx   <- spec_id[!is_header]
                                                                                                                                                   +     parts <- strsplit(body, "[\t,]") 
                                                                                                                                                   +     get <- function(i) vapply(parts, function(x) if (length(x) >= i) x[i] else NA_character_, "")
                                                                                                                                                   +     
                                                                                                                                                     +     first_val <- suppressWarnings(as.numeric(get(1)))
                                                                                                                                                     +     if (all(is.na(first_val))) {
                                                                                                                                                       +         data.frame(
                                                                                                                                                         +             class = class_label, file = spec_name[idx],
                                                                                                                                                         +             ppm = suppressWarnings(as.numeric(get(2))), intensity = suppressWarnings(as.numeric(get(3))),
                                                                                                                                                         +             width = suppressWarnings(as.numeric(get(4))), area = suppressWarnings(as.numeric(get(5))),
                                                                                                                                                         +             peak_class = get(1), stringsAsFactors = FALSE
                                                                                                                                                         +         )
                                                                                                                                                       +     } else {
                                                                                                                                                         +         data.frame(
                                                                                                                                                           +             class = class_label, file = spec_name[idx],
                                                                                                                                                           +             ppm = suppressWarnings(as.numeric(get(1))), intensity = suppressWarnings(as.numeric(get(2))),
                                                                                                                                                           +             width = suppressWarnings(as.numeric(get(3))), area = suppressWarnings(as.numeric(get(4))),
                                                                                                                                                           +             peak_class = get(5), stringsAsFactors = FALSE
                                                                                                                                                           +         )
                                                                                                                                                         +     }
                                                                                                                                                     + }
                                                                                                                                             > 
                                                                                                                                               > peaks <- bind_rows(
                                                                                                                                                 +     read_raw(arabica_file, "arabica"),
                                                                                                                                                 +     read_raw(robusta_file, "robusta"),
                                                                                                                                                 +     read_raw(unknown_file, "unknown")
                                                                                                                                                 + ) %>% filter(!is.na(ppm), !is.na(area))
                                                                                                                                             > 
                                                                                                                                               > short_label <- function(cls, file) {
                                                                                                                                                 +     day  <- sub("^\\d{4}-\\d{2}-(\\d{2})-.*$", "\\1", file)
                                                                                                                                                 +     name <- sub("^\\d{4}-\\d{2}-\\d{2}-chem124-", "", file, ignore.case = TRUE)
                                                                                                                                                 +     name <- sub("\\.fid$", "", name, ignore.case = TRUE)
                                                                                                                                                 +     name <- sub("\\.\\d+$", "", name)
                                                                                                                                                 +     paste0(toupper(substr(cls, 1, 1)), ":", name, "@", day)
                                                                                                                                                 + }
                                                                                                                                             > peaks <- peaks %>% mutate(spectrum = short_label(class, file))
                                                                                                                                             > 
                                                                                                                                               > # ---- 3. Data Ingestion & Preprocessing -------------------------------------
                                                                                                                                             > peaks_clean <- peaks %>%
                                                                                                                                               +     filter(peak_class %in% keep_classes | class == "unknown",
                                                                                                                                                            +            ppm >= ppm_range[1], ppm <= ppm_range[2],
                                                                                                                                                            +            width <= max_width, area > 0)
                                                                                                                                             > 
                                                                                                                                               > breaks <- seq(ppm_range[1], ppm_range[2], by = bin_width)
                                                                                                                                             > 
                                                                                                                                               > bin_df <- peaks_clean %>%
                                                                                                                                               +     mutate(bin = cut(ppm, breaks = breaks, include.lowest = TRUE, labels = FALSE),
                                                                                                                                                            +            bin_mid = breaks[bin] + bin_width / 2) %>%
                                                                                                                                               +     group_by(class, spectrum, bin_mid) %>%
                                                                                                                                               +     summarise(area = sum(area), .groups = "drop") %>%
                                                                                                                                               +     group_by(spectrum) %>%
                                                                                                                                               +     mutate(area = area / sum(area) * 100) %>% # Total Area Normalization (%)
                                                                                                                                               +     ungroup() %>%
                                                                                                                                               +     complete(nesting(class, spectrum), bin_mid, fill = list(area = 0))
                                                                                                                                             > 
                                                                                                                                               > wide <- bin_df %>% pivot_wider(names_from = bin_mid, values_from = area)
                                                                                                                                             > meta <- wide %>% select(class, spectrum)
                                                                                                                                             > X    <- sqrt(as.matrix(wide %>% select(-class, -spectrum))) # Variance-Stabilizing Transform
                                                                                                                                             > rownames(X) <- meta$spectrum
                                                                                                                                             > 
                                                                                                                                               > is_known  <- meta$class != "unknown"
                                                                                                                                             > X_known   <- X[is_known, , drop = FALSE]
                                                                                                                                             > X_unknown <- X[!is_known, , drop = FALSE]
                                                                                                                                             > 
                                                                                                                                               > X_known   <- X_known[, apply(X_known, 2, var) > 0, drop = FALSE]
                                                                                                                                             > X_unknown <- X_unknown[, colnames(X_known), drop = FALSE]
                                                                                                                                             > 
                                                                                                                                               > # ---- 4. Chemometric Modeling (Principal Component Analysis) -----------------
                                                                                                                                             > pca <- prcomp(X_known, center = TRUE, scale. = FALSE)
                                                                                                                                             > var_exp <- pca$sdev^2 / sum(pca$sdev^2) * 100
                                                                                                                                             > 
                                                                                                                                               > scores <- as.data.frame(pca$x[, 1:5])
                                                                                                                                             > scores$spectrum <- rownames(scores)
                                                                                                                                             > scores$class    <- meta$class[is_known]
                                                                                                                                             > 
                                                                                                                                               > unk_scores <- as.data.frame(predict(pca, newdata = X_unknown)[, 1:5, drop = FALSE])
                                                                                                                                             > unk_scores$spectrum <- rownames(X_unknown)
                                                                                                                                             > unk_scores$class    <- "unknown"
                                                                                                                                             > 
                                                                                                                                               > all_scores <- bind_rows(scores, unk_scores) %>%
                                                                                                                                               +     mutate(class = factor(class, levels = c("arabica", "robusta", "unknown")))
                                                                                                                                             > 
                                                                                                                                               > write.csv(all_scores, file.path(out_dir, "pca_scores.csv"), row.names = FALSE)
                                                                                                                                             > 
