                                                                                                                                               > # ---- 5a. Figure 1: Full Section Score Plot (PC1 vs PC2) --------------------
                                                                                                                                             > p_scores_full <- ggplot(all_scores, aes(PC1, PC2, colour = class)) +
                                                                                                                                               +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                               +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                               +     geom_point(data = filter(all_scores, class != "unknown"), size = 2, alpha = 0.85) +
                                                                                                                                               +     geom_point(data = filter(all_scores, class == "unknown"), shape = 8, size = 3, stroke = 1.2) +
                                                                                                                                               +     geom_text_repel(aes(label = spectrum), size = 1.8, fontfamily = "sans", 
                                                                                                                                                                     +                     show.legend = FALSE, max.overlaps = 20, box.padding = 0.2) +
                                                                                                                                               +     scale_colour_manual(values = class_cols) +
                                                                                                                                               +     labs(x = paste0("PC1 (", round(var_exp[1], 1), "%)"), y = paste0("PC2 (", round(var_exp[2], 1), "%)")) +
                                                                                                                                               +     theme_bw(base_size = 8, base_family = "sans") + 
                                                                                                                                               +     theme(
                                                                                                                                                 +         panel.grid.major = element_blank(), panel.grid.minor = element_blank(),
                                                                                                                                                 +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                 +         legend.title     = element_blank(), legend.text = element_text(size = 7),
                                                                                                                                                 +         legend.position  = "inside", legend.position.inside = c(0.15, 0.18),
                                                                                                                                                 +         legend.background = element_rect(fill = "white", color = "black", linewidth = 0.3)
                                                                                                                                                 +     )
