                                                                                                                                                                  > 
                                                                                                                                                                    > ggsave(file.path(out_dir, "Figure1_PCA_Scores_Full_Section.png"), plot = p_scores_full, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                  > 
                                                                                                                                                                    > # ---- 5b. Figure 2: Isolated Group Score Plot (Checklist Point #2) ------------
                                                                                                                                                                  > # Simulating an isolated group dataset by tracking a single day/cohort footprint
                                                                                                                                                                    > group_subset   <- all_scores %>% filter(grepl("@20|unknown", spectrum)) 
                                                                                                                                                                  > p_scores_group <- ggplot(group_subset, aes(PC1, PC2, colour = class)) +
