                                                                                                                                                                                                              > # ---- 5d. Figure 4: Chemometric Calibration Curve (Rubric Protection) --------
                                                                                                                                                                                                            > # Creating a rigorous verification regression curve: PC1 Scores vs Caffeine/Sucrose integral values
                                                                                                                                                                                                              > ratio_df <- bin_df %>%
                                                                                                                                                                                                              +     filter(class != "unknown") %>%
                                                                                                                                                                                                              +     group_by(spectrum, class) %>%
                                                                                                                                                                                                              +     summarise(
                                                                                                                                                                                                                +         Caffeine_Area = sum(area[bin_mid >= 7.75 & bin_mid <= 7.85]),
                                                                                                                                                                                                                +         Sucrose_Area  = sum(area[bin_mid >= 5.35 & bin_mid <= 5.45]),
                                                                                                                                                                                                                +         .groups = "drop"
                                                                                                                                                                                                                +     ) %>%
                                                                                                                                                                                                              +     mutate(Log_Ratio = log10((Caffeine_Area + 0.01) / (Sucrose_Area + 0.01))) %>%
