                                                                                                                                                                                                                                                                                                          > # =============================================================================
                                                                                                                                                                                                                                                                                                        > # ---- Figure 1: Stacked 1H NMR Spectral Trace Overlay Engine -----------------
                                                                                                                                                                                                                                                                                                        > # =============================================================================
                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                          > library(ggplot2)
                                                                                                                                                                                                                                                                                                        > library(dplyr)
                                                                                                                                                                                                                                                                                                        > library(tidyr)
                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                          > # 1. Generating Mock Continuous 1H NMR Line-Shape Trace Data (5.0 to 10.0 ppm)
                                                                                                                                                                                                                                                                                                          > # Continuous ppm vector standard for down-field coffee profiling
                                                                                                                                                                                                                                                                                                          > ppm_seq <- seq(5.0, 10.0, by = 0.002)
                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                          > # Lorentzian mathematical line-shape function to simulate raw FID peak profiles
                                                                                                                                                                                                                                                                                                          > lorentzian <- function(x, x0, gamma, amplitude) {
                                                                                                                                                                                                                                                                                                            +     amplitude * (gamma^2 / ((x - x0)^2 + gamma^2))
                                                                                                                                                                                                                                                                                                            + }
                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                          > # Building a baseline trace with synthetic high-resolution micro-instrument noise
                                                                                                                                                                                                                                                                                                          > set.seed(42)
                                                                                                                                                                                                                                                                                                        > noise_a <- rnorm(length(ppm_seq), mean = 0, sd = 0.012)
                                                                                                                                                                                                                                                                                                        > noise_r <- rnorm(length(ppm_seq), mean = 0, sd = 0.012)
                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                          > # Simulating the C. arabica Metabolomic Fingerprint
                                                                                                                                                                                                                                                                                                          > # Normalized so that the Sucrose anomeric doublet is uniform with Robusta
                                                                                                                                                                                                                                                                                                          > arabica_trace <- data.frame(
                                                                                                                                                                                                                                                                                                            +     ppm = ppm_seq,
                                                                                                                                                                                                                                                                                                            +     intensity = lorentzian(ppm_seq, 5.40, 0.015, 1.20) +  # Sucrose (Normalized target)
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 7.80, 0.020, 0.25) +  # Caffeine (Low in Arabica)
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 6.45, 0.040, 0.20) +  # Chlorogenic Acids (CQAs)
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 6.85, 0.035, 0.15) +  
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 7.15, 0.045, 0.22) +  
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 8.82, 0.030, 0.40) +  # Trigonelline
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 9.12, 0.025, 0.35) +  
                                                                                                                                                                                                                                                                                                              +         noise_a,
                                                                                                                                                                                                                                                                                                            +     class = "Coffea arabica"
                                                                                                                                                                                                                                                                                                            + )
                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                          > # Simulating the C. canephora (Robusta) Metabolomic Fingerprint
                                                                                                                                                                                                                                                                                                          > # Showcases elevated baseline intensities for alkaloids and phenolics
                                                                                                                                                                                                                                                                                                          > robusta_trace <- data.frame(
                                                                                                                                                                                                                                                                                                            +     ppm = ppm_seq,
                                                                                                                                                                                                                                                                                                            +     intensity = lorentzian(ppm_seq, 5.40, 0.015, 1.20) +  # Sucrose (Identical target scale)
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 7.80, 0.020, 1.15) +  # Caffeine (Significantly Higher)
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 6.45, 0.040, 0.55) +  # Chlorogenic Acids (Significantly Higher)
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 6.85, 0.035, 0.45) +  
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 7.15, 0.045, 0.65) +  
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 8.82, 0.030, 0.45) +  # Trigonelline
                                                                                                                                                                                                                                                                                                              +         lorentzian(ppm_seq, 9.12, 0.025, 0.38) +  
                                                                                                                                                                                                                                                                                                              +         noise_r,
                                                                                                                                                                                                                                                                                                            +     class = "Coffea canephora (Robusta)"
                                                                                                                                                                                                                                                                                                            + )
                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                          > # Combine datasets into a stacked, paneled layout array
                                                                                                                                                                                                                                                                                                          > stacked_spectral_data <- bind_rows(arabica_trace, robusta_trace) %>%
                                                                                                                                                                                                                                                                                                          +     mutate(class = factor(class, levels = c("Coffea arabica", "Coffea canephora (Robusta)")))
                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                          > # Custom annotation labels frame mapping specific small-molecule assignments
                                                                                                                                                                                                                                                                                                          > peak_annotations <- data.frame(
