                                                                                                                                                                                                                                                                                                                       > # ---- Figure 5: Chemometric Calibration Regression Curve Engine --------------
                                                                                                                                                                                                                                                                                                                       > # =============================================================================
                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                         > # 1. Isolating individual peak integral area boundaries from bin_df
                                                                                                                                                                                                                                                                                                                         > ratio_df <- bin_df %>%
                                                                                                                                                                                                                                                                                                                         +     filter(class != "unknown") %>% # Focus on reference standards populations
                                                                                                                                                                                                                                                                                                                         +     group_by(spectrum, class) %>%
                                                                                                                                                                                                                                                                                                                         +     summarise(
                                                                                                                                                                                                                                                                                                                           +         Caffeine_Area = sum(area[bin_mid >= 7.75 & bin_mid <= 7.85]),
                                                                                                                                                                                                                                                                                                                           +         Sucrose_Area  = sum(area[bin_mid >= 5.35 & bin_mid <= 5.45]),
                                                                                                                                                                                                                                                                                                                           +         .groups = "drop"
                                                                                                                                                                                                                                                                                                                           +     ) %>%
                                                                                                                                                                                                                                                                                                                         +     # Logarithmic transformation to linearize phenotypic ratios and stabilize variance
                                                                                                                                                                                                                                                                                                                         +     mutate(Log_Ratio = log10((Caffeine_Area + 0.01) / (Sucrose_Area + 0.01))) %>%
                                                                                                                                                                                                                                                                                                                         +     left_join(all_scores, by = "spectrum")
                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                         > # 2. Executing Ordinary Least Squares Linear Regression Model
                                                                                                                                                                                                                                                                                                                         > fit <- lm(PC1 ~ Log_Ratio, data = ratio_df)
                                                                                                                                                                                                                                                                                                                       > r2_val <- round(summary(fit)$r.squared, 3)
                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                         > # Formulating mathematical display label using 'atop' to prevent multi-line \n parse errors
                                                                                                                                                                                                                                                                                                                         > eq_label <- paste0("atop(PC1 == ", round(coef(fit)[2], 2), " * log[10](Caf/Suc) - ", abs(round(coef(fit)[1], 2)), 
                                                                                                                                                                                                                                                                                                                                              +                    ", R^2 == ", r2_val, ")")
                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                         > # 3. Rendering the Clean, Gridless ACS Publication Calibration Curve
                                                                                                                                                                                                                                                                                                                         > p_calibration <- ggplot(ratio_df, aes(x = Log_Ratio, y = PC1)) +
                                                                                                                                                                                                                                                                                                                         +     # Adds a solid black fit line superimposed over a light-grey 95% standard error confidence band
                                                                                                                                                                                                                                                                                                                         +     geom_smooth(method = "lm", colour = "black", fill = "grey93", linewidth = 0.5, formula = y ~ x) +
                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                         +     # Plot data track scores colored cleanly by their biological species lineage
                                                                                                                                                                                                                                                                                                                         +     geom_point(aes(colour = class.x), size = 2.0, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                         +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                         +     # Annotate mathematical regression formula inside the open upper-left quadrant
                                                                                                                                                                                                                                                                                                                         +     annotate("text", x = min(ratio_df$Log_Ratio) * 0.9, y = max(ratio_df$PC1) * 0.7,
                                                                                                                                                                                                                                                                                                                                        +              label = eq_label, parse = TRUE, size = 2.2, fontfamily = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                         +     labs(x = expression(paste("Log"[10], " (Caffeine / Sucrose Peak Integral Ratio)")), 
                                                                                                                                                                                                                                                                                                                                    +          y = "Calculated Principal Component 1 Coordinates") +
                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                         +     # Apply strict ACS visual boundary frame styles
                                                                                                                                                                                                                                                                                                                         +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                         +     theme(
                                                                                                                                                                                                                                                                                                                           +         panel.grid.major = element_blank(), # Clean White: Removes distracting grid blocks
                                                                                                                                                                                                                                                                                                                           +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                           +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                           +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                           +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                           +         axis.ticks       = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                           +         legend.position  = "none" # Subsections remain clear without duplicate legends
                                                                                                                                                                                                                                                                                                                           +     )
                                                                                                                                                                                                                                                                                                                       Warning message:
