                                                                                                                                                                                                                                                                                                                                       > ggsave(file.path(out_dir, "Figure5_Chemometric_Calibration_Curve.png"), 
                                                                                                                                                                                                                                                                                                                                                +        plot = p_calibration, width = 3.25, height = 3.0, units = "in", dpi = 600)
