                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                       > # 5. Rendering the Clean, Gridless ACS Publication Dendrogram
                                                                                                                                                                                                                                                                                                                                       > p_dendrogram <- ggplot() +
                                                                                                                                                                                                                                                                                                                                       +     # Draw the structural branch segments of the clustering tree
                                                                                                                                                                                                                                                                                                                                       +     geom_segment(data = segment(dendro_data), 
                                                                                                                                                                                                                                                                                                                                                          +                  aes(x = x, y = y, xend = xend, yend = yend), 
                                                                                                                                                                                                                                                                                                                                                          +                  colour = "black", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                       +     
                                                                                                                                                                                                                                                                                                                                       +     # Superimpose your sample leaf labels rotated at 90 degrees
                                                                                                                                                                                                                                                                                                                                       +     # Color-coded completely to match your standard easy-on-the-eyes palette
                                                                                                                                                                                                                                                                                                                                       +     geom_text(data = leaf_labels, 
                                                                                                                                                                                                                                                                                                                                                       +               aes(x = x, y = y, label = spectrum, colour = class), 
                                                                                                                                                                                                                                                                                                                                                       +               hjust = 1.05, angle = 90, size = 1.8, fontfamily = "sans") +
                                                                                                                                                                                                                                                                                                                                       +     
                                                                                                                                                                                                                                                                                                                                       +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                                       +     
                                                                                                                                                                                                                                                                                                                                       +     # Expand vertical scaling limits to accommodate the text labels beneath the tree leaves
                                                                                                                                                                                                                                                                                                                                       +     scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
                                                                                                                                                                                                                                                                                                                                       +     
                                                                                                                                                                                                                                                                                                                                       +     labs(y = "Euclidean Distance", title = "Hierarchical Cluster Analysis") +
                                                                                                                                                                                                                                                                                                                                       +     
                                                                                                                                                                                                                                                                                                                                       +     # Force strict 8pt sans-serif text geometries
                                                                                                                                                                                                                                                                                                                                       +     theme_minimal(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                       +     theme(
                                                                                                                                                                                                                                                                                                                                         +         axis.title.x     = element_blank(), 
                                                                                                                                                                                                                                                                                                                                         +         axis.text.x      = element_blank(),
                                                                                                                                                                                                                                                                                                                                         +         axis.grid.major  = element_blank(), # Clean White: Strips background lines
                                                                                                                                                                                                                                                                                                                                         +         axis.grid.minor  = element_blank(),
                                                                                                                                                                                                                                                                                                                                         +         panel.background = element_blank(),
                                                                                                                                                                                                                                                                                                                                         +         panel.border     = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                         +         plot.title       = element_text(size = 9, face = "plain", hjust = 0.5),
