                                                                                                                                                                                                                                                                                                                                                                              > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                            > # ---- Figure 6: Hierarchical Cluster Analysis (Dendrogram) Engine -------------
                                                                                                                                                                                                                                                                                                                                                                            > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                              > # 1. Compute distance and clustering vectors
                                                                                                                                                                                                                                                                                                                                                                              > dist_matrix <- dist(X_known, method = "euclidean")
                                                                                                                                                                                                                                                                                                                                                                            > hc <- hclust(dist_matrix, method = "ward.D2")
                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                              > # 2. Extract standard dendrogram segments
                                                                                                                                                                                                                                                                                                                                                                              > dendro_data <- dendro_data(hc, type = "rectangle")
                                                                                                                                                                                                                                                                                                                                                                            > segments_df <- segment(dendro_data)
                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                              > # 3. Isolate metadata labels and join species classifications
                                                                                                                                                                                                                                                                                                                                                                              > leaf_labels <- label(dendro_data) %>%
                                                                                                                                                                                                                                                                                                                                                                              +     mutate(spectrum = as.character(label)) %>%
                                                                                                                                                                                                                                                                                                                                                                              +     left_join(meta, by = "spectrum")
                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                              > # 4. CRITICAL LAYER: Identify and color-code the bottom vertical branch lines
                                                                                                                                                                                                                                                                                                                                                                              > # We isolate segments where yend == 0 (the bottom leaf endpoints) 
                                                                                                                                                                                                                                                                                                                                                                              > # and map them to their corresponding species class
                                                                                                                                                                                                                                                                                                                                                                              > segments_df <- segments_df %>%
                                                                                                                                                                                                                                                                                                                                                                              +     mutate(is_leaf_branch = (yend == 0 & y != yend)) %>%
                                                                                                                                                                                                                                                                                                                                                                              +     left_join(leaf_labels %>% select(x, class), by = c("x" = "x")) %>%
                                                                                                                                                                                                                                                                                                                                                                              +     mutate(branch_color = ifelse(is_leaf_branch & !is.na(class), as.character(class), "black"))
                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                              > # Separate segments into non-colored upper tree branches and color-coded bases
                                                                                                                                                                                                                                                                                                                                                                              > upper_tree  <- segments_df %>% filter(branch_color == "black")
                                                                                                                                                                                                                                                                                                                                                                            > colored_base <- segments_df %>% filter(branch_color != "black")
                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                              > # 5. Rendering the Clean, Gridless ACS Publication Dendrogram with Color Bases
                                                                                                                                                                                                                                                                                                                                                                              > p_dendrogram <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                              +     # Draw upper main tree architecture in uniform black lines
                                                                                                                                                                                                                                                                                                                                                                              +     geom_segment(data = upper_tree, 
                                                                                                                                                                                                                                                                                                                                                                                                 +                  aes(x = x, y = y, xend = xend, yend = yend), 
                                                                                                                                                                                                                                                                                                                                                                                                 +                  colour = "black", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                              +     # Draw bottom terminal leaf branches color-coded by botanical cultivar species
                                                                                                                                                                                                                                                                                                                                                                              +     geom_segment(data = colored_base, 
                                                                                                                                                                                                                                                                                                                                                                                                 +                  aes(x = x, y = y, xend = xend, yend = yend, colour = branch_color), 
                                                                                                                                                                                                                                                                                                                                                                                                 +                  linewidth = 0.6, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                              +     # Superimpose your sample leaf labels matching the color track perfectly
                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = leaf_labels, 
                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = spectrum, colour = class), 
                                                                                                                                                                                                                                                                                                                                                                                              +               hjust = 1.05, angle = 90, size = 1.8, fontfamily = "sans") +
                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_manual(values = c(class_cols, "black" = "black")) +
                                                                                                                                                                                                                                                                                                                                                                              +     scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                              +     labs(y = "Euclidean Distance", title = "Hierarchical Cluster Analysis") +
                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                              +     theme_minimal(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.x     = element_blank(), 
