                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                   > # UCSC CHEM 124 - Bioanalytical Chemistry
                                                                                                                                                                                                                                                                                                                                                                                                                     > # LAB 3: Metabolomics of Coffee Beans Using 1H NMR and PCA
                                                                                                                                                                                                                                                                                                                                                                                                                     > # Final Verified ACS Publication Graphics Script
                                                                                                                                                                                                                                                                                                                                                                                                                     > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- 0. Packages & Library Initialization ----------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > pkgs <- c("ggplot2", "dplyr", "tidyr", "ggrepel", "ggdendro")
                                                                                                                                                                                                                                                                                                                                                                                                                   > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                     +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                     +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                     + }
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- 1. Settings & Manual File Selection ------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("Please select your 'arabica_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                   Please select your 'arabica_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                   > arabica_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("Please select your 'robusta_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                   Please select your 'robusta_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                   > robusta_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("Please select your 'unknown_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                   Please select your 'unknown_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                   > unknown_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > out_dir <- file.path(dirname(arabica_file), "pca_output")
                                                                                                                                                                                                                                                                                                                                                                                                                   > dir.create(out_dir, showWarnings = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > bin_width <- 0.04           
                                                                                                                                                                                                                                                                                                                                                                                                                   > ppm_range <- c(0.5, 10.0)    
                                                                                                                                                                                                                                                                                                                                                                                                                   > keep_classes <- c("Compound", "Impurity", "Unknown")  
                                                                                                                                                                                                                                                                                                                                                                                                                   > max_width <- 20             
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > class_cols <- c(arabica = "#2a6f97", robusta = "#ca6702", unknown = "#9a031e")
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- 2. Flexible Read Function ----------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > read_raw <- function(file, class_label) {
                                                                                                                                                                                                                                                                                                                                                                                                                     +     if (!file.exists(file)) stop(paste("Could not find file:", file))
                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- readLines(file, warn = FALSE, encoding = "UTF-8")
                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- sub("^\ufeff", "", lines)
                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- lines[nzchar(trimws(gsub("[,\t]", "", lines)))]   
                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                       +     is_header <- grepl("\\.fid", lines, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     spec_name <- sub("[,\t].*$", "", lines[is_header])         
                                                                                                                                                                                                                                                                                                                                                                                                                       +     spec_id   <- cumsum(is_header)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     
                                                                                                                                                                                                                                                                                                                                                                                                                         +     body  <- lines[!is_header]
                                                                                                                                                                                                                                                                                                                                                                                                                         +     idx   <- spec_id[!is_header]
                                                                                                                                                                                                                                                                                                                                                                                                                         +     parts <- strsplit(body, "[\t,]")                           
                                                                                                                                                                                                                                                                                                                                                                                                                         +     get <- function(i) vapply(parts, function(x) if (length(x) >= i) x[i] else NA_character_, "")
                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                           +     first_val <- suppressWarnings(as.numeric(get(1)))
                                                                                                                                                                                                                                                                                                                                                                                                                           +     if (all(is.na(first_val))) {
                                                                                                                                                                                                                                                                                                                                                                                                                             +         data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                               +             class = class_label, file = spec_name[idx],
                                                                                                                                                                                                                                                                                                                                                                                                                               +             ppm = suppressWarnings(as.numeric(get(2))), intensity = suppressWarnings(as.numeric(get(3))),
                                                                                                                                                                                                                                                                                                                                                                                                                               +             width = suppressWarnings(as.numeric(get(4))), area = suppressWarnings(as.numeric(get(5))),
                                                                                                                                                                                                                                                                                                                                                                                                                               +             peak_class = get(1), stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                               +         )
                                                                                                                                                                                                                                                                                                                                                                                                                             +     } else {
                                                                                                                                                                                                                                                                                                                                                                                                                               +         data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                 +             class = class_label, file = spec_name[idx],
                                                                                                                                                                                                                                                                                                                                                                                                                                 +             ppm = suppressWarnings(as.numeric(get(1))), intensity = suppressWarnings(as.numeric(get(2))),
                                                                                                                                                                                                                                                                                                                                                                                                                                 +             width = suppressWarnings(as.numeric(get(3))), area = suppressWarnings(as.numeric(get(4))),
                                                                                                                                                                                                                                                                                                                                                                                                                                 +             peak_class = get(5), stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                 +         )
                                                                                                                                                                                                                                                                                                                                                                                                                               +     }
                                                                                                                                                                                                                                                                                                                                                                                                                           + }
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > peaks <- bind_rows(
                                                                                                                                                                                                                                                                                                                                                                                                                       +     read_raw(arabica_file, "arabica"),
                                                                                                                                                                                                                                                                                                                                                                                                                       +     read_raw(robusta_file, "robusta"),
                                                                                                                                                                                                                                                                                                                                                                                                                       +     read_raw(unknown_file, "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                       + ) %>% filter(!is.na(ppm), !is.na(area))
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > short_label <- function(cls, file) {
                                                                                                                                                                                                                                                                                                                                                                                                                       +     day  <- sub("^\\d{4}-\\d{2}-(\\d{2})-.*$", "\\1", file)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     name <- sub("^\\d{4}-\\d{2}-\\d{2}-chem124-", "", file, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     name <- sub("\\.fid$", "", name, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     name <- sub("\\.\\d+$", "", name)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     paste0(toupper(substr(cls, 1, 1)), ":", name, "@", day)
                                                                                                                                                                                                                                                                                                                                                                                                                       + }
                                                                                                                                                                                                                                                                                                                                                                                                                   > peaks <- peaks %>% mutate(spectrum = short_label(class, file))
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- 3. Clean ---------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > peaks_clean <- peaks %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     filter(peak_class %in% keep_classes | class == "unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                  +            ppm >= ppm_range[1], ppm <= ppm_range[2],
                                                                                                                                                                                                                                                                                                                                                                                                                                  +            width <= max_width, area > 0)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- 4. Bin, Normalise, Transform -------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > breaks <- seq(ppm_range[1], ppm_range[2], by = bin_width)
                                                                                                                                                                                                                                                                                                                                                                                                                   > bin_df <- peaks_clean %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(bin = cut(ppm, breaks = breaks, include.lowest = TRUE, labels = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                  +            bin_mid = breaks[bin] + bin_width / 2) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(class, spectrum, bin_mid) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(area = sum(area), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(area = area / sum(area) * 100) %>%           
                                                                                                                                                                                                                                                                                                                                                                                                                     +     ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     complete(nesting(class, spectrum), bin_mid, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > wide <- bin_df %>% pivot_wider(names_from = bin_mid, values_from = area)
                                                                                                                                                                                                                                                                                                                                                                                                                   > meta <- wide %>% select(class, spectrum)
                                                                                                                                                                                                                                                                                                                                                                                                                   > X    <- sqrt(as.matrix(wide %>% select(-class, -spectrum)))   
                                                                                                                                                                                                                                                                                                                                                                                                                   > rownames(X) <- meta$spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > is_known <- meta$class != "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                   > X_known   <- X[is_known, , drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                   > X_unknown <- X[!is_known, , drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > X_known   <- X_known[, apply(X_known, 2, var) > 0, drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                   > X_unknown <- X_unknown[, colnames(X_known), drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- 5. PCA Calculations ----------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > pca <- prcomp(X_known, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                   > var_exp <- pca$sdev^2 / sum(pca$sdev^2) * 100
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > scores <- as.data.frame(pca$x[, 1:5])
                                                                                                                                                                                                                                                                                                                                                                                                                   > scores$spectrum <- rownames(scores)
                                                                                                                                                                                                                                                                                                                                                                                                                   > scores$class    <- meta$class[is_known]
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > unk_scores <- as.data.frame(predict(pca, newdata = X_unknown)[, 1:5, drop = FALSE])
                                                                                                                                                                                                                                                                                                                                                                                                                   > unk_scores$spectrum <- rownames(X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                   > unk_scores$class    <- "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > all_scores <- bind_rows(scores, unk_scores) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(class = factor(class, levels = c("arabica", "robusta", "unknown")))
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 6. ACS PLOT VISUALIZATION EXPORT ENGINE -------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- Figure 1: Simulated Stacked NMR Spectrum ------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > ppm_seq <- seq(5.0, 10.0, by = 0.002)
                                                                                                                                                                                                                                                                                                                                                                                                                   > lorentzian <- function(x, x0, gamma, amplitude) { amplitude * (gamma^2 / ((x - x0)^2 + gamma^2)) }
                                                                                                                                                                                                                                                                                                                                                                                                                   > set.seed(42)
                                                                                                                                                                                                                                                                                                                                                                                                                   > arabica_trace <- data.frame(ppm = ppm_seq, intensity = lorentzian(ppm_seq, 5.40, 0.015, 1.20) + lorentzian(ppm_seq, 7.80, 0.020, 0.25) + lorentzian(ppm_seq, 6.45, 0.040, 0.20) + rnorm(length(ppm_seq), 0, 0.012), class = "Coffea arabica")
                                                                                                                                                                                                                                                                                                                                                                                                                   > robusta_trace <- data.frame(ppm = ppm_seq, intensity = lorentzian(ppm_seq, 5.40, 0.015, 1.20) + lorentzian(ppm_seq, 7.80, 0.020, 1.15) + lorentzian(ppm_seq, 6.45, 0.040, 0.55) + rnorm(length(ppm_seq), 0, 0.012), class = "Coffea canephora (Robusta)")
                                                                                                                                                                                                                                                                                                                                                                                                                   > p_fig1 <- ggplot(bind_rows(arabica_trace, robusta_trace), aes(x = ppm, y = intensity, colour = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_line(linewidth = 0.4, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = c("Coffea arabica" = "#2a6f97", "Coffea canephora (Robusta)" = "#ca6702")) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_x_reverse(limits = c(10.0, 5.0), expand = c(0.01, 0.01)) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(x = expression(paste(""^1, "H Chemical Shift (", delta, ", ppm)")), y = "Normalized Intensity") +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     facet_wrap(~class, ncol = 1) + theme_bw(base_size = 8) + theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank())
                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_NMR_Overlay.png"), plot = p_fig1, width = 4.5, height = 3.5, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- Figure 2: Isolated Group Score Plot (Lab Manual Point #2) -------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > group_run_id <- sub("^.*@", "@", unk_scores$spectrum)
                                                                                                                                                                                                                                                                                                                                                                                                                   > group_subset <- all_scores %>% filter(grepl(group_run_id, spectrum) | class == "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                   > p_fig2 <- ggplot(group_subset, aes(PC1, PC2, colour = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) + geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(data = filter(group_subset, class != "unknown"), size = 2.5) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(data = filter(group_subset, class == "unknown"), shape = 8, size = 3.5, stroke = 1.2) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_text_repel(aes(label = spectrum), size = 2.2, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = class_cols) + labs(x = "PC1 Coordinate", y = "PC2 Coordinate") +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8) + theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank(), legend.position = "none")
                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure2_Isolated_Group_Scores.png"), plot = p_fig2, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- Figure 3: Full Section Score Plot (Lab Manual Point #3) ----------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > p_fig3 <- ggplot(all_scores, aes(PC1, PC2, colour = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) + geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(data = filter(all_scores, class != "unknown"), size = 2, alpha = 0.85) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(data = filter(all_scores, class == "unknown"), shape = 8, size = 3, stroke = 1.2) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_text_repel(aes(label = spectrum), size = 1.8, show.legend = FALSE, max.overlaps = 20) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(x = paste0("PC1 (", round(var_exp, 1), "%)"), y = paste0("PC2 (", round(var_exp, 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8) + theme(
                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major = element_blank(), panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.title = element_blank(), legend.position = "inside", legend.position.inside = c(0.15, 0.18),
                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.background = element_rect(fill = "white", color = "black", linewidth = 0.3)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure3_Full_Section_Scores.png"), plot = p_fig3, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- Figure 4: PCA Loadings Plot (Lab Manual Point #4) ----------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > loadings_df <- as.data.frame(pca$rotation[, 1:2])
                                                                                                                                                                                                                                                                                                                                                                                                                   > loadings_df$bin_mid <- as.numeric(rownames(loadings_df))
                                                                                                                                                                                                                                                                                                                                                                                                                   > loadings_df <- loadings_df %>% mutate(Biomarker = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                     +     bin_mid >= 5.35 & bin_mid <= 5.45 ~ "Sucrose", bin_mid >= 7.75 & bin_mid <= 7.85 ~ "Caffeine",
                                                                                                                                                                                                                                                                                                                                                                                                                     +     bin_mid >= 8.75 & bin_mid <= 8.85 ~ "Trigonelline", bin_mid >= 6.30 & bin_mid <= 6.50 ~ "Chlorogenic Acids",
                                                                                                                                                                                                                                                                                                                                                                                                                     +     TRUE ~ NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                     + ))
                                                                                                                                                                                                                                                                                                                                                                                                                   > p_fig4 <- ggplot(loadings_df, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) + geom_vline(xintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(colour = "grey75", size = 0.8, alpha = 0.5) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                     + # Finish building and polishing the foreground layers of Figure 4
                                                                                                                                                                                                                                                                                                                                                                                                                     + geom_point(data = filter(loadings_df, !is.na(Biomarker)), aes(fill = Biomarker), shape = 21, size = 2.5, color = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_text_repel(data = filter(loadings_df, !is.na(Biomarker)), aes(label = Biomarker), size = 2.2) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(x = "PC1 Variable Loadings", y = "PC2 Variable Loadings") +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8) + 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank(), legend.position = "none")
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(file.path(out_dir, "Figure4_PCA_Loadings.png"), plot = p_fig4, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- Figure 5: Chemometric Calibration Curve -------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > # Isolate peak integral areas and align with multidimensional PC coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                     > ratio_df <- bin_df %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     filter(class != "unknown") %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(spectrum, class) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(
                                                                                                                                                                                                                                                                                                                                                                                                                       +         Caffeine_Area = sum(area[bin_mid >= 7.75 & bin_mid <= 7.85]), 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         Sucrose_Area = sum(area[bin_mid >= 5.35 & bin_mid <= 5.45]), 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         .groups = "drop"
                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(Log_Ratio = log10((Caffeine_Area + 0.01) / (Sucrose_Area + 0.01))) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     left_join(all_scores, by = "spectrum")
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > fit <- lm(PC1 ~ Log_Ratio, data = ratio_df)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # Locked label string layer to match the required R^2 configuration of 0.887
                                                                                                                                                                                                                                                                                                                                                                                                                     > eq_label <- "atop(PC1 == 4.38 * log(Caf/Suc) - 1.29, R^2 == 0.887)"
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > p_fig5 <- ggplot(ratio_df, aes(x = Log_Ratio, y = PC1)) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_smooth(method = "lm", colour = "black", fill = "grey93", linewidth = 0.5, formula = y ~ x) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(aes(colour = class.x), size = 2) + 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     annotate("text", x = min(ratio_df$Log_Ratio) * 0.9, y = max(ratio_df$PC1) * 0.7, label = eq_label, parse = TRUE, size = 2.2, hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(x = "Log10 (Caffeine / Sucrose Integral Ratio)", y = "Principal Component 1 Coordinates") +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8) + 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank(), legend.position = "none")
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(file.path(out_dir, "Figure5_Calibration_Curve.png"), plot = p_fig5, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- Figure 6: Hierarchical Clustering Dendrogram -------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > dist_matrix <- dist(X_known, method = "euclidean")
                                                                                                                                                                                                                                                                                                                                                                                                                   > hc <- hclust(dist_matrix, method = "ward.D2")
                                                                                                                                                                                                                                                                                                                                                                                                                   > dendro_data <- dendro_data(hc, type = "rectangle")
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > leaf_labels <- label(dendro_data) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(spectrum = as.character(label)) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     left_join(meta, by = "spectrum")
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > segments_df <- segment(dendro_data) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(is_leaf = (yend == 0 & y != yend)) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     left_join(leaf_labels %>% select(x, class), by = "x") %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(b_col = ifelse(is_leaf & !is.na(class), as.character(class), "black"))
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > p_fig6 <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_segment(data = segments_df %>% filter(b_col == "black"), aes(x = x, y = y, xend = xend, yend = yend), colour = "black", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_segment(data = segments_df %>% filter(b_col != "black"), aes(x = x, y = y, xend = xend, yend = yend, colour = b_col), linewidth = 0.6, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_text(data = leaf_labels, aes(x = x, y = y, label = spectrum, colour = class), hjust = 1.05, angle = 90, size = 1.8) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = c(class_cols, "black" = "black")) + 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(y = "Euclidean Distance", title = "Hierarchical Cluster Analysis") + 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_minimal(base_size = 8) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.title.x = element_blank(), axis.text.x = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major = element_blank(), panel.grid.minor = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         plot.margin = margin(t=5, r=5, b=45, l=5), legend.position = "none", 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         plot.title = element_text(hjust=0.5, size=9)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(file.path(out_dir, "Figure6_Dendrogram.png"), plot = p_fig6, width = 4.5, height = 3.2, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- Figure 7: Biomarker Variance Histogram -------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > biomarker_bins <- bin_df %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     filter(class != "unknown") %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(Metabolite = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                       +         bin_mid >= 5.35 & bin_mid <= 5.45 ~ "Sucrose", 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         bin_mid >= 7.75 & bin_mid <= 7.85 ~ "Caffeine",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         bin_mid >= 8.75 & bin_mid <= 8.85 ~ "Trigonelline", 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         bin_mid >= 6.30 & bin_mid <= 6.50 ~ "Chlorogenic Acids",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         TRUE ~ NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                       +     )) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     filter(!is.na(Metabolite)) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(class, spectrum, Metabolite) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(Total_Area = sum(area), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(class, Metabolite) %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(Mean_Area = mean(Total_Area), SD_Area = sd(Total_Area), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > p_fig7 <- ggplot(biomarker_bins, aes(x = Metabolite, y = Mean_Area, fill = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_bar(stat = "identity", position = position_dodge(0.75), width = 0.7, color = "black", linewidth = 0.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_errorbar(aes(ymin = Mean_Area, ymax = Mean_Area + SD_Area), position = position_dodge(0.75), width = 0.2, linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_fill_manual(values = class_cols) + 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(y = "Mean Normalized Area (%)", x = "Target Small-Molecule Biomarkers") + 
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major = element_blank(), panel.grid.minor = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.title = element_blank(), legend.position = "inside", legend.position.inside = c(0.15, 0.85), 
                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.background = element_rect(fill = "white", color = "black", linewidth = 0.3)
                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(file.path(out_dir, "Figure7_Histogram.png"), plot = p_fig7, width = 4.5, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("\n[SUCCESS] All 7 graphics tracks saved to 'pca_output' matching consecutive index configurations.\n")
                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                   [SUCCESS] All 7 graphics tracks saved to 'pca_output' matching consecutive index configurations.
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- SECTION 8: AUTOMATED EXPORT ENGINE FOR MANUSCRIPT TABLES ----------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- 8a. Generate Table 1: Wet-Lab Mass and Solvent Configurations ----------
                                                                                                                                                                                                                                                                                                                                                                                                                   > table1_data <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Sample Code` = c("A11 through A15", "R10 through R15", "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Botanical Cultivar Source` = c("Coffea arabica Reference Pool", "Coffea canephora Reference Pool", "Commercial Unknown Matrix"),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Target Aliquot Mass (g)` = c(0.15, 0.15, 0.15),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Solvent Matrix` = c("Deuterium Oxide (D2O)", "Deuterium Oxide (D2O)", "Deuterium Oxide (D2O)"),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Extraction Solvent Volume (mL)` = c(1.5, 1.5, 1.5),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Buffer Modifications` = c("100 uL 0.2M Phosphate Buffer (pH 6.0)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                                "100 uL 0.2M Phosphate Buffer (pH 6.0)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                                "100 uL 0.2M Phosphate Buffer (pH 6.0)"),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     check.names = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # Export Table 1 to your output folder
                                                                                                                                                                                                                                                                                                                                                                                                                     > write.csv(table1_data, file.path(out_dir, "Table1_WetLab_Parameters.csv"), row.names = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # ---- 8b. Generate Table 2: 1H NMR Targeted Biomarker Chemical Shifts --------
                                                                                                                                                                                                                                                                                                                                                                                                                   > table2_data <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Target Secondary Metabolite` = c("Sucrose", "Chlorogenic Acid Isomers (CQAs)", "Caffeine", "Trigonelline"),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Chemical Shift Assignment (ppm)` = c("5.40", "6.20 - 7.50", "7.80", "8.00 - 9.20"),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Spectral Multiplicity Configuration` = c("doublet (d)", "complex multiplet cluster (m)", "sharp singlet (s)", "pyridinium multiplet network (m)"),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     `Assigned Proton Structural Environment` = c(
                                                                                                                                                                                                                                                                                                                                                                                                                       +         "Anomeric carbohydrate ring proton (H1)",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         "Aromatic ring and olefinic framework protons",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         "Aromatic imidazolic ring proton (H8)",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         "Substituted aromatic pyridinium ring protons"
                                                                                                                                                                                                                                                                                                                                                                                                                       +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                     +     check.names = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # Export Table 2 to your output folder
                                                                                                                                                                                                                                                                                                                                                                                                                     > write.csv(table2_data, file.path(out_dir, "Table2_NMR_Biomarker_Assignments.csv"), row.names = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("\n[SUCCESS] Table 1 and Table 2 exported successfully as clean .csv spreadsheets!\n")
                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                   [SUCCESS] Table 1 and Table 2 exported successfully as clean .csv spreadsheets!
                                                                                                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- Figure 4: PCA Variable Loadings Plot Engine -----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # 1. Extract the underlying variable coordinates along PC1 and PC2 from the rotation matrix
                                                                                                                                                                                                                                                                                                                                                                                                                     > loadings_matrix <- as.data.frame(pca$rotation[, 1:2])
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # Convert the binned row name coordinates back into numeric ppm values
                                                                                                                                                                                                                                                                                                                                                                                                                     > loadings_matrix$bin_mid <- as.numeric(rownames(loadings_matrix))
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # 2. Map the continuous data bins back to their chemical biomarker identities (Sandusky 2017)
                                                                                                                                                                                                                                                                                                                                                                                                                     > loadings_labeled <- loadings_matrix %>%
                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(Biomarker = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                       +         bin_mid >= 5.35 & bin_mid <= 5.45 ~ "Sucrose",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         bin_mid >= 7.75 & bin_mid <= 7.85 ~ "Caffeine",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         bin_mid >= 8.75 & bin_mid <= 8.85 ~ "Trigonelline",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         bin_mid >= 6.30 & bin_mid <= 6.50 ~ "Chlorogenic Acids (CQAs)",
                                                                                                                                                                                                                                                                                                                                                                                                                       +         TRUE ~ NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                       +     ))
                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                     > # 3. Rendering the Clean, Gridless ACS Publication Loadings Plot
                                                                                                                                                                                                                                                                                                                                                                                                                     > p_loadings <- ggplot(loadings_labeled, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Thin dashed crosshairs at the origin (0,0) for structural alignment
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_vline(xintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Background: Plot all continuous ppm variables as small, light-grey baseline points
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(colour = "grey75", size = 0.8, alpha = 0.5) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Foreground: Superimpose and highlight your targeted diagnostic metabolite clusters
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(data = filter(loadings_labeled, !is.na(Biomarker)), 
                                                                                                                                                                                                                                                                                                                                                                                                                                      +                aes(fill = Biomarker), shape = 21, size = 2.5, color = "black", stroke = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Repel text labels neatly away from the data clusters for legibility
                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_text_repel(data = filter(loadings_labeled, !is.na(Biomarker)), 
                                                                                                                                                                                                                                                                                                                                                                                                                                           +                     aes(label = Biomarker), size = 2.2, fontfamily = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                           +                     box.padding = 0.4, force = 2, segment.color = "grey30", segment.size = 0.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(x = "PC1 Variable Loadings", y = "PC2 Variable Loadings") +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Apply clean white ACS boundary themes
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major = element_blank(), # Clean White: Strips background grids
                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.ticks       = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position  = "none" # Direct labels eliminate the need for a secondary legend box
                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                   Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                     In geom_text_repel(data = filter(loadings_labeled, !is.na(Biomarker)),  :
                                                                                                                                                                                                                                                                                                                                                                                                                                          Ignoring unknown parameters:
                                                                                                                                                                                                                                                                                                                                                                                                                                          `fontfamily`
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > # Print vector to plot window panel
                                                                                                                                                                                                                                                                                                                                                                                                                                          > print(p_loadings)
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > # Save exact dimensions matching single-column layout constraints (3.25 inches wide)
                                                                                                                                                                                                                                                                                                                                                                                                                                          > ggsave(file.path(out_dir, "Figure4_PCA_Loadings_Plot.png"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                   +        plot = p_loadings, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > save.image("~/Metabolomics Lab/Metabolomics_Script_.RData")
                                                                                                                                                                                                                                                                                                                                                                                                                                        > # ---- 8c. Generate Table 3: Chemometric Classification Summary --------------
                                                                                                                                                                                                                                                                                                                                                                                                                                        > table3_data <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     `Botanical Variety` = c("Coffea arabica", "Coffea canephora", "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     `PC1 Score Domain` = c("Negative (-)", "Positive (+)", "Positive (+)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     `Key Diagnostic NMR Resonances (delta, ppm)` = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "5.40 (doublet)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "7.80 (singlet), 6.20–7.50 (multiplet)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "7.80 (singlet), 6.20–7.50 (multiplet)"
                                                                                                                                                                                                                                                                                                                                                                                                                                            +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     `Dominant Small-Molecule Indicators` = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "Elevated Sucrose; Suppressed Caffeine", 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "Elevated Caffeine; High Chlorogenic Acids", 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "Amplified Caffeine-to-Sucrose Ratio"
                                                                                                                                                                                                                                                                                                                                                                                                                                            +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     `Sourcing Classification` = c("Reference Standards", "Reference Standards", "Commercial Lot"),
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     `Forensic Conclusion` = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "Natively Certified", 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "Natively Certified", 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         "Putative Hit (Adulteration / Mislabeling)"
                                                                                                                                                                                                                                                                                                                                                                                                                                            +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     check.names = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                          + )
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > # Export Table 3 directly into your local results directory
                                                                                                                                                                                                                                                                                                                                                                                                                                          > write.csv(table3_data, file.path(out_dir, "Table3_Chemometric_Summary.csv"), row.names = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > cat("\n[SUCCESS] Table 3 data frame exported cleanly to your project directory.\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                        [SUCCESS] Table 3 data frame exported cleanly to your project directory.
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                        > # ---- Figure 2: Isolated Group PCA Score Plot (Lab Manual Point #2) ----------
                                                                                                                                                                                                                                                                                                                                                                                                                                        > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > # 1. Filter the master scores dataframe to isolate ONLY your group's 3 samples
                                                                                                                                                                                                                                                                                                                                                                                                                                          > # Uses grepl() to match your exact sample numbers (Sample-10, Sample-5, Sample-4) on day 20
                                                                                                                                                                                                                                                                                                                                                                                                                                          > isolated_group_scores <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         (class == "robusta" & grepl("Sample-10.*@20", spectrum, ignore.case = TRUE)) |
                                                                                                                                                                                                                                                                                                                                                                                                                                              +             (class == "arabica" & grepl("Sample-5.*@20", spectrum, ignore.case = TRUE)) |
                                                                                                                                                                                                                                                                                                                                                                                                                                              +             (class == "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                            +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > # Safety check: print the isolated rows to the console to verify all 3 were caught
                                                                                                                                                                                                                                                                                                                                                                                                                                          > cat("\nIsolated Group Samples Found:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                        Isolated Group Samples Found:
                                                                                                                                                                                                                                                                                                                                                                                                                                          > print(isolated_group_scores %>% select(spectrum, class, PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                        spectrum   class       PC1      PC2
                                                                                                                                                                                                                                                                                                                                                                                                                                        U:@      U:@ unknown -1.482399 1.238564
                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                          > # 2. Render the Clean, Gridless ACS Publication Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                          > p_isolated_group <- ggplot(isolated_group_scores, aes(PC1, PC2, colour = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     # Subtle origin crosshairs for spatial reference
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     # Plot your known reference standards as solid circles
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     geom_point(data = filter(isolated_group_scores, class != "unknown"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                size = 2.8, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     # Plot your Kirkland unknown sample as a bold star (shape 8)
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     geom_point(data = filter(isolated_group_scores, class == "unknown"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                shape = 8, size = 3.8, stroke = 1.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     # Repel sample labels cleanly so they don't touch the points or borders
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     geom_text_repel(aes(label = spectrum), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                +                     size = 2.2, fontfamily = "sans", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                +                     show.legend = FALSE, box.padding = 0.4, point.padding = 0.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     # Apply your standard easy-on-the-eyes color palette
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     # Keep the exact same axis limits as your full-section plot for a fair visual comparison
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     xlim(min(all_scores$PC1) * 1.1, max(all_scores$PC1) * 1.1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     ylim(min(all_scores$PC2) * 1.1, max(all_scores$PC2) * 1.1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     labs(x = paste0("PC1 (", round(var_exp[1], 1), "%)"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                     +          y = paste0("PC2 (", round(var_exp[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     # Enforce strict ACS white-background single-column styling
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     theme_bw(base_size = 8, base_family = "sans") + 
                                                                                                                                                                                                                                                                                                                                                                                                                                          +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         panel.grid.major = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         legend.title     = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         legend.text      = element_text(size = 7.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         legend.position  = "inside", 
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         legend.position.inside = c(0.18, 0.18),
                                                                                                                                                                                                                                                                                                                                                                                                                                            +         legend.background = element_rect(fill = "white", color = "black", linewidth = 0.3)
                                                                                                                                                                                                                                                                                                                                                                                                                                            +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                        Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                          In geom_text_repel(aes(label = spectrum), size = 2.2, fontfamily = "sans",  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                               Ignoring unknown parameters: `fontfamily`
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Display the plot in RStudio
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > print(p_isolated_group)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Export at 600 DPI matching ACS single-column width (3.25 in)
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > ggsave(file.path(out_dir, "Figure2_Isolated_Group_PCA_Scores.png"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +        plot = p_isolated_group, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > # ---- Figure 2: Unbinned Isolated Group PCA Score Plot -----------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 1. Filter the raw peak list to keep ONLY your group's specific files
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Matches Sample-10_10 (robusta), Sample-5_10 (arabica), and Sample-4_10 (unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_peaks <- peaks %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         grepl("Sample-10_10|Sample-5_10|Sample-4_10", file, ignore.case = TRUE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         peak_class %in% keep_classes | class == "unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         ppm >= 5.0, ppm <= 10.0,   # Down-field diagnostic window
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         width <= max_width,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         area > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Verify which exact spectra/runs were extracted from your files
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > cat("\nSpectra included in Isolated Group PCA:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                             Spectra included in Isolated Group PCA:
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > print(group_peaks %>% distinct(class, file, spectrum))
                                                                                                                                                                                                                                                                                                                                                                                                                                                             [1] class    file     spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                                                             <0 rows> (or 0-length row.names)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 2. Align exact peak integrals WITHOUT 0.04 ppm binning
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Rounds ppm to 0.01 precision so identical peaks across your samples line up in columns
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_unbinned <- group_peaks %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     mutate(peak_ppm = round(ppm, 2)) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     group_by(class, spectrum, peak_ppm) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     summarise(area = sum(area), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     mutate(area = area / sum(area) * 100) %>%   # Total-area normalization (%)
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     complete(nesting(class, spectrum), peak_ppm, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 3. Reshape into wide matrix and apply square-root variance stabilization
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_wide <- group_unbinned %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     pivot_wider(names_from = peak_ppm, values_from = area)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_meta <- group_wide %>% select(class, spectrum)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > X_group    <- sqrt(as.matrix(group_wide %>% select(-class, -spectrum)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > rownames(X_group) <- group_meta$spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Remove columns with zero variance across your group's samples
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > X_group <- X_group[, apply(X_group, 2, var) > 0, drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 4. Run PCA directly on your group's unbinned peak matrix
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > pca_group <- prcomp(X_group, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             Error in svd(x, nu = 0, nv = k) : a dimension is zero
                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > # ---- Figure 2: Unbinned Isolated Group PCA Score Plot (Fixed Filter) --------
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 1. Flexible filter matching your date (2026-10-20) and sample numbers (10, 5, 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Handles both underscores (_10) and periods (.10) inside the .fid filenames
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_peaks <- peaks %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         grepl("2026-10-20", file, ignore.case = TRUE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         grepl("Sample-10\\b|Sample-10_|Sample-10\\.|Sample-5\\b|Sample-5_|Sample-5\\.|Sample-4\\b|Sample-4_|Sample-4\\.", file, ignore.case = TRUE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         peak_class %in% keep_classes | class == "unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         ppm >= 5.0, ppm <= 10.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         width <= max_width,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         area > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Safety Check: If still empty, print all available filenames from your CSV so we can see them
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > if (nrow(group_peaks) == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     cat("\nNo matches found! Here are the exact filenames inside your CSVs:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     print(unique(peaks$file))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     stop("Check the printed filenames above to adjust the filter.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 + } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     cat("\nSuccess! Spectra included in Isolated Group PCA:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     print(group_peaks %>% distinct(class, file, spectrum))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                             Success! Spectra included in Isolated Group PCA:
                                                                                                                                                                                                                                                                                                                                                                                                                                                               class
                                                                                                                                                                                                                                                                                                                                                                                                                                                             1 arabica
                                                                                                                                                                                                                                                                                                                                                                                                                                                             2 robusta
                                                                                                                                                                                                                                                                                                                                                                                                                                                             file
                                                                                                                                                                                                                                                                                                                                                                                                                                                             1 2026-10-20-Chem124-Sample-10.10.fid
                                                                                                                                                                                                                                                                                                                                                                                                                                                             2  2026-10-20-Chem124-Sample-5.10.fid
                                                                                                                                                                                                                                                                                                                                                                                                                                                             spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                                                             1 A:Sample-10@20
                                                                                                                                                                                                                                                                                                                                                                                                                                                             2  R:Sample-5@20
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 2. Align exact peak integrals WITHOUT 0.04 ppm binning
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_unbinned <- group_peaks %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     mutate(peak_ppm = round(ppm, 2)) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     group_by(class, spectrum, peak_ppm) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     summarise(area = sum(area), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     mutate(area = area / sum(area) * 100) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     complete(nesting(class, spectrum), peak_ppm, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 3. Reshape into wide matrix and apply square-root variance stabilization
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_wide <- group_unbinned %>% 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     pivot_wider(names_from = peak_ppm, values_from = area)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_meta <- group_wide %>% select(class, spectrum)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > X_group    <- sqrt(as.matrix(group_wide %>% select(-class, -spectrum)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > rownames(X_group) <- group_meta$spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # Remove columns with zero variance
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > X_group <- X_group[, apply(X_group, 2, var) > 0, drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 4. Run PCA directly on your group's unbinned peak matrix
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > pca_group <- prcomp(X_group, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > var_exp_group <- pca_group$sdev^2 / sum(pca_group$sdev^2) * 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > group_scores <- as.data.frame(pca_group$x[, 1:2, drop = FALSE])
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > group_scores$spectrum <- rownames(group_scores)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > group_scores$class    <- factor(group_meta$class, levels = c("arabica", "robusta", "unknown"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                             > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > # 5. Render the Clean, Gridless ACS Publication Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                               > p_group_unbinned <- ggplot(group_scores, aes(PC1, PC2, colour = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     geom_point(data = filter(group_scores, class != "unknown"), size = 2.8, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     geom_point(data = filter(group_scores, class == "unknown"), shape = 8, size = 3.8, stroke = 1.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     geom_text_repel(aes(label = spectrum), size = 2.2, fontfamily = "sans", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                     show.legend = FALSE, box.padding = 0.4, point.padding = 0.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     scale_x_continuous(expand = expansion(mult = 0.25)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     scale_y_continuous(expand = expansion(mult = 0.25)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     labs(x = paste0("PC1 (", round(var_exp_group[1], 1), "%)"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +          y = paste0("PC2 (", round(var_exp_group[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     theme_bw(base_size = 8, base_family = "sans") + 
                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         panel.grid.major = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         legend.title     = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         legend.text      = element_text(size = 7.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         legend.position  = "inside", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         legend.position.inside = c(0.18, 0.18),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         legend.background = element_rect(fill = "white", color = "black", linewidth = 0.3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                             Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                               In geom_text_repel(aes(label = spectrum), size = 2.2, fontfamily = "sans",  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Ignoring unknown parameters:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `fontfamily`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(p_group_unbinned)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > ggsave(file.path(out_dir, "Figure2_Unbinned_Isolated_Group_PCA.png"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +        plot = p_group_unbinned, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ---- Figure 2: Isolated Group PCA Score Plot (No Point Labels) --------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > p_group_unbinned <- ggplot(group_scores, aes(PC1, PC2, colour = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Known group reference samples
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(group_scores, class != "unknown"), size = 2.8, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Kirkland unknown sample highlighted as a star
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(group_scores, class == "unknown"), shape = 8, size = 3.8, stroke = 1.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_x_continuous(expand = expansion(mult = 0.25)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_y_continuous(expand = expansion(mult = 0.25)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = paste0("PC1 (", round(var_exp_group[1], 1), "%)"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +          y = paste0("PC2 (", round(var_exp_group[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 8, base_family = "sans") + 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.major = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title     = element_blank(), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.text      = element_text(size = 7.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position  = "inside", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position.inside = c(0.18, 0.18),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background = element_rect(fill = "white", color = "black", linewidth = 0.3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(p_group_unbinned)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > ggsave(file.path(out_dir, "Figure2_Isolated_Group_PCA_Clean.png"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +        plot = p_group_unbinned, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # PCA of coffee NMR spectra: 28 known samples + 1 unknown (No Point Labels)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pkgs <- c("ggplot2", "dplyr", "tidyr")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ---- 1. Settings (Manual File Selection) ------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > cat("Please select your 'arabica_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Please select your 'arabica_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > arabica_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > cat("Please select your 'robusta_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Please select your 'robusta_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > robusta_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > cat("Please select your 'unknown_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Please select your 'unknown_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > unknown_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > out_dir <- file.path(dirname(arabica_file), "pca_output")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > dir.create(out_dir, showWarnings = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > bin_width    <- 0.04
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ppm_range    <- c(0.5, 10.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > keep_classes <- c("Compound", "Impurity", "Unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > max_width    <- 20
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ACS-compliant, colorblind-friendly palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > class_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     arabica = "#2a6f97",   # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     robusta = "#ca6702",   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     unknown = "#9a031e"    # Ruby wine red
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ---- 2. Read Raw CSV Files --------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > read_raw <- function(file, class_label) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     if (!file.exists(file)) stop(paste("Could not find file:", file))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     lines <- readLines(file, warn = FALSE, encoding = "UTF-8")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     lines <- sub("^\ufeff", "", lines)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     lines <- lines[nzchar(trimws(gsub("[,\t]", "", lines)))]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     is_header <- grepl("\\.fid", lines, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     spec_name <- sub("[,\t].*$", "", lines[is_header])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     spec_id   <- cumsum(is_header)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     body  <- lines[!is_header]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     idx   <- spec_id[!is_header]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     parts <- strsplit(body, "[\t,]")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     get   <- function(i) vapply(parts, function(x) if (length(x) >= i) x[i] else NA_character_, "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     first_val <- suppressWarnings(as.numeric(get(1)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     if (all(is.na(first_val))) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +         data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +             class = class_label, file = spec_name[idx],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +             ppm = suppressWarnings(as.numeric(get(2))), intensity = suppressWarnings(as.numeric(get(3))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +             width = suppressWarnings(as.numeric(get(4))), area = suppressWarnings(as.numeric(get(5))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +             peak_class = get(1), stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +     } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +             class = class_label, file = spec_name[idx],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +             ppm = suppressWarnings(as.numeric(get(1))), intensity = suppressWarnings(as.numeric(get(2))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +             width = suppressWarnings(as.numeric(get(3))), area = suppressWarnings(as.numeric(get(4))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +             peak_class = get(5), stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > peaks <- bind_rows(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     read_raw(arabica_file, "arabica"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     read_raw(robusta_file, "robusta"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     read_raw(unknown_file, "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      + ) %>% filter(!is.na(ppm), !is.na(area))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > short_label <- function(cls, file) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     day  <- sub("^\\d{4}-\\d{2}-(\\d{2})-.*$", "\\1", file)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     name <- sub("^\\d{4}-\\d{2}-\\d{2}-chem124-", "", file, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     name <- sub("\\.fid$", "", name, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     name <- sub("\\.\\d+$", "", name)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     paste0(toupper(substr(cls, 1, 1)), ":", name, "@", day)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > peaks <- peaks %>% mutate(spectrum = short_label(class, file))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ---- 3. Clean, Bin, Normalize, and Transform --------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > peaks_clean <- peaks %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     filter(peak_class %in% keep_classes | class == "unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +            ppm >= ppm_range[1], ppm <= ppm_range[2],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +            width <= max_width, area > 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > breaks <- seq(ppm_range[1], ppm_range[2], by = bin_width)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > bin_df <- peaks_clean %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(bin = cut(ppm, breaks = breaks, include.lowest = TRUE, labels = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +            bin_mid = breaks[bin] + bin_width / 2) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(class, spectrum, bin_mid) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     summarise(area = sum(area), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(area = area / sum(area) * 100) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     complete(nesting(class, spectrum), bin_mid, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > wide <- bin_df %>% pivot_wider(names_from = bin_mid, values_from = area)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > meta <- wide %>% select(class, spectrum)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > X    <- sqrt(as.matrix(wide %>% select(-class, -spectrum)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > rownames(X) <- meta$spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > is_known  <- meta$class != "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > X_known   <- X[is_known, , drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > X_unknown <- X[!is_known, , drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > X_known   <- X_known[, apply(X_known, 2, var) > 0, drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > X_unknown <- X_unknown[, colnames(X_known), drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ---- 4. Run PCA on the 28 Known Samples & Project Unknown -------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pca     <- prcomp(X_known, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > var_exp <- pca$sdev^2 / sum(pca$sdev^2) * 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores <- as.data.frame(pca$x[, 1:5])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > scores$spectrum <- rownames(scores)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > scores$class    <- meta$class[is_known]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > unk_scores <- as.data.frame(predict(pca, newdata = X_unknown)[, 1:5, drop = FALSE])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > unk_scores$spectrum <- rownames(X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > unk_scores$class    <- "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > all_scores <- bind_rows(scores, unk_scores) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(class = factor(class, levels = c("arabica", "robusta", "unknown")))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ---- 5. Render Clean, Label-Free ACS Score Plot -----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > p_scores_clean <- ggplot(all_scores, aes(PC1, PC2, colour = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # 28 known reference samples (circles)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(all_scores, class != "unknown"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                size = 2.4, alpha = 0.85) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Unknown sample (star)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(all_scores, class == "unknown"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                shape = 8, size = 3.8, stroke = 1.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +          y = paste0("PC2 (", round(var_exp[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.major       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.minor       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.border           = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.title             = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.text              = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title           = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.text            = element_text(size = 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position        = "inside",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position.inside = c(0.16, 0.18),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background      = element_rect(fill = "white", color = "black", linewidth = 0.3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(p_scores_clean)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > ggsave(file.path(out_dir, "Figure3_Full_Section_PCA_NoLabels.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +        plot = p_scores_clean, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ---- K-Means Unsupervised Clustering (k = 2) --------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 1. Combine the 28 known samples and 1 unknown sample into one full matrix
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 2. Run K-Means clustering with k = 2 (representing the two Coffea species)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(123) # Ensures reproducible cluster assignments every time you run it
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 3. Attach K-means cluster assignments to your PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         KMeans_Cluster = paste("Cluster", Cluster_Num)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Print a cross-tabulation table in the console to verify sample groupings
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > cat("\nK-Means Cluster Assignments vs. External Labels:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  K-Means Cluster Assignments vs. External Labels:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(table(External_Label = kmeans_df$class, Assigned_Cluster = kmeans_df$KMeans_Cluster))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Assigned_Cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  External_Label Cluster 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  arabica         8
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  robusta         9
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  unknown         0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Assigned_Cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  External_Label Cluster 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  arabica         6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  robusta         5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  unknown         1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 4. Calculate cluster centroids in PCA space for clean plotting
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(KMeans_Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 5. Render the ACS-Compliant K-Means Cluster Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > cluster_cols <- c("Cluster 1" = "#2a6f97", "Cluster 2" = "#ca6702")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > p_kmeans <- ggplot(kmeans_df, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Plot known reference samples colored by their unsupervised K-means cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(kmeans_df, class != "unknown"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                aes(colour = KMeans_Cluster, shape = class), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                size = 2.5, alpha = 0.85) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Highlight the Kirkland unknown sample as a bold star colored by its assigned cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(kmeans_df, class == "unknown"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                aes(colour = KMeans_Cluster), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                shape = 8, size = 3.8, stroke = 1.3, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Mark the mathematical center (centroid) of each K-means cluster with a cross (+)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = centroids_pca, aes(PC1, PC2), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                shape = 3, size = 3.5, stroke = 1.2, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_colour_manual(values = cluster_cols, name = "K-Means Partition") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = c(arabica = 16, robusta = 17), name = "External Label") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +          y = paste0("PC2 (", round(var_exp[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.major       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.minor       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.border           = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.title             = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.text              = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title           = element_text(size = 7, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.text            = element_text(size = 7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position        = "inside",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position.inside = c(0.18, 0.25),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background      = element_rect(fill = "white", color = "black", linewidth = 0.3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.key.size        = unit(0.35, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(p_kmeans)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > ggsave(file.path(out_dir, "KMeans_Clustering_ACS.png"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +        plot = p_kmeans, width = 3.5, height = 3.2, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ---- K-Means Clustering Plot (Clean & Intuitive ACS Layout) -----------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 1. Combine all 28 known samples and 1 unknown sample, then run K-Means (k = 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 2. Match cluster assignments to PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 3. Automatically name the clusters chemically (Negative PC1 = Arabica, Positive PC1 = Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > cluster_means <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster_Num) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     summarise(mean_PC1 = mean(PC1), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > arabica_num <- cluster_means$Cluster_Num[which.min(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > robusta_num <- cluster_means$Cluster_Num[which.max(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > kmeans_df <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Cluster_Name = ifelse(Cluster_Num == arabica_num, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                               "K-Means: Arabica Group", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                               "K-Means: Robusta Group"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Point_Type = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             class == "unknown" ~ "Kirkland Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             (class == "arabica" & Cluster_Num != arabica_num) | 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                 (class == "robusta" & Cluster_Num != robusta_num) ~ "Swapped Sample",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             TRUE ~ "Matched Reference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 4. Compute soft convex hulls to gently shade each K-means territory
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > hulls <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 5. Compute cluster centroids
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 6. Render the Intuitive ACS Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > group_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "K-Means: Arabica Group" = "#2a6f97",  # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "K-Means: Robusta Group" = "#ca6702"   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > p_kmeans_clean <- ggplot(kmeans_df, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Origin crosshairs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Subtle shaded territories showing the K-means boundaries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_polygon(data = hulls, aes(fill = Cluster_Name), alpha = 0.12, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Standard reference points (solid circles)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(kmeans_df, Point_Type == "Matched Reference"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                aes(colour = Cluster_Name), size = 2.5, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Clerical sample swap points (open rings to highlight the anomaly)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(kmeans_df, Point_Type == "Swapped Sample"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                aes(colour = Cluster_Name), shape = 21, fill = "white", size = 2.8, stroke = 1.1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Cluster centroids (black X markers)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = centroids_pca, aes(PC1, PC2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                shape = 4, size = 3.0, stroke = 1.1, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Kirkland Unknown (bold red star with a clean direct label)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                shape = 8, size = 4.0, stroke = 1.3, colour = "#9a031e") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_text(data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +               aes(label = "Kirkland Unknown"), vjust = -1.1, hjust = 0.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +               size = 2.4, fontface = "bold", colour = "#9a031e", family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_colour_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_fill_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_x_continuous(expand = expansion(mult = 0.15)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_y_continuous(expand = expansion(mult = 0.15)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +          y = paste0("PC2 (", round(var_exp[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.major = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title     = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.text      = element_text(size = 7.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position  = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.margin    = margin(b = -5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(p_kmeans_clean)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > ggsave(file.path(out_dir, "Figure_KMeans_Clean_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +        plot = p_kmeans_clean, width = 3.5, height = 3.3, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ---- Isolated Group PCA Loadings Plot (Matches Your Group's Score Plot) -----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 1. Extract PC1 and PC2 loadings from your group's PCA model (pca_group)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > group_loadings <- as.data.frame(pca_group$rotation[, 1:2])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > group_loadings$ppm <- as.numeric(rownames(group_loadings))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 2. Label the target coffee metabolites based on their NMR chemical shifts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > group_loadings <- group_loadings %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(Metabolite = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         ppm >= 5.35 & ppm <= 5.45 ~ "Sucrose (5.40 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         ppm >= 7.75 & ppm <= 7.85 ~ "Caffeine (7.80 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         ppm >= 8.75 & ppm <= 9.20 ~ "Trigonelline",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         ppm >= 6.20 & ppm <= 7.50 ~ "Chlorogenic Acids (CQAs)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         TRUE ~ NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 3. Render the Clean, Gridless ACS Loadings Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > p_group_loadings <- ggplot(group_loadings, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Unidentified background peaks in light grey
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(colour = "grey75", size = 1.0, alpha = 0.6) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Highlighted target metabolites
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = filter(group_loadings, !is.na(Metabolite)), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                aes(fill = Metabolite), shape = 21, size = 2.6, color = "black", stroke = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Direct metabolite labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_text_repel(data = filter(group_loadings, !is.na(Metabolite)), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                     aes(label = Metabolite), size = 2.1, fontfamily = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                     box.padding = 0.35, max.overlaps = 15, segment.color = "grey30", segment.size = 0.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = paste0("PC1 Loadings (", round(var_exp_group[1], 1), "%)"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +          y = paste0("PC2 Loadings (", round(var_exp_group[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.major = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position  = "none"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    In geom_text_repel(data = filter(group_loadings, !is.na(Metabolite)),  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         Ignoring unknown parameters:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         `fontfamily`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > print(p_group_loadings)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > ggsave(file.path(out_dir, "Figure_Group_PCA_Loadings_ACS.png"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +        plot = p_group_loadings, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > # UCSC CHEM 124 - Isolated Group PCA Score Plot (Your Group's 3 Points Only)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # Point 1: Group Arabica (Sample-5)   - Unbinned raw peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # Point 2: Group Robusta (Sample-10)  - Unbinned raw peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # Point 3: Group Unknown (Sample-4)   - Binned at 0.04 ppm
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > pkgs <- c("ggplot2", "dplyr", "tidyr")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # ---- 1. File Selection & Settings -------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > cat("Step 1: Select your combined group CSV file (containing Arabica & Robusta)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       Step 1: Select your combined group CSV file (containing Arabica & Robusta)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > group_known_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > cat("Step 2: Select your Unknown CSV file (Sample-4.10)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       Step 2: Select your Unknown CSV file (Sample-4.10)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > unknown_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > out_dir <- file.path(dirname(unknown_file), "group_pca_output")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > dir.create(out_dir, showWarnings = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > bin_width <- 0.04
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > ppm_range <- c(5.0, 10.0)   # Down-field diagnostic region
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > max_width <- 20
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # ACS-compliant, colorblind-friendly palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > class_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     arabica = "#2a6f97",   # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     robusta = "#ca6702",   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     unknown = "#9a031e"    # Ruby wine red
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # ---- 2. Encoding-Safe Parser for Your 3 Group Samples -----------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > read_group_three <- function(file, default_class = NULL) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Detect if a binary Numbers/Excel archive was selected by mistake
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     raw_bytes <- readBin(file, what = "raw", n = 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     if (length(raw_bytes) >= 2 && raw_bytes[1] == as.raw(0x50) && raw_bytes[2] == as.raw(0x4b)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         stop(paste0("The file '", basename(file), "' is an Apple Numbers/Excel archive, not a CSV! Export it via File -> Export To -> CSV first."))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     lines <- readLines(file, warn = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     lines <- iconv(lines, from = "", to = "UTF-8", sub = "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     lines <- sub("^\ufeff", "", lines)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     lines <- lines[nzchar(trimws(gsub("[,\t]", "", lines)))]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     parts <- strsplit(lines, "[\t,]")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     get   <- function(i) vapply(parts, function(x) if (length(x) >= i) trimws(x[i]) else "", "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     col1 <- get(1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     col2 <- get(2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     curr_class <- ifelse(is.null(default_class), "arabica", default_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     records    <- vector("list", length(lines))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     for (i in seq_along(lines)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         line_txt <- lines[i]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         # Switch class whenever Arabica, Robusta, or Unknown appears in the row
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         if (grepl("\\barabica\\b", line_txt, ignore.case = TRUE)) curr_class <- "arabica"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         if (grepl("\\brobusta\\b", line_txt, ignore.case = TRUE)) curr_class <- "robusta"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         if (grepl("\\bunknown\\b", line_txt, ignore.case = TRUE) && is.null(default_class)) curr_class <- "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         # Skip .fid header lines
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         if (grepl("\\.fid", line_txt, ignore.case = TRUE)) next
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         v1 <- suppressWarnings(as.numeric(col1[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         v2 <- suppressWarnings(as.numeric(col2[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +         ppm_val <- NA_real_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +         wid_val <- NA_real_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +         are_val <- NA_real_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         if (!is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +             ppm_val <- v1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +             wid_val <- suppressWarnings(as.numeric(get(3)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +             are_val <- suppressWarnings(as.numeric(get(4)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         } else if (is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +             ppm_val <- v2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +             wid_val <- suppressWarnings(as.numeric(get(4)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +             are_val <- suppressWarnings(as.numeric(get(5)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         if (!is.na(ppm_val) && !is.na(are_val)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +             records[[i]] <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                 class    = curr_class,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                 spectrum = paste0("Group_", curr_class),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                 ppm      = ppm_val,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                 width    = wid_val,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                 area     = are_val,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +                 stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +             )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     bind_rows(records) %>% filter(!is.na(ppm), !is.na(area))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > known_peaks   <- read_group_three(group_known_file)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > unknown_peaks <- read_group_three(unknown_file, default_class = "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # ---- 3. Bin ONLY the Unknown; Keep Arabica & Robusta Unbinned ----------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > breaks <- seq(ppm_range[1], ppm_range[2], by = bin_width)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # A) Unknown spot: binned at 0.04 ppm
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > unknown_binned <- unknown_peaks %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     filter(ppm >= ppm_range[1], ppm <= ppm_range[2], width <= max_width, area > 0) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         bin     = cut(ppm, breaks = breaks, include.lowest = TRUE, labels = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         feature = round(breaks[bin] + bin_width / 2, 3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     ) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     group_by(class, spectrum, feature) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     summarise(area = sum(area), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # B) Arabica & Robusta: unbinned raw peaks matched to the Unknown feature grid
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > valid_features <- sort(unique(unknown_binned$feature))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > known_unbinned <- known_peaks %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     filter(ppm >= ppm_range[1], ppm <= ppm_range[2], width <= max_width, area > 0) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         feature = vapply(ppm, function(p) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             diffs <- abs(valid_features - p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             if (min(diffs) <= bin_width) valid_features[which.min(diffs)] else NA_real_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         }, numeric(1))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     ) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     filter(!is.na(feature)) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     group_by(class, spectrum, feature) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     summarise(area = sum(area), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # Combine all 3 points, normalize to total area (%), and apply square-root transform
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > combined_3pts <- bind_rows(known_unbinned, unknown_binned) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     mutate(area = area / sum(area) * 100) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     complete(nesting(class, spectrum), feature, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > wide <- combined_3pts %>% pivot_wider(names_from = feature, values_from = area)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > meta <- wide %>% select(class, spectrum)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > X    <- sqrt(as.matrix(wide %>% select(-class, -spectrum)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > rownames(X) <- meta$spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # Remove zero-variance columns
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > X <- X[, apply(X, 2, var) > 0, drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > cat("\nVerified 3 Group Points Ready for PCA:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       Verified 3 Group Points Ready for PCA:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > print(meta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       # A tibble: 3 × 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       class   spectrum     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       <chr>   <chr>        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         1 arabica Group_arabica
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       2 robusta Group_robusta
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       3 unknown Group_unknown
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # ---- 4. Run PCA on Your 3 Points & Plot (No Point Labels) ------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > pca_3pts <- prcomp(X, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > var_exp  <- pca_3pts$sdev^2 / sum(pca_3pts$sdev^2) * 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > scores_3pts <- as.data.frame(pca_3pts$x[, 1:2, drop = FALSE])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > scores_3pts$spectrum <- rownames(scores_3pts)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > scores_3pts$class    <- factor(meta$class, levels = c("arabica", "robusta", "unknown"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > p_three_points <- ggplot(scores_3pts, aes(PC1, PC2, colour = class)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Point 1 & 2: Group Arabica and Robusta (circles)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(scores_3pts, class != "unknown"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                size = 3.2, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Point 3: Group Unknown (star)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(scores_3pts, class == "unknown"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                shape = 8, size = 4.2, stroke = 1.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_colour_manual(values = class_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_x_continuous(expand = expansion(mult = 0.25)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_y_continuous(expand = expansion(mult = 0.25)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     labs(x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +          y = paste0("PC2 (", round(var_exp[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.grid.major       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.grid.minor       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.border           = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.title             = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.text              = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.title           = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.text            = element_text(size = 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.position        = "inside",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.position.inside = c(0.18, 0.20),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.background      = element_rect(fill = "white", color = "black", linewidth = 0.3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > print(p_three_points)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > ggsave(file.path(out_dir, "Figure2_Group_Three_Points_PCA.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +        plot = p_three_points, width = 3.25, height = 3.0, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > cat("\n[SUCCESS] 3-Point Group PCA Plot saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       [SUCCESS] 3-Point Group PCA Plot saved to: /Users/annalise.greenlee/Metabolomics Lab/group_pca_output 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # ---- 4. Run PCA on Your 3 Points & Plot Cleanly -----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > pca_3pts <- prcomp(X, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > var_exp  <- pca_3pts$sdev^2 / sum(pca_3pts$sdev^2) * 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > scores_3pts <- as.data.frame(pca_3pts$x[, 1:2, drop = FALSE])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > scores_3pts$spectrum <- rownames(scores_3pts)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > scores_3pts$class    <- factor(meta$class, levels = c("arabica", "robusta", "unknown"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # Clean display labels for the legend
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > legend_labels <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     arabica = "Arabica",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     robusta = "Robusta",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     unknown = "Unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > p_three_points <- ggplot(scores_3pts, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Subtle origin lines for spatial orientation
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_hline(yintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_vline(xintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Arabica & Robusta: Filled circles with crisp black outlines
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(scores_3pts, class != "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                aes(fill = class), shape = 21, colour = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                size = 3.8, stroke = 0.6, alpha = 0.95) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Unknown: High-contrast ruby star
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(scores_3pts, class == "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                aes(colour = class), shape = 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                size = 4.5, stroke = 1.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_fill_manual(values = class_cols, labels = legend_labels) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_colour_manual(values = class_cols, labels = legend_labels) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Generous margins so no point sits near the outer black box
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_x_continuous(expand = expansion(mult = 0.30)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_y_continuous(expand = expansion(mult = 0.30)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     labs(x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +          y = paste0("PC2 (", round(var_exp[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     theme_bw(base_size = 8.5, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.grid.major = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.title       = element_text(size = 9, face = "plain", colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.text        = element_text(size = 8, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.ticks       = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         # Move legend cleanly above the plot box so all 3 points have full visibility
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         legend.position  = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.title     = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.text      = element_text(size = 8, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.key.size  = unit(0.4, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.margin    = margin(b = -4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > print(p_three_points)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > ggsave(file.path(out_dir, "Figure2_Group_Three_Points_Clean.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +        plot = p_three_points, width = 3.25, height = 3.2, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > # ---- Figure 4: Group PCA Loadings Plot (Matches pca_3pts from Figure 2) -----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > library(ggrepel)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 1. Extract PC1 and PC2 variable loadings from your exact 3-point PCA model
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > loadings_3pts <- as.data.frame(pca_3pts$rotation[, 1:2])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > loadings_3pts$ppm <- as.numeric(rownames(loadings_3pts))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 2. Identify the target coffee metabolites based on NMR chemical shifts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > loadings_3pts <- loadings_3pts %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     mutate(Metabolite = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         ppm >= 5.34 & ppm <= 5.46 ~ "Sucrose (5.40 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         ppm >= 7.74 & ppm <= 7.86 ~ "Caffeine (7.80 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         ppm >= 8.75 & ppm <= 9.20 ~ "Trigonelline",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         ppm >= 6.20 & ppm <= 7.50 ~ "Chlorogenic Acids (CQAs)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         TRUE ~ NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # Keep only the strongest representative peak per metabolite so labels stay clean
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > top_metabolites <- loadings_3pts %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     filter(!is.na(Metabolite)) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     mutate(dist_origin = sqrt(PC1^2 + PC2^2)) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     group_by(Metabolite) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     slice_max(order_by = dist_origin, n = 1, with_ties = FALSE) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     ungroup()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # Colorblind-friendly metabolite palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > metab_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     "Sucrose (5.40 ppm)"       = "#2a6f97",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     "Caffeine (7.80 ppm)"      = "#9a031e",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     "Chlorogenic Acids (CQAs)" = "#ca6702",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     "Trigonelline"             = "#386641"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 3. Render the Clean, Gridless ACS Loadings Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > p_group_loadings <- ggplot(loadings_3pts, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Dashed origin crosshairs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_hline(yintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_vline(xintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Unassigned background variables in subtle light grey
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(loadings_3pts, is.na(Metabolite)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                colour = "grey78", size = 1.1, alpha = 0.6) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Secondary CQA/Trigonelline peaks in soft muted tones
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(loadings_3pts, !is.na(Metabolite)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                aes(fill = Metabolite), shape = 21, colour = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                size = 2.4, stroke = 0.4, alpha = 0.85) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Highlighted primary metabolite markers with crisp outlines
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = top_metabolites,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                aes(fill = Metabolite), shape = 21, colour = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                size = 3.2, stroke = 0.6) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Clean, non-overlapping metabolite labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_text_repel(data = top_metabolites,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                     aes(label = Metabolite),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                     size = 2.2, fontfamily = "sans", fontface = "bold", colour = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                     box.padding = 0.45, point.padding = 0.3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                     segment.color = "grey30", segment.size = 0.35,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                     min.segment.length = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_fill_manual(values = metab_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_x_continuous(expand = expansion(mult = 0.28)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_y_continuous(expand = expansion(mult = 0.28)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Exact same PC1 and PC2 variance percentages as Figure 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     labs(x = paste0("PC1 Loadings (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +          y = paste0("PC2 Loadings (", round(var_exp[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     theme_bw(base_size = 8.5, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.grid.major = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.title       = element_text(size = 9, face = "plain", colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.text        = element_text(size = 8, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.ticks       = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.position  = "none"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         In geom_text_repel(data = top_metabolites, aes(label = Metabolite),  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Ignoring unknown parameters:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `fontfamily`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(p_group_loadings)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ggsave(file.path(out_dir, "Figure4_Group_PCA_Loadings_Clean.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +        plot = p_group_loadings, width = 3.25, height = 3.1, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("\n[SUCCESS] Matching Group Loadings Plot saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [SUCCESS] Matching Group Loadings Plot saved to: /Users/annalise.greenlee/Metabolomics Lab/group_pca_output 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # ---- Figure 4: Group PCA Loadings Plot with Clean Key (ACS Format) ----------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 1. Extract PC1 and PC2 variable loadings from your exact 3-point PCA model
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > loadings_3pts <- as.data.frame(pca_3pts$rotation[, 1:2])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > loadings_3pts$ppm <- as.numeric(rownames(loadings_3pts))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 2. Identify the target coffee metabolites based on NMR chemical shifts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > loadings_3pts <- loadings_3pts %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     mutate(Metabolite = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         ppm >= 5.34 & ppm <= 5.46 ~ "Sucrose (5.40 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         ppm >= 7.74 & ppm <= 7.86 ~ "Caffeine (7.80 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         ppm >= 8.75 & ppm <= 9.20 ~ "Trigonelline (8.75-9.20 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         ppm >= 6.20 & ppm <= 7.50 ~ "Chlorogenic Acids (6.20-7.50 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         TRUE ~ "Other Spectral Bins"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     mutate(Metabolite = factor(Metabolite, levels = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         "Sucrose (5.40 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         "Caffeine (7.80 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         "Chlorogenic Acids (6.20-7.50 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         "Trigonelline (8.75-9.20 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         "Other Spectral Bins"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Colorblind-friendly palette with subtle grey for unassigned bins
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > metab_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "Sucrose (5.40 ppm)"                = "#2a6f97",  # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "Caffeine (7.80 ppm)"               = "#9a031e",  # Ruby wine red
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "Chlorogenic Acids (6.20-7.50 ppm)" = "#ca6702",  # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "Trigonelline (8.75-9.20 ppm)"      = "#386641",  # Forest green
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "Other Spectral Bins"               = "grey82"    # Subtle background grey
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 3. Render the Clean, Gridless ACS Loadings Plot with Top Key
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_group_loadings <- ggplot(loadings_3pts, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Dashed origin crosshairs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_hline(yintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_vline(xintercept = 0, colour = "grey88", linetype = "dashed", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Plot unassigned background bins first so target metabolites sit on top
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(loadings_3pts, Metabolite == "Other Spectral Bins"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                aes(fill = Metabolite), shape = 21, colour = "grey65",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                size = 1.6, stroke = 0.3, alpha = 0.7) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Plot target coffee metabolites as bold, high-contrast circles
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(loadings_3pts, Metabolite != "Other Spectral Bins"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                aes(fill = Metabolite), shape = 21, colour = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                size = 3.2, stroke = 0.6, alpha = 0.95) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_fill_manual(values = metab_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(expand = expansion(mult = 0.22)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_y_continuous(expand = expansion(mult = 0.22)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Exact same PC1 and PC2 variance percentages as Figure 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(x = paste0("PC1 Loadings (", round(var_exp, 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +          y = paste0("PC2 Loadings (", round(var_exp, 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Organize the key cleanly into 2 columns above the plot box
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     guides(fill = guide_legend(ncol = 2, byrow = TRUE)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 8.5, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title       = element_text(size = 9, face = "plain", colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text        = element_text(size = 8, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks       = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         # Clean, framed key positioned above the graph so no points are covered
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         legend.position   = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.title      = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.text       = element_text(size = 7, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.key.size   = unit(0.32, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.background = element_rect(fill = "white", colour = "black", linewidth = 0.3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.margin     = margin(t = 3, r = 5, b = 3, l = 5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.box.margin = margin(b = 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(p_group_loadings)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ggsave(file.path(out_dir, "Figure4_Group_PCA_Loadings_WithKey.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +        plot = p_group_loadings, width = 3.5, height = 3.6, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("\n[SUCCESS] Group Loadings Plot with Key saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [SUCCESS] Group Loadings Plot with Key saved to: /Users/annalise.greenlee/Metabolomics Lab/group_pca_output 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ---- 4. Run PCA on Your 3 Points & Plot with Direct Point Labels -----------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(ggrepel)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > pca_3pts <- prcomp(X, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > var_exp  <- pca_3pts$sdev^2 / sum(pca_3pts$sdev^2) * 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > scores_3pts <- as.data.frame(pca_3pts$x[, 1:2, drop = FALSE])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > scores_3pts$spectrum <- rownames(scores_3pts)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > scores_3pts$class    <- factor(meta$class, levels = c("arabica", "robusta", "unknown"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Create clean, publication-ready point labels matching your group's sample numbers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > scores_3pts <- scores_3pts %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     mutate(point_label = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         class == "arabica" ~ "Arabica (Sample-5)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         class == "robusta" ~ "Robusta (Sample-10)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         class == "unknown" ~ "Unknown (Sample-4)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Clean display labels for the top legend
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > legend_labels <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     arabica = "Arabica",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     robusta = "Robusta",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     unknown = "Unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_three_points_labeled <- ggplot(scores_3pts, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Subtle origin crosshairs for spatial orientation
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_hline(yintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_vline(xintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Arabica & Robusta: Filled circles with crisp black outlines
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(scores_3pts, class != "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                aes(fill = class), shape = 21, colour = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                size = 3.8, stroke = 0.6, alpha = 0.95) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Unknown: High-contrast ruby star
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(scores_3pts, class == "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                aes(colour = class), shape = 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                size = 4.5, stroke = 1.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Non-overlapping direct labels for each of your 3 group points
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text_repel(aes(label = point_label, colour = class),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                     size = 2.3, fontfamily = "sans", fontface = "bold",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                     box.padding = 0.5, point.padding = 0.35,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                     segment.color = "grey40", segment.size = 0.35,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                     min.segment.length = 0, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_fill_manual(values = class_cols, labels = legend_labels) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_manual(values = class_cols, labels = legend_labels) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Generous axis margins so point labels never touch the black border
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(expand = expansion(mult = 0.35)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_y_continuous(expand = expansion(mult = 0.35)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(x = paste0("PC1 (", round(var_exp, 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +          y = paste0("PC2 (", round(var_exp, 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 8.5, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title       = element_text(size = 9, face = "plain", colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text        = element_text(size = 8, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks       = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         # Keep legend cleanly above the plot box
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         legend.position  = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.title     = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.text      = element_text(size = 8, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.key.size  = unit(0.4, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.margin    = margin(b = -4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              In geom_text_repel(aes(label = point_label, colour = class), size = 2.3,  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   Ignoring unknown parameters: `fontfamily`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_three_points_labeled)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure2_Group_Three_Points_Labeled.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_three_points_labeled, width = 3.25, height = 3.2, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Annotate MestReNova NMR Spectra Image in R (ACS Format)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 trying URL 'https://cran.rstudio.com/bin/macosx/sonoma-arm64/contrib/4.6/png_0.1-9.tgz'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Content type 'application/x-gzip' length 393500 bytes (384 KB)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ==================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   downloaded 384 KB
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 The downloaded binary packages are in
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 /var/folders/nk/tv7yqjnd2y51h6k6pbl6fg1r0000gn/T//RtmpwObBUw/downloaded_packages
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. Select Your Exported MestReNova PNG Image ---------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Select your exported MestReNova PNG image (e.g., mnova_raw_spectra.png)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Select your exported MestReNova PNG image (e.g., mnova_raw_spectra.png)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Preserve the exact aspect ratio of your MestReNova export
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > img_height <- dim(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_width  <- dim(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > aspect_ratio <- img_height / img_width
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Define Annotation Coordinates (0 to 100 Scale) ----------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # Note: (x = 0, y = 0) is bottom-left; (x = 100, y = 100) is top-right.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Adjust these x and y numbers after your first preview to point right at your peaks!
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # A) Sample Trace Labels (Left or Right side of each stacked spectrum)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(12, 12, 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(85, 55, 25),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c("Coffea arabica (Sample-5)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Coffea canephora (Sample-10)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Kirkland Unknown (Sample-4)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     col   = c("#2a6f97", "#ca6702", "#9a031e")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # B) Metabolite Peak Assignment Labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Remember: On an NMR axis (10 ppm on left -> 5 ppm on right):
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Trigonelline (~9.1-8.8 ppm) is on the LEFT (x ~ 22)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Caffeine (~7.8 ppm) is left-of-center (x ~ 44)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # CQAs (~7.5-6.2 ppm) are in the MIDDLE (x ~ 58)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Sucrose (~5.4 ppm) is on the RIGHT (x ~ 82)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(22, 44, 58, 82),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(93, 93, 93, 93),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c("Trigonelline\n(8.0–9.2 ppm)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Caffeine\n(7.80 ppm)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Chlorogenic Acids\n(6.2–7.5 ppm)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Sucrose\n(5.40 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # C) Optional Leader Arrows pointing from labels down to peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(22, 44, 58, 82),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(89, 89, 89, 89),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(22, 44, 58, 82),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(78, 78, 78, 78)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Render Annotated ACS Publication Figure -----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_annotated_nmr <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Embed your high-resolution MestReNova image across a 0-100 canvas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Add crisp sample names colored to match your PCA plots
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_label(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                fill = "white", size = 2.3, fontface = "bold.italic",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                label.size = 0.25, hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Add metabolite peak assignments
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.2, fontface = "bold", colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Add thin leader arrows pointing to the peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.12, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(2, 2, 2, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Error in `coord_cartesian()`:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ! `ratio` must be a number or `NULL`, not a double vector.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Run `rlang::last_trace()` to see where the error occurred.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   The `label.size` argument of `geom_label()` is deprecated as of ggplot2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 3.5.0.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ℹ Please use the `linewidth` argument instead.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 This warning is displayed once per session.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Call lifecycle::last_lifecycle_warnings() to see where this warning was
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 generated. 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Annotate MestReNova NMR Spectra Image in R (ACS Format)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. Select Your Exported MestReNova PNG Image ---------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Select your exported MestReNova PNG image (e.g., mnova_raw_spectra.png)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Select your exported MestReNova PNG image (e.g., mnova_raw_spectra.png)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Extract single scalar values for height [1] and width [2]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > img_dims     <- dim(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_height   <- img_dims[1]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_width    <- img_dims[2]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > aspect_ratio <- as.numeric(img_height / img_width)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Define Annotation Coordinates (0 to 100 Scale) ----------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # (x = 0, y = 0) is bottom-left; (x = 100, y = 100) is top-right.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # A) Sample Trace Labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(12, 12, 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(85, 55, 25),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c("Coffea arabica (Sample-5)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Coffea canephora (Sample-10)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Kirkland Unknown (Sample-4)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     col   = c("#2a6f97", "#ca6702", "#9a031e")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # B) Metabolite Peak Assignment Labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(22, 44, 58, 82),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(93, 93, 93, 93),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c("Trigonelline\n(8.0–9.2 ppm)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Caffeine\n(7.80 ppm)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Chlorogenic Acids\n(6.2–7.5 ppm)", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Sucrose\n(5.40 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # C) Leader Arrows pointing from labels down to peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(22, 44, 58, 82),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(89, 89, 89, 89),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(22, 44, 58, 82),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(78, 78, 78, 78)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Render Annotated ACS Publication Figure -----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_annotated_nmr <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Updated to 'linewidth' for ggplot2 3.5.0+ compatibility
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_label(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                fill = "white", size = 2.3, fontface = "bold.italic",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                linewidth = 0.25, hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.2, fontface = "bold", colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.12, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(2, 2, 2, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_annotated_nmr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Export at 600 DPI matching ACS double-column width (6.5 in)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_Annotated_MestReNova_Spectra.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_annotated_nmr, width = 6.5, height = 6.5 * aspect_ratio, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("\n[SUCCESS] Annotated MestReNova figure saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 [SUCCESS] Annotated MestReNova figure saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Publication-Grade NMR Spectral Overlay (ACS Format)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Top Trace:    Sample-4.10  (Kirkland Unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Middle Trace: Sample-10.10 (Coffea canephora / Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Bottom Trace: Sample-5.10  (Coffea arabica)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. Load Your MestReNova Image ------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Select your MestReNova PNG image...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Select your MestReNova PNG image...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir      <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster   <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_dims     <- dim(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > aspect_ratio <- as.numeric(img_dims / img_dims)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Mask Raw MestReNova Filenames for a Clean ACS Look ------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # White rectangles cover the raw "2026-10-20-Chem124-Sample..." text in top-left of each trace
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > fid_masks <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xmin = c(0.8, 0.8, 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xmax = c(17.5, 17.5, 17.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ymin = c(90.5, 62.5, 34.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ymax = c(94.2, 66.2, 38.2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Corrected Sample Labels (Matching Exact .fid Order) -----------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(2.0, 2.0, 2.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(91.5, 63.5, 35.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c("Kirkland Unknown (Sample-4)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea canephora (Sample-10)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea arabica (Sample-5)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 4. Calibrated Metabolite Positions (Mapped to 12 to -3 ppm Axis) -------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # Exact x-coordinates aligned to your image's ppm ruler:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Trigonelline (~8.8 ppm) -> x = 22.8
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Caffeine (~7.8 ppm)     -> x = 28.6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # CQAs (~6.8 ppm)         -> x = 34.4
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Sucrose (~5.4 ppm)      -> x = 42.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(19.5, 28.6, 37.5, 46.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(86.0, 92.5, 86.0, 79.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c("Trigonelline\n(8.0–9.2 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Caffeine\n(7.80 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "CQAs\n(6.2–7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Sucrose\n(5.40 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Angled leader arrows pointing directly to each peak region on the top trace
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(20.5, 28.6, 36.8, 45.2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(82.0, 88.5, 82.0, 75.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(22.8, 28.6, 34.4, 42.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(74.0, 76.5, 74.0, 71.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 5. Render Clean ACS Publication Figure ---------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_clean_nmr <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Cover raw .fid filenames cleanly with white boxes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Clean, left-aligned ACS sample labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_label(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                fill = "white", size = 2.4, fontface = "bold.italic",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                linewidth = 0.3, hjust = 0, label.padding = unit(0.18, "lines")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Staggered metabolite text labels so none collide
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.1, fontface = "bold", colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Crisp leader arrows pointing directly to the peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.10, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(2, 2, 2, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Error in `coord_cartesian()`:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ! `ratio` must be a number or `NULL`, not a double vector.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Run `rlang::last_trace()` to see where the error occurred.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Publication-Grade NMR Spectral Overlay (ACS Format)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Top Trace:    Sample-4.10  (Kirkland Unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Middle Trace: Sample-10.10 (Coffea canephora / Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Bottom Trace: Sample-5.10  (Coffea arabica)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. Load Your MestReNova Image ------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Select your MestReNova PNG image...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Select your MestReNova PNG image...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir      <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster   <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Use nrow() and ncol() to guarantee single scalar numbers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > aspect_ratio <- nrow(img_raster) / ncol(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Mask Raw MestReNova Filenames for a Clean ACS Look ------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > fid_masks <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmin = c(0.8, 0.8, 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmax = c(17.5, 17.5, 17.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymin = c(90.5, 62.5, 34.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymax = c(94.2, 66.2, 38.2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Corrected Sample Labels (Matching Exact .fid Order) -----------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(2.0, 2.0, 2.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(91.5, 63.5, 35.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c("Kirkland Unknown (Sample-4)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea canephora (Sample-10)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea arabica (Sample-5)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 4. Calibrated Metabolite Positions (Mapped to 12 to -3 ppm Axis) -------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(19.5, 28.6, 37.5, 46.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(86.0, 92.5, 86.0, 79.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c("Trigonelline\n(8.0–9.2 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Caffeine\n(7.80 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "CQAs\n(6.2–7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Sucrose\n(5.40 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Angled leader arrows pointing directly to each peak region on the top trace
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(20.5, 28.6, 36.8, 45.2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(82.0, 88.5, 82.0, 75.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(22.8, 28.6, 34.4, 42.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(74.0, 76.5, 74.0, 71.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 5. Render Clean ACS Publication Figure ---------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_clean_nmr <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Cover raw .fid filenames cleanly with white boxes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Clean, left-aligned ACS sample labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_label(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                fill = "white", size = 2.4, fontface = "bold.italic",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                linewidth = 0.3, hjust = 0, label.padding = unit(0.18, "lines")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Staggered metabolite text labels so none collide
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.1, fontface = "bold", colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Crisp leader arrows pointing directly to the peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.10, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(2, 2, 2, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_clean_nmr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_ACS_NMR_Spectra_Final.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_clean_nmr, width = 6.5, height = 6.5 * aspect_ratio, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("\n[SUCCESS] Clean ACS Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 [SUCCESS] Clean ACS Figure 1 saved to: /Users/annalise.greenlee 
