                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(2, 2, 2, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_clean_nmr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_ACS_NMR_Spectra_Final.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_clean_nmr, width = 6.5, height = 6.5 * aspect_ratio, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("\n[SUCCESS] Clean ACS Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 [SUCCESS] Clean ACS Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Publication-Grade NMR Spectral Overlay (ACS Format)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Top Trace:    Sample-4.10  (Kirkland Unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Middle Trace: Sample-10.10 (Coffea canephora / Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Bottom Trace: Sample-5.10  (Coffea arabica)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. Load Your MestReNova Image ------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Select your MestReNova PNG image...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Select your MestReNova PNG image...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir      <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster   <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Use nrow() and ncol() to guarantee single scalar numbers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > aspect_ratio <- nrow(img_raster) / ncol(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Mask Raw MestReNova Filenames for a Clean ACS Look ------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > fid_masks <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmin = c(0.8, 0.8, 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmax = c(17.5, 17.5, 17.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymin = c(90.5, 62.5, 34.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymax = c(94.2, 66.2, 38.2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Corrected Sample Labels (Matching Exact .fid Order) -----------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(2.0, 2.0, 2.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(91.5, 63.5, 35.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c("Kirkland Unknown (Sample-4)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea canephora (Sample-10)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea arabica (Sample-5)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 4. Calibrated Metabolite Positions (Mapped to 12 to -3 ppm Axis) -------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(19.5, 28.6, 37.5, 46.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(86.0, 92.5, 86.0, 79.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c("Trigonelline\n(8.0–9.2 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Caffeine\n(7.80 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "CQAs\n(6.2–7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Sucrose\n(5.40 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Angled leader arrows pointing directly to each peak region on the top trace
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(20.5, 28.6, 36.8, 45.2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(82.0, 88.5, 82.0, 75.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(22.8, 28.6, 34.4, 42.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(74.0, 76.5, 74.0, 71.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 5. Render Clean ACS Publication Figure ---------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_clean_nmr <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Cover raw .fid filenames cleanly with white boxes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Clean, left-aligned ACS sample labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_label(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                fill = "white", size = 2.4, fontface = "bold.italic",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                linewidth = 0.3, hjust = 0, label.padding = unit(0.18, "lines")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Staggered metabolite text labels so none collide
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.1, fontface = "bold", colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Crisp leader arrows pointing directly to the peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.10, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(2, 2, 2, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_clean_nmr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_ACS_NMR_Spectra_Final.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_clean_nmr, width = 6.5, height = 6.5 * aspect_ratio, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("\n[SUCCESS] Clean ACS Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 [SUCCESS] Clean ACS Figure 1 saved to: /Users/annalise.greenlee 
