                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > fid_masks <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmin = c(0.4, 0.4, 0.4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmax = c(17.5, 17.5, 17.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymin = c(90.5, 62.5, 34.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymax = c(94.5, 66.5, 38.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Sample Labels (Aligned to Exact Trace Order) ------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(1.5, 1.5, 1.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(91.8, 63.8, 35.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c("Kirkland Unknown (Sample-4)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea canephora (Sample-10)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea arabica (Sample-5)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 4. Exact PPM Metabolite Labels & Arrows (Pointing to Middle Trace) -----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # Exact ppm targets:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Trigonelline = 8.80 ppm -> x = 22.8
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Caffeine     = 7.77 ppm -> x = 28.8
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # CQAs         = 6.85 ppm -> x = 34.1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Sucrose      = 5.40 ppm -> x = 42.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(ppm_to_x(9.5), ppm_to_x(7.77), ppm_to_x(6.2), ppm_to_x(4.6)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(54.5,          60.5,           54.5,          49.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c("Trigonelline\n(8.0–9.2 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Caffeine\n(7.80 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "CQAs\n(6.2–7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Sucrose\n(5.40 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(ppm_to_x(9.3),  ppm_to_x(7.77), ppm_to_x(6.35), ppm_to_x(4.85)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(51.5,           57.5,           51.5,           47.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(ppm_to_x(8.80), ppm_to_x(7.77), ppm_to_x(6.85), ppm_to_x(5.40)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(44.2,           45.5,           44.2,           42.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 5. Render Clean ACS Publication Figure ---------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_calibrated_nmr <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Cover raw .fid filenames cleanly
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Left-aligned ACS sample labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_label(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                fill = "white", size = 2.4, fontface = "bold.italic",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                linewidth = 0.3, hjust = 0, label.padding = unit(0.18, "lines")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Staggered metabolite peak labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.1, fontface = "bold", colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Calibrated arrows pointing directly to the exact ppm peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.10, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(2, 2, 2, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_calibrated_nmr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_ACS_NMR_Spectra_Calibrated.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_calibrated_nmr, width = 6.5, height = 6.5 * aspect_ratio, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("\n[SUCCESS] Calibrated Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 [SUCCESS] Calibrated Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Annotated Zoomed NMR Spectral Overlay (ACS Format)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Top Trace:    Sample-4.10  (Kirkland Unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Middle Trace: Sample-10.10 (Coffea canephora / Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Bottom Trace: Sample-5.10  (Coffea arabica)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. Load Your Zoomed MestReNova Image -----------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Select your zoomed MestReNova PNG image...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Select your zoomed MestReNova PNG image...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir      <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster   <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > aspect_ratio <- nrow(img_raster) / ncol(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Exact linear calibration for your image's 12.5 to 4.5 ppm ruler
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ppm_to_x <- function(ppm) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     6.37 + (12.0 - ppm) * 11.65
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Mask Raw MestReNova Filenames for a Clean ACS Look ------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > fid_masks <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmin = c(0.1, 0.1, 0.1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmax = c(17.5, 17.5, 17.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymin = c(91.0, 62.5, 34.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymax = c(95.5, 67.0, 38.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Sample Labels (Aligned to Exact Trace Order) ------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(1.5, 1.5, 1.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(92.2, 63.7, 35.2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c("Kirkland Unknown (Sample-4)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea canephora (Sample-10)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Coffea arabica (Sample-5)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 4. Exact Metabolite Labels & Arrows (Pointing to Middle Trace) ---------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # Peak targets calibrated to your zoomed spectrum:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Trigonelline = 8.72 ppm -> x = 44.6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Caffeine     = 7.68 ppm -> x = 56.7
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # CQAs         = 6.85 ppm -> x = 66.4
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Sucrose      = 5.29 ppm -> x = 84.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.75), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(58.0,           62.0,           56.5,           54.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c("Trigonelline\n(8.3–9.0 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Chlorogenic Acids\n(6.2–7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.85), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(54.5,           58.5,           53.0,           50.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.85), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(46.0,           48.5,           46.5,           43.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 5. Render Clean ACS Publication Figure ---------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_zoomed_nmr <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Cover raw .fid filenames cleanly with white boxes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Clean, left-aligned ACS sample labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_label(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                fill = "white", size = 2.4, fontface = "bold.italic",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                linewidth = 0.3, hjust = 0, label.padding = unit(0.18, "lines")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Staggered metabolite text labels so none collide
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.1, fontface = "bold", colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Vertical leader arrows pointing directly down to each peak
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.10, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(2, 2, 2, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_zoomed_nmr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_ACS_Zoomed_NMR_Spectra.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_zoomed_nmr, width = 6.5, height = 6.5 * aspect_ratio, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("\n[SUCCESS] Annotated Zoomed Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 [SUCCESS] Annotated Zoomed Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Strict ACS Publication-Grade NMR Spectral Overlay
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Top Trace:    Sample-4.10  (Kirkland Unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Middle Trace: Sample-10.10 (Coffea canephora)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Bottom Trace: Sample-5.10  (Coffea arabica)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. Load Your Zoomed MestReNova Image -----------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Select your zoomed MestReNova PNG image...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Select your zoomed MestReNova PNG image...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir      <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster   <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > aspect_ratio <- nrow(img_raster) / ncol(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Exact linear calibration for your image's 12.5 to 4.5 ppm ruler
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ppm_to_x <- function(ppm) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     6.37 + (12.0 - ppm) * 11.65
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Mask Raw MestReNova Filenames & Trace Numbers -----------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # Clean white masks remove non-ACS software UI elements
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ui_masks <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xmin = c(0.1,  0.1,  0.1,  93.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xmax = c(18.0, 18.0, 18.0, 99.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ymin = c(90.5, 62.0, 33.5, 10.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ymax = c(95.8, 67.5, 39.0, 95.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Clean ACS Sample Labels (Unboxed Sans-Serif Typography) -------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # Species names are italicized; sample codes are plain text
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(1.8, 1.8, 1.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(92.5, 64.0, 35.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         "bold('Kirkland Unknown (Sample-4)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         "bold(italic('Coffea canephora') * ' (Sample-10)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         "bold(italic('Coffea arabica') * ' (Sample-5)')"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 4. Exact Metabolite Labels & Arrows (Pointing to Middle Trace) ---------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # Peak targets calibrated to your zoomed spectrum:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Trigonelline = 8.72 ppm -> x = 44.6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Caffeine     = 7.68 ppm -> x = 56.7
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # CQAs         = 6.85 ppm -> x = 66.4
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Sucrose      = 5.29 ppm -> x = 84.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x     = c(ppm_to_x(8.85), ppm_to_x(7.68), ppm_to_x(6.65), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y     = c(58.5,           62.5,           57.0,           54.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     label = c("Trigonelline\n(8.3–9.0 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Chlorogenic Acids\n(6.2–7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.85), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(54.8,           58.8,           53.2,           50.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.85), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(46.0,           48.5,           46.5,           43.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 5. Render Strict ACS Publication Figure --------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_acs_nmr <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Mask raw MestReNova filenames and right-edge trace numbers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_rect(data = ui_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Unboxed, clean sans-serif sample labels with proper species italics
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               parse = TRUE, size = 2.6, family = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Clean black sans-serif metabolite assignments (no boxes)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.3, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Thin, crisp leader arrows (0.5 pt equivalent) pointing directly to peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.11, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin  = margin(1, 1, 1, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_acs_nmr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Export at 600 DPI matching ACS double-column width (6.5 in)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_ACS_Publication_NMR.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_acs_nmr, width = 6.5, height = 6.5 * aspect_ratio, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("\n[SUCCESS] Strict ACS Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 [SUCCESS] Strict ACS Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Pure White Background ACS Publication NMR Spectral Overlay
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Top Trace:    Sample-4.10  (Kirkland Unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Middle Trace: Sample-10.10 (Coffea canephora)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Bottom Trace: Sample-5.10  (Coffea arabica)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. Load & Clean Background of Your MestReNova Image --------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Select your zoomed MestReNova PNG image...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Select your zoomed MestReNova PNG image...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir      <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster   <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > aspect_ratio <- nrow(img_raster) / ncol(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Strip faint light-grey MestReNova gridlines to pure white (RGB = 1.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Any pixel where Red, Green, and Blue are all > 0.80 becomes pure white
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > light_pixels <- (img_raster[, , 1] > 0.80) & 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     (img_raster[, , 2] > 0.80) & 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     (img_raster[, , 3] > 0.80)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > img_raster[, , 1][light_pixels] <- 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster[, , 2][light_pixels] <- 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > img_raster[, , 3][light_pixels] <- 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Exact linear calibration for your image's 12.5 to 4.5 ppm ruler
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ppm_to_x <- function(ppm) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     6.37 + (12.0 - ppm) * 11.65
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Mask Raw MestReNova Filenames & Trace Numbers -----------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > ui_masks <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmin = c(0.1,  0.1,  0.1,  93.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     xmax = c(18.0, 18.0, 18.0, 99.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymin = c(90.5, 62.0, 33.5, 10.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ymax = c(95.8, 67.5, 39.0, 95.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 3. Clean ACS Sample Labels (Unboxed Sans-Serif Typography) -------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(1.8, 1.8, 1.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(92.5, 64.0, 35.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         "bold('Kirkland Unknown (Sample-4)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         "bold(italic('Coffea canephora') * ' (Sample-10)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         "bold(italic('Coffea arabica') * ' (Sample-5)')"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 4. Exact Metabolite Labels & Arrows (Pointing to Middle Trace) ---------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     x     = c(ppm_to_x(8.85), ppm_to_x(7.68), ppm_to_x(6.65), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     y     = c(58.5,           62.5,           57.0,           54.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     label = c("Trigonelline\n(8.3–9.0 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Chlorogenic Acids\n(6.2–7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x    = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.85), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y    = c(54.8,           58.8,           53.2,           50.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     xend = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.85), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     yend = c(46.0,           48.5,           46.5,           43.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 5. Render Pure White ACS Publication Figure ----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > p_acs_nmr_white <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Mask raw MestReNova filenames and right-edge trace numbers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_rect(data = ui_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Unboxed, clean sans-serif sample labels with proper species italics
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               parse = TRUE, size = 2.6, family = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Clean black sans-serif metabolite assignments
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               size = 2.3, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +               colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     # Thin, crisp leader arrows pointing directly to peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  arrow = arrow(length = unit(0.11, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +                  linewidth = 0.35, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(limits = c(0, 100), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.background = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.background  = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border     = element_rect(colour = "black", fill = NA, linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         plot.margin      = margin(1, 1, 1, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_acs_nmr_white)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Export at 600 DPI matching ACS double-column width (6.5 in)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ggsave(file.path(out_dir, "Figure1_ACS_WhiteBG_NMR.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +        plot = p_acs_nmr_white, width = 6.5, height = 6.5 * aspect_ratio, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("\n[SUCCESS] Pure white background ACS Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 [SUCCESS] Pure white background ACS Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Unified ACS PCA Score Plot Generator (Figures 2 & 3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Figure 2: Isolated Group PCA (3 points, direct sample labels + top key)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Figure 3: Full-Section PCA (28 known + 1 unknown, clean color/shape key only)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "dplyr", "tidyr", "ggrepel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. File Selection & Settings -------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Step 1: Select your combined group CSV file (your Arabica & Robusta)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Step 1: Select your combined group CSV file (your Arabica & Robusta)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > group_known_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("Step 2: Select your Unknown CSV file (Sample-4.10)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Step 2: Select your Unknown CSV file (Sample-4.10)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > unknown_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("Step 3: Select the full section 'arabica_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Step 3: Select the full section 'arabica_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sec_arabica_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("Step 4: Select the full section 'robusta_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Step 4: Select the full section 'robusta_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sec_robusta_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir <- file.path(dirname(unknown_file), "ACS_Final_PCA_Figures")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > dir.create(out_dir, showWarnings = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > bin_width <- 0.04
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > ppm_range <- c(5.0, 10.0)   # Down-field diagnostic window
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > max_width <- 20
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ACS-compliant, colorblind-friendly palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > class_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     arabica = "#2a6f97",   # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     robusta = "#ca6702",   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     unknown = "#9a031e"    # Ruby wine red
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Encoding-Safe CSV Parser --------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > safe_read_nmr <- function(file, default_class = NULL, split_runs = TRUE) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     raw_bytes <- readBin(file, what = "raw", n = 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (length(raw_bytes) >= 2 && raw_bytes == as.raw(0x50) && raw_bytes == as.raw(0x4b)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         stop(paste0("'", basename(file), "' is an Apple Numbers/Excel archive! Export it as a .csv first."))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- readLines(file, warn = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- iconv(lines, from = "", to = "UTF-8", sub = "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- sub("^\ufeff", "", lines)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- lines[nzchar(trimws(gsub("[,\t]", "", lines)))]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     parts <- strsplit(lines, "[\t,]")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     get   <- function(i) vapply(parts, function(x) if (length(x) >= i) trimws(x[i]) else "", "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     col1 <- get(1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     col2 <- get(2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     is_fid     <- grepl("\\.fid", lines, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     run_idx    <- 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     curr_class <- ifelse(is.null(default_class), "arabica", default_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     curr_spec  <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     last_ppm   <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     records <- vector("list", length(lines))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     for (i in seq_along(lines)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         line_txt <- lines[i]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         row_class <- NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         if (grepl("\\barabica\\b", line_txt, ignore.case = TRUE)) row_class <- "arabica"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         if (grepl("\\brobusta\\b", line_txt, ignore.case = TRUE)) row_class <- "robusta"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         if (grepl("\\bunknown\\b", line_txt, ignore.case = TRUE) && is.null(default_class)) row_class <- "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         if (is_fid[i]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             if (split_runs) run_idx <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             if (!is.na(row_class) && is.null(default_class)) curr_class <- row_class
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             fid_match <- regmatches(line_txt, regexpr("[^,\t]+\\.fid", line_txt, ignore.case = TRUE))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             curr_spec <- if (length(fid_match) > 0) paste0(fid_match, "_", run_idx) else paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             last_ppm  <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             next
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         if (!is.na(row_class) && is.null(default_class) && row_class != curr_class) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             run_idx    <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             curr_class <- row_class
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             curr_spec  <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             last_ppm   <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         v1 <- suppressWarnings(as.numeric(col1[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         v2 <- suppressWarnings(as.numeric(col2[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         ppm_val <- NA_real_; wid_val <- NA_real_; are_val <- NA_real_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         if (!is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +             ppm_val <- v1; wid_val <- suppressWarnings(as.numeric(get(3)[i])); are_val <- suppressWarnings(as.numeric(get(4)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         } else if (is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             ppm_val <- v2; wid_val <- suppressWarnings(as.numeric(get(4)[i])); are_val <- suppressWarnings(as.numeric(get(5)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         if (!is.na(ppm_val) && !is.na(are_val)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             if (split_runs && (ppm_val - last_ppm > 2.0)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                 run_idx   <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                 curr_spec <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             last_ppm <- ppm_val
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +             spec_id <- if (split_runs) curr_spec else paste0("Group_", curr_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +             records[[i]] <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                 class = curr_class, spectrum = spec_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                 ppm = ppm_val, width = wid_val, area = are_val,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                 stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +             )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     bind_rows(records) %>% filter(!is.na(ppm), !is.na(area))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # ---- PART A: FIGURE 2 (Isolated Group PCA - 3 Labeled Points + Top Key) -----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > grp_known   <- safe_read_nmr(group_known_file, default_class = NULL, split_runs = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Error in length(raw_bytes) >= 2 && raw_bytes == as.raw(80) : 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'length = 4' in coercion to 'logical(1)'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > theme_bw(base_size = 8.5, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.grid.major = element_blank(), panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         axis.title       = element_text(size = 9, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         axis.text        = element_text(size = 8, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         legend.position  = "top", legend.title = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         legend.text      = element_text(size = 8), legend.margin = margin(b = -4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <theme> List of 144
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $ line                            : <ggplot2::element_line>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ..@ colour       : chr "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ linewidth    : num 0.386
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ linetype     : num 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ lineend      : chr "butt"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ linejoin     : chr "round"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ arrow        : logi FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ arrow.fill   : chr "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ inherit.blank: logi TRUE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $ rect                            : <ggplot2::element_rect>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ..@ fill         : chr "white"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ colour       : chr "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ linewidth    : num 0.386
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ linetype     : num 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ linejoin     : chr "round"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ inherit.blank: logi TRUE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 $ text                            : <ggplot2::element_text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ..@ family       : chr "sans"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ face         : chr "plain"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ italic       : chr NA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ fontweight   : num NA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ fontwidth    : num NA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ colour       : chr "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ size         : num 8.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ hjust        : num 0.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ vjust        : num 0.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ angle        : num 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ lineheight   : num 0.9
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ..@ margin       : <ggplot2::margin> num [1:4] 0 0 0 0
