                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 @ complete: logi TRUE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 @ validate: logi TRUE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > print(p_fig2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > ggsave(file.path(out_dir, "Figure2_ACS_Isolated_Group_PCA.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +        plot = p_fig2, width = 3.25, height = 3.2, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # ---- PART B: FIGURE 3 (Full-Section PCA - Clean Color/Shape Key, No Labels) -
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sec_arabica <- safe_read_nmr(sec_arabica_file, default_class = "arabica", split_runs = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Error in length(raw_bytes) >= 2 && raw_bytes == as.raw(80) : 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'length = 4' in coercion to 'logical(1)'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # UCSC CHEM 124 - Unified ACS PCA Score Plot Generator (Figures 2 & 3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Figure 2: Isolated Group PCA (3 points, direct sample labels + top key)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Figure 3: Full-Section PCA (28 known + 1 unknown, clean color/shape key only)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > pkgs <- c("ggplot2", "dplyr", "tidyr", "ggrepel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 1. File Selection & Settings -------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > cat("Step 1: Select your combined group CSV file (your Arabica & Robusta)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Step 1: Select your combined group CSV file (your Arabica & Robusta)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > group_known_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("Step 2: Select your Unknown CSV file (Sample-4.10)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Step 2: Select your Unknown CSV file (Sample-4.10)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > unknown_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("Step 3: Select the full section 'arabica_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Step 3: Select the full section 'arabica_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sec_arabica_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > cat("Step 4: Select the full section 'robusta_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Step 4: Select the full section 'robusta_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > sec_robusta_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > out_dir <- file.path(dirname(unknown_file), "ACS_Final_PCA_Figures")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > dir.create(out_dir, showWarnings = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > bin_width <- 0.04
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > ppm_range <- c(5.0, 10.0)   # Down-field diagnostic window
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > max_width <- 20
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ACS-compliant, colorblind-friendly palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > class_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     arabica = "#2a6f97",   # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     robusta = "#ca6702",   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     unknown = "#9a031e"    # Ruby wine red
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- 2. Encoding-Safe CSV Parser --------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > safe_read_nmr <- function(file, default_class = NULL, split_runs = TRUE) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     raw_bytes <- readBin(file, what = "raw", n = 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     if (length(raw_bytes) >= 2 && raw_bytes[1] == as.raw(0x50) && raw_bytes[2] == as.raw(0x4b)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         stop(paste0("'", basename(file), "' is an Apple Numbers/Excel archive! Export it as a .csv first."))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- readLines(file, warn = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- iconv(lines, from = "", to = "UTF-8", sub = "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- sub("^\ufeff", "", lines)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     lines <- lines[nzchar(trimws(gsub("[,\t]", "", lines)))]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     parts <- strsplit(lines, "[\t,]")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     get   <- function(i) vapply(parts, function(x) if (length(x) >= i) trimws(x[i]) else "", "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     col1 <- get(1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     col2 <- get(2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     is_fid     <- grepl("\\.fid", lines, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     run_idx    <- 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     curr_class <- ifelse(is.null(default_class), "arabica", default_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     curr_spec  <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     last_ppm   <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     records <- vector("list", length(lines))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     for (i in seq_along(lines)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         line_txt <- lines[i]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         row_class <- NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         if (grepl("\\barabica\\b", line_txt, ignore.case = TRUE)) row_class <- "arabica"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         if (grepl("\\brobusta\\b", line_txt, ignore.case = TRUE)) row_class <- "robusta"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         if (grepl("\\bunknown\\b", line_txt, ignore.case = TRUE) && is.null(default_class)) row_class <- "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         if (is_fid[i]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             if (split_runs) run_idx <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             if (!is.na(row_class) && is.null(default_class)) curr_class <- row_class
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             fid_match <- regmatches(line_txt, regexpr("[^,\t]+\\.fid", line_txt, ignore.case = TRUE))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             curr_spec <- if (length(fid_match) > 0) paste0(fid_match, "_", run_idx) else paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             last_ppm  <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             next
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         if (!is.na(row_class) && is.null(default_class) && row_class != curr_class) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             run_idx    <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             curr_class <- row_class
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             curr_spec  <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             last_ppm   <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         v1 <- suppressWarnings(as.numeric(col1[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         v2 <- suppressWarnings(as.numeric(col2[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         ppm_val <- NA_real_; wid_val <- NA_real_; are_val <- NA_real_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         if (!is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +             ppm_val <- v1; wid_val <- suppressWarnings(as.numeric(get(3)[i])); are_val <- suppressWarnings(as.numeric(get(4)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         } else if (is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             ppm_val <- v2; wid_val <- suppressWarnings(as.numeric(get(4)[i])); are_val <- suppressWarnings(as.numeric(get(5)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         if (!is.na(ppm_val) && !is.na(are_val)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             if (split_runs && (ppm_val - last_ppm > 2.0)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                 run_idx   <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                 curr_spec <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             last_ppm <- ppm_val
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +             spec_id <- if (split_runs) curr_spec else paste0("Group_", curr_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +             records[[i]] <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                 class = curr_class, spectrum = spec_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                 ppm = ppm_val, width = wid_val, area = are_val,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                 stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +             )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +     bind_rows(records) %>% filter(!is.na(ppm), !is.na(area))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # ---- PART A: FIGURE 2 (Isolated Group PCA - 3 Labeled Points + Top Key) -----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > grp_known   <- safe_read_nmr(group_known_file, default_class = NULL, split_runs = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > grp_unknown <- safe_read_nmr(unknown_file, default_class = "unknown", split_runs = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > breaks <- seq(ppm_range[1], ppm_range[2], by = bin_width)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Bin Unknown at 0.04 ppm; align unbinned Arabica & Robusta to the same feature grid
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > unk_binned <- grp_unknown %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     filter(ppm >= ppm_range[1], ppm <= ppm_range[2], width <= max_width, area > 0) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     mutate(bin = cut(ppm, breaks = breaks, include.lowest = TRUE, labels = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +            feature = round(breaks[bin] + bin_width / 2, 3)) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     group_by(class, spectrum, feature) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     summarise(area = sum(area), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > valid_feats <- sort(unique(unk_binned$feature))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > knw_unbinned <- grp_known %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     filter(ppm >= ppm_range[1], ppm <= ppm_range[2], width <= max_width, area > 0) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     mutate(feature = vapply(ppm, function(p) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         diffs <- abs(valid_feats - p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         if (min(diffs) <= bin_width) valid_feats[which.min(diffs)] else NA_real_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     }, numeric(1))) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     filter(!is.na(feature)) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     group_by(class, spectrum, feature) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     summarise(area = sum(area), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > df_3pts <- bind_rows(knw_unbinned, unk_binned) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     mutate(area = area / sum(area) * 100) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     complete(nesting(class, spectrum), feature, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > wide_3 <- df_3pts %>% pivot_wider(names_from = feature, values_from = area)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > meta_3 <- wide_3 %>% select(class, spectrum)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > X_3    <- sqrt(as.matrix(wide_3 %>% select(-class, -spectrum)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > rownames(X_3) <- meta_3$spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > X_3    <- X_3[, apply(X_3, 2, var) > 0, drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > pca_3     <- prcomp(X_3, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > var_exp_3 <- pca_3$sdev^2 / sum(pca_3$sdev^2) * 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > scores_3 <- as.data.frame(pca_3$x[, 1:2, drop = FALSE])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > scores_3$class <- factor(meta_3$class, levels = c("arabica", "robusta", "unknown"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > scores_3 <- scores_3 %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     mutate(point_label = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         class == "arabica" ~ "Arabica (Sample-5)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         class == "robusta" ~ "Robusta (Sample-10)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         class == "unknown" ~ "Unknown (Sample-4)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > key_labels <- c(arabica = "Arabica", robusta = "Robusta", unknown = "Unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > p_fig2 <- ggplot(scores_3, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_hline(yintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_vline(xintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_point(data = filter(scores_3, class != "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(fill = class), shape = 21, colour = "black", size = 3.6, stroke = 0.6) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_point(data = filter(scores_3, class == "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                aes(colour = class), shape = 8, size = 4.4, stroke = 1.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     geom_text_repel(aes(label = point_label, colour = class),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +                     size = 2.2, fontfamily = "sans", fontface = "bold",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +                     box.padding = 0.5, point.padding = 0.35,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +                     segment.color = "grey40", segment.size = 0.35,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +                     min.segment.length = 0, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_fill_manual(values = class_cols, labels = key_labels) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_colour_manual(values = class_cols, labels = key_labels) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_x_continuous(expand = expansion(mult = 0.35)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     scale_y_continuous(expand = expansion(mult = 0.35)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     labs(x = paste0("PC1 (", round(var_exp_3[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +          y = paste0("PC2 (", round(var_exp_3[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme_bw(base_size = 8.5, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.grid.major = element_blank(), panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         axis.title       = element_text(size = 9, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         axis.text        = element_text(size = 8, colour = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         legend.position  = "top", legend.title = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +         legend.text      = element_text(size = 8), legend.margin = margin(b = -4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   In geom_text_repel(aes(label = point_label, colour = class), size = 2.2,  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Ignoring unknown parameters:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `fontfamily`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > print(p_fig2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > ggsave(file.path(out_dir, "Figure2_ACS_Isolated_Group_PCA.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +        plot = p_fig2, width = 3.25, height = 3.2, units = "in", dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > # ---- PART B: FIGURE 3 (Full-Section PCA - Clean Color/Shape Key, No Labels) -
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > sec_arabica <- safe_read_nmr(sec_arabica_file, default_class = "arabica", split_runs = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > sec_robusta <- safe_read_nmr(sec_robusta_file, default_class = "robusta", split_runs = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > sec_unknown <- safe_read_nmr(unknown_file, default_class = "unknown", split_runs = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > sec_all <- bind_rows(sec_arabica, sec_robusta, sec_unknown) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     filter(ppm >= ppm_range[1], ppm <= ppm_range[2], width <= max_width, area > 0) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     mutate(bin = cut(ppm, breaks = breaks, include.lowest = TRUE, labels = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +            bin_mid = breaks[bin] + bin_width / 2) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     group_by(class, spectrum, bin_mid) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     summarise(area = sum(area), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     mutate(area = area / sum(area) * 100) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     complete(nesting(class, spectrum), bin_mid, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > wide_sec <- sec_all %>% pivot_wider(names_from = bin_mid, values_from = area)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > # UCSC CHEM 124 - Ultra-Sharp ACS Publication NMR Overlay (Bruker 500 MHz)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # Top Trace:    Sample-4.10  (Kirkland Unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # Middle Trace: Sample-10.10 (Coffea canephora)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # Bottom Trace: Sample-5.10  (Coffea arabica)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > pkgs <- c("ggplot2", "png", "grid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # ---- 1. Load & Enhance Contrast of Your MestReNova Image --------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > cat("Select your clean MestReNova PNG image...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Select your clean MestReNova PNG image...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > mnova_img_path <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > out_dir      <- dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > img_raster   <- readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # A) Snap any light-grey background pixels (> 0.72) to pure white (1.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > light_bg <- (img_raster[, , 1] > 0.72) & 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     (img_raster[, , 2] > 0.72) & 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     (img_raster[, , 3] > 0.72)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > img_raster[, , 1][light_bg] <- 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > img_raster[, , 2][light_bg] <- 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > img_raster[, , 3][light_bg] <- 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # B) Deepen spectral lines & bottom ppm numbers slightly for razor-sharp print contrast
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > dark_ink <- !light_bg
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > img_raster[, , 1][dark_ink] <- pmax(0, img_raster[, , 1][dark_ink] * 0.78)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > img_raster[, , 2][dark_ink] <- pmax(0, img_raster[, , 2][dark_ink] * 0.78)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > img_raster[, , 3][dark_ink] <- pmax(0, img_raster[, , 3][dark_ink] * 0.78)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # Exact linear calibration for your image's 12.5 to 4.5 ppm ruler
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > ppm_to_x <- function(ppm) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     6.37 + (12.0 - ppm) * 11.65
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # Crop limits: focuses cleanly on 9.6 ppm (left) down to 4.7 ppm (right)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > x_min_crop <- ppm_to_x(9.6)   # ~34.3%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > x_max_crop <- ppm_to_x(4.7)   # ~91.4%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # Adjusted aspect ratio for the cropped diagnostic window
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > aspect_ratio <- (nrow(img_raster) / ncol(img_raster)) * (100 / (x_max_crop - x_min_crop))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # ---- 2. Mask Raw MestReNova UI Text & Default "f1 (ppm)" Label --------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > ui_masks <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     xmin = c(x_min_crop, x_min_crop, x_min_crop, 92.5, x_min_crop),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     xmax = c(52.0,       52.0,       52.0,       100,  x_max_crop),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     ymin = c(90.5,       62.0,       33.5,       5.0,  0.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     ymax = c(96.0,       67.5,       39.0,       96.0, 2.3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # ---- 3. Clean ACS Sample Labels (Crisp Vector Typography) -------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > sample_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     x     = rep(x_min_crop + 1.2, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     y     = c(92.5, 64.0, 35.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         "bold('Kirkland Unknown (Sample-4)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         "bold(italic('Coffea canephora') * ' (Sample-10)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         "bold(italic('Coffea arabica') * ' (Sample-5)')"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # ---- 4. Exact Metabolite Labels & Arrows (Pointing to Middle Trace) ---------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > metabolite_labels <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     x     = c(ppm_to_x(8.85), ppm_to_x(7.68), ppm_to_x(6.65), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     y     = c(58.5,           62.5,           57.0,           54.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     label = c("Trigonelline\n(8.3–9.0 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               "Chlorogenic Acids\n(6.2–7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > arrow_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     x    = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.85), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     y    = c(54.8,           58.8,           53.2,           50.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     xend = c(ppm_to_x(8.72), ppm_to_x(7.68), ppm_to_x(6.85), ppm_to_x(5.29)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     yend = c(46.0,           48.5,           46.5,           43.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # ---- 5. Render Ultra-Sharp ACS Publication Figure ---------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > p_acs_sharp <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc"), interpolate = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         xmin = 0, xmax = 100, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     # Cover raw software filenames, right-hand scale bar, and "f1 (ppm)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     geom_rect(data = ui_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     # Clean ACS sample labels with proper species italics
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     geom_text(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               parse = TRUE, size = 2.8, family = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     # Metabolite peak assignment labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               size = 2.5, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +               colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     # Calibrated leader arrows pointing directly to peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                  arrow = arrow(length = unit(0.12, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                  linewidth = 0.4, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     # Crop horizontal viewport to 9.6 - 4.7 ppm so peaks fill the frame
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     scale_x_continuous(limits = c(x_min_crop, x_max_crop), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     scale_y_continuous(limits = c(0, 98), expand = c(0, 0)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     coord_fixed(ratio = aspect_ratio) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     # Official ACS X-Axis Title below the ppm tick numbers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     labs(x = expression(paste(""^1, "H Chemical Shift (", delta, ", ppm)"))) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         panel.background = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         plot.background  = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         panel.border     = element_rect(colour = "black", fill = NA, linewidth = 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         axis.title.x     = element_text(size = 9.5, face = "plain", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                                         colour = "black", margin = margin(t = 5, b = 2)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         plot.margin      = margin(3, 5, 3, 5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > print(p_acs_sharp)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > # Export at 800 DPI and full ACS double-column width (7.0 in) for razor-sharp print quality
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > ggsave(file.path(out_dir, "Figure1_ACS_UltraSharp_500MHz_NMR.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +        plot = p_acs_sharp, width = 7.0, height = 7.0 * aspect_ratio + 0.35, units = "in", dpi = 800)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        > cat("\n[SUCCESS] Ultra-sharp 800 DPI Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      [SUCCESS] Ultra-sharp 800 DPI Figure 1 saved to: /Users/annalise.greenlee 
