                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # UCSC CHEM 124 - Publication-Grade 500 MHz NMR Overlay (ACS Standard)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(png)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(grid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("Select your zoomed MestReNova PNG image (image_MfueAS.png)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Select your zoomed MestReNova PNG image (image_MfueAS.png)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > mnova_img_path = file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > out_dir    = dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Snap faint grey background pixels to pure white
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > light_bg = (img_raster[, , 1] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 2] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 3] > 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > img_raster[, , 1][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 2][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 3][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Deepen spectral lines slightly for crisp print contrast
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > dark_ink = !light_bg
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 1][dark_ink] = pmax(0, img_raster[, , 1][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 2][dark_ink] = pmax(0, img_raster[, , 2][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 3][dark_ink] = pmax(0, img_raster[, , 3][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Calibrated ppm bounds of image_MfueAS.png
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > xmin_img = -10.438
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > xmax_img = -4.101
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # White masks over raw MestReNova .fid filenames
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > fid_masks = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmin = rep(-10.10, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmax = rep(-8.95,  3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymin = c(90.5, 62.0, 33.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymax = c(96.0, 67.5, 39.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Clean ACS sample labels with proper botanical italics
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > sample_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = rep(-9.72, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(91.5, 63.0, 34.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold('Kirkland Unknown (Sample-4)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea canephora') * ' (Sample-10)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea arabica') * ' (Sample-5)')"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Exact peak annotations and leader arrows
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > metabolite_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = c(-8.68, -7.68, -6.75, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(59.0,  63.5,  58.0,  53.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c("Trigonelline\n(8.3-9.0 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Chlorogenic Acids\n(6.2-7.5 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > arrow_df = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x    = c(-8.68, -7.68, -6.75, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y    = c(55.2,  59.7,  54.2,  49.7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xend = c(-8.73, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     yend = c(51.2,  58.2,  52.8,  43.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Render ACS publication figure with pure vector X-axis
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_fig1_acs = ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc"), interpolate = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         xmin = xmin_img, xmax = xmax_img, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               parse = TRUE, size = 2.8, family = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               size = 2.5, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  arrow = arrow(length = unit(0.11, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  linewidth = 0.4, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         breaks       = seq(-9.5, -5.0, by = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         minor_breaks = seq(-9.8, -4.8, by = 0.1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         labels       = function(x) sprintf("%.1f", abs(x)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         guide        = guide_axis(minor.ticks = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     coord_cartesian(xlim = c(-9.8, -4.8), ylim = c(5.5, 96.5), expand = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(x = expression(paste(""^1, "H Chemical Shift (", delta, ", ppm)"))) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 9, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.background          = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.background           = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border              = element_rect(colour = "black", fill = NA, linewidth = 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.y               = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.x              = element_text(size = 9.5, colour = "black", margin = margin(t = 6)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.x               = element_text(size = 8.5, colour = "black", margin = margin(t = 3)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.x              = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.length.x       = unit(0.14, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.minor.ticks.length.x = unit(0.08, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.margin               = margin(t = 6, r = 10, b = 6, l = 10)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(p_fig1_acs)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ggsave(file.path(out_dir, "Figure1_ACS_500MHz_Final.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +        plot = p_fig1_acs, width = 6.5, height = 4.2, units = "in", dpi = 1200)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("\n[SUCCESS] Final 1200 DPI ACS Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [SUCCESS] Final 1200 DPI ACS Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "bold('Commercial Unknown')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "bold(italic('Coffea canephora'))",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "bold(italic('Coffea arabica'))"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Error: unexpected ',' in:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "    "bold(italic('Coffea arabica'))"
),"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # Clean ACS sample labels (Minimalist Format)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > sample_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = rep(-9.72, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(91.5, 63.0, 34.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold('Commercial Unknown')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea canephora'))",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea arabica'))"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # UCSC CHEM 124 - Strict ACS NMR Guidelines Figure 1 (500 MHz, D2O)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(png)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(grid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("Select your MestReNova PNG image (image_MfueAS.png)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Select your MestReNova PNG image (image_MfueAS.png)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > mnova_img_path = file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > out_dir    = dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Snap faint grey background pixels to pure white
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > light_bg = (img_raster[, , 1] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 2] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 3] > 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > img_raster[, , 1][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 2][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 3][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Deepen spectral lines for sharp print contrast
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > dark_ink = !light_bg
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 1][dark_ink] = pmax(0, img_raster[, , 1][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 2][dark_ink] = pmax(0, img_raster[, , 2][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 3][dark_ink] = pmax(0, img_raster[, , 3][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Calibrated ppm bounds of image_MfueAS.png
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > xmin_img = -10.438
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > xmax_img = -4.101
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # White masks over raw MestReNova .fid filenames
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > fid_masks = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmin = rep(-10.10, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmax = rep(-8.95,  3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymin = c(90.5, 62.0, 33.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymax = c(96.0, 67.5, 39.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Clean ACS sample labels (Minimum 10 pt equivalent at 6.5 in width)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > sample_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = rep(-9.70, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(87.0, 63.0, 34.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold('Commercial Unknown')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea canephora'))",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea arabica'))"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     col   = c("#9a031e", "#ca6702", "#2a6f97")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Exact 2-decimal-place peak annotations ordered downfield to upfield (ACS Rule 1.4 & 1.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > metabolite_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = c(-8.68, -7.68, -6.75, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(59.5,  64.0,  58.5,  54.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c("Trigonelline\n(8.30–9.00 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Chlorogenic Acids\n(6.20–7.50 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > arrow_df = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x    = c(-8.68, -7.68, -6.75, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y    = c(55.0,  59.5,  54.0,  49.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xend = c(-8.73, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     yend = c(51.0,  58.0,  52.5,  43.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Render ACS Publication Figure with >= 10 pt fonts and on-spectrum header
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_fig1_acs = ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc"), interpolate = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         xmin = xmin_img, xmax = xmax_img, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # ACS Rule 2.1: Required on-spectrum header showing nucleus, solvent formula, and field strength
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotate("text", x = -9.70, y = 93.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              label = "paste(NULL^1, 'H NMR (D'[2], 'O, 500 MHz)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              parse = TRUE, size = 3.6, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              colour = "black", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Sample identifiers (>= 10 pt)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               parse = TRUE, size = 3.5, family = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Metabolite assignments with 2 decimal places (>= 10 pt)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               size = 3.5, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Leader arrows pointing straight to peak tips
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  arrow = arrow(length = unit(0.12, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  linewidth = 0.45, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Vector ACS X-axis with 10 pt labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         breaks       = seq(-9.5, -5.0, by = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         minor_breaks = seq(-9.8, -4.8, by = 0.1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         labels       = function(x) sprintf("%.1f", abs(x)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         guide        = guide_axis(minor.ticks = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     coord_cartesian(xlim = c(-9.8, -4.8), ylim = c(5.5, 96.5), expand = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(x = expression(paste(""^1, "H Chemical Shift (", delta, ", ppm)"))) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 10, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.background          = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.background           = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border              = element_rect(colour = "black", fill = NA, linewidth = 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.y               = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.x              = element_text(size = 11, colour = "black", margin = margin(t = 6)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.x               = element_text(size = 10, colour = "black", margin = margin(t = 3)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.x              = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.length.x       = unit(0.15, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.minor.ticks.length.x = unit(0.08, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.margin               = margin(t = 6, r = 10, b = 6, l = 10)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(p_fig1_acs)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ggsave(file.path(out_dir, "Figure1_ACS_Guidelines_Compliant.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +        plot = p_fig1_acs, width = 6.5, height = 4.4, units = "in", dpi = 1200)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("\n[SUCCESS] ACS-compliant Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [SUCCESS] ACS-compliant Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # UCSC CHEM 124 - Final Polished ACS Figure 1 (500 MHz, D2O)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(png)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(grid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("Select your clean MestReNova PNG image (image_MfueAS.png)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Select your clean MestReNova PNG image (image_MfueAS.png)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > mnova_img_path = file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > out_dir    = dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Snap faint grey background pixels to pure white
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > light_bg = (img_raster[, , 1] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 2] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 3] > 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > img_raster[, , 1][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 2][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 3][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Deepen spectral lines for sharp print contrast
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > dark_ink = !light_bg
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 1][dark_ink] = pmax(0, img_raster[, , 1][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 2][dark_ink] = pmax(0, img_raster[, , 2][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 3][dark_ink] = pmax(0, img_raster[, , 3][dark_ink] * 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > xmin_img = -10.438
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > xmax_img = -4.101
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # White masks over raw MestReNova .fid filenames
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > fid_masks = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmin = rep(-10.10, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmax = rep(-8.95,  3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymin = c(90.5, 62.0, 33.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymax = c(96.0, 67.5, 39.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 1. Sample labels colored to match each trace's actual line color & raised clear of Trigonelline
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > sample_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = rep(-9.70, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(87.5, 66.5, 35.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold('Commercial Unknown')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea canephora'))",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea arabica'))"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     col   = c("#2a6f97", "#ca6702", "#9a031e")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 2. Spaced-out metabolite labels so nothing touches Coffea canephora
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > metabolite_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = c(-8.48, -7.68, -6.72, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(61.5,  66.5,  60.5,  54.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c("Trigonelline\n(8.30–9.00 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Chlorogenic Acids\n(6.20–7.50 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 3. Uniform-length leader arrows pointing cleanly to each peak tip
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > arrow_df = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x    = c(-8.55, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y    = c(57.2,  62.2,  56.2,  50.2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xend = c(-8.73, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     yend = c(51.5,  57.8,  52.0,  43.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_fig1_polished = ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc"), interpolate = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         xmin = xmin_img, xmax = xmax_img, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotate("text", x = -9.70, y = 93.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              label = "paste(NULL^1, 'H NMR (D', 'O, 500 MHz)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              parse = TRUE, size = 3.6, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              colour = "black", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               parse = TRUE, size = 3.5, family = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               size = 3.4, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  arrow = arrow(length = unit(0.12, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  linewidth = 0.45, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         breaks       = seq(-9.5, -5.0, by = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         minor_breaks = seq(-9.8, -4.8, by = 0.1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         labels       = function(x) sprintf("%.1f", abs(x)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         guide        = guide_axis(minor.ticks = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     coord_cartesian(xlim = c(-9.8, -4.8), ylim = c(5.5, 96.5), expand = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(x = expression(paste(""^1, "H Chemical Shift (", delta, ", ppm)"))) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 10, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.background          = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.background           = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border              = element_rect(colour = "black", fill = NA, linewidth = 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.y               = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.x              = element_text(size = 11, colour = "black", margin = margin(t = 6)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.x               = element_text(size = 10, colour = "black", margin = margin(t = 3)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.x              = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.length.x       = unit(0.14, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.minor.ticks.length.x = unit(0.08, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.margin               = margin(t = 6, r = 10, b = 6, l = 10)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(p_fig1_polished)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ggsave(file.path(out_dir, "Figure1_ACS_Final_Polished.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +        plot = p_fig1_polished, width = 6.5, height = 4.4, units = "in", dpi = 1200)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > annotate("text", x = -9.70, y = 93.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +          label = "paste(NULL^1, 'H NMR (D'[2], 'O, 500 MHz)')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +          parse = TRUE, size = 3.6, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +          colour = "black", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + # UCSC CHEM 124 - Final ACS Figure 1 (Consistent PCA Colors + D2O Subscript)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + # Top Trace (Sample-4):    Commercial Unknown -> Red (#9a031e)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + # Middle Trace (Sample-10): Coffea arabica     -> Blue (#2a6f97)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + # Bottom Trace (Sample-5):  Coffea canephora   -> Orange (#ca6702)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Error in `+.gg`:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ! Cannot add <ggproto>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              objects together.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ℹ Did you forget to add this
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            object to a <ggplot> object?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Run `rlang::last_trace()` to see where the error occurred.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # UCSC CHEM 124 - Final ACS Figure 1 (Consistent Colors + f1 (ppm) Axis)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Top Trace (Sample-4):     Commercial Unknown -> Red (#9a031e)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Middle Trace (Sample-10): Coffea arabica     -> Blue (#2a6f97)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Bottom Trace (Sample-5):  Coffea canephora   -> Orange (#ca6702)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(png)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(grid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("Select your original MestReNova PNG image (image_MfueAS.png)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Select your original MestReNova PNG image (image_MfueAS.png)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > mnova_img_path = file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > out_dir    = dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > n_rows     = nrow(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 1. Snap faint grey background pixels to pure white
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > light_bg = (img_raster[, , 1] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 2] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 3] > 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > img_raster[, , 1][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 2][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 3][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 2. Recolor each spectral trace to match your exact PCA color palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > r_top = 1:round(n_rows * 0.35)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > r_mid = (round(n_rows * 0.35) + 1):round(n_rows * 0.63)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > r_bot = (round(n_rows * 0.63) + 1):round(n_rows * 0.92)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > recolor_band = function(img, rows, hex_col) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     rgb_vals = col2rgb(hex_col) / 255
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     sub_ink  = !light_bg[rows, , drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     r_mat = img[rows, , 1]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     g_mat = img[rows, , 2]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     b_mat = img[rows, , 3]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     r_mat[sub_ink] = rgb_vals[1]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     g_mat[sub_ink] = rgb_vals[2]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     b_mat[sub_ink] = rgb_vals[3]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     img[rows, , 1] = r_mat
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     img[rows, , 2] = g_mat
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     img[rows, , 3] = b_mat
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     return(img)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > img_raster = recolor_band(img_raster, r_top, "#9a031e")  # Top: Commercial Unknown (Red)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = recolor_band(img_raster, r_mid, "#2a6f97")  # Middle: Coffea arabica (Blue)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = recolor_band(img_raster, r_bot, "#ca6702")  # Bottom: Coffea canephora (Orange)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > xmin_img = -10.438
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > xmax_img = -4.101
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # White masks over raw MestReNova .fid filenames
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > fid_masks = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmin = rep(-10.10, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmax = rep(-8.95,  3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymin = c(90.5, 62.0, 33.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymax = c(96.0, 67.5, 39.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 3. Corrected sample labels & consistent PCA colors
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > sample_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = rep(-9.70, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(87.5, 66.5, 35.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold('Commercial Unknown')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea arabica'))",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea canephora'))"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     col   = c("#9a031e", "#2a6f97", "#ca6702")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 4. Peak annotations and leader arrows
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > metabolite_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = c(-8.48, -7.68, -6.72, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(61.5,  66.5,  60.5,  54.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c("Trigonelline\n(8.30–9.00 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Chlorogenic Acids\n(6.20–7.50 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > arrow_df = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x    = c(-8.55, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y    = c(57.2,  62.2,  56.2,  50.2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xend = c(-8.73, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     yend = c(51.5,  57.8,  52.0,  43.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 5. Render Final ACS Figure 1 (Starts cleanly with ggplot())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_fig1_consistent = ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc"), interpolate = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         xmin = xmin_img, xmax = xmax_img, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotate("text", x = -9.70, y = 93.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              label = expression(bold(""^1 * "H NMR (D"[2] * "O, 500 MHz)")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              size = 3.6, family = "sans", colour = "black", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               parse = TRUE, size = 3.5, family = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               size = 3.4, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  arrow = arrow(length = unit(0.12, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  linewidth = 0.45, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         breaks       = seq(-9.5, -5.0, by = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         minor_breaks = seq(-9.8, -4.8, by = 0.1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         labels       = function(x) sprintf("%.1f", abs(x)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         guide        = guide_axis(minor.ticks = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     coord_cartesian(xlim = c(-9.8, -4.8), ylim = c(5.5, 96.5), expand = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(x = "f1 (ppm)") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 10, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.background          = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.background           = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border              = element_rect(colour = "black", fill = NA, linewidth = 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.y               = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.x              = element_text(size = 11, colour = "black", margin = margin(t = 6)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.x               = element_text(size = 10, colour = "black", margin = margin(t = 3)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.x              = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.length.x       = unit(0.14, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.minor.ticks.length.x = unit(0.08, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.margin               = margin(t = 6, r = 10, b = 6, l = 10)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(p_fig1_consistent)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ggsave(file.path(out_dir, "Figure1_ACS_Consistent_Colors.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +        plot = p_fig1_consistent, width = 6.5, height = 4.4, units = "in", dpi = 1200)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("\n[SUCCESS] Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [SUCCESS] Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 3. Sample labels positioned cleanly on each trace
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > sample_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = rep(-9.70, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(87.5, 65.5, 36.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold('Commercial Unknown')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea arabica'))",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea canephora'))"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     col   = c("#9a031e", "#2a6f97", "#ca6702")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 4. Peak annotations and leader arrows positioned on the bottom Robusta trace
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > metabolite_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = c(-8.48, -7.68, -6.72, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(31.5,  37.5,  30.5,  24.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c("Trigonelline\n(8.30–9.00 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Chlorogenic Acids\n(6.20–7.50 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > arrow_df = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x    = c(-8.55, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y    = c(27.2,  33.2,  26.2,  20.2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xend = c(-8.73, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     yend = c(20.5,  29.5,  21.5,  13.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # UCSC CHEM 124 - Final ACS Figure 1 (Labels on Coffea canephora / Robusta Trace)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Top Trace (Sample-4):     Commercial Unknown -> Red (#9a031e)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Middle Trace (Sample-10): Coffea arabica     -> Blue (#2a6f97)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Bottom Trace (Sample-5):  Coffea canephora   -> Orange (#ca6702)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(png)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(grid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("Select your original MestReNova PNG image (image_MfueAS.png)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Select your original MestReNova PNG image (image_MfueAS.png)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > mnova_img_path = file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > out_dir    = dirname(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = readPNG(mnova_img_path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > n_rows     = nrow(img_raster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 1. Snap faint grey background pixels to pure white
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > light_bg = (img_raster[, , 1] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 2] > 0.75) &
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     (img_raster[, , 3] > 0.75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > img_raster[, , 1][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 2][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster[, , 3][light_bg] = 1.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 2. Recolor each spectral trace to match your consistent PCA color palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > r_top = 1:round(n_rows * 0.35)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > r_mid = (round(n_rows * 0.35) + 1):round(n_rows * 0.63)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > r_bot = (round(n_rows * 0.63) + 1):round(n_rows * 0.92)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > recolor_band = function(img, rows, hex_col) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     rgb_vals = col2rgb(hex_col) / 255
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     sub_ink  = !light_bg[rows, , drop = FALSE]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     r_mat = img[rows, , 1]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     g_mat = img[rows, , 2]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     b_mat = img[rows, , 3]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     r_mat[sub_ink] = rgb_vals[1]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     g_mat[sub_ink] = rgb_vals[2]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     b_mat[sub_ink] = rgb_vals[3]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     img[rows, , 1] = r_mat
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     img[rows, , 2] = g_mat
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     img[rows, , 3] = b_mat
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     return(img)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > img_raster = recolor_band(img_raster, r_top, "#9a031e")  # Top: Commercial Unknown (Red)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = recolor_band(img_raster, r_mid, "#2a6f97")  # Middle: Coffea arabica (Blue)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > img_raster = recolor_band(img_raster, r_bot, "#ca6702")  # Bottom: Coffea canephora (Orange)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > xmin_img = -10.438
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > xmax_img = -4.101
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 3. White masks over raw MestReNova .fid filenames
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > fid_masks = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmin = rep(-10.10, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xmax = rep(-8.95,  3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymin = c(90.5, 62.0, 33.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ymax = c(96.0, 67.5, 39.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 4. Sample labels positioned cleanly above each trace
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > sample_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = rep(-9.70, 3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(87.5, 65.5, 36.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold('Commercial Unknown')",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea arabica'))",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         "bold(italic('Coffea canephora'))"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     col   = c("#9a031e", "#2a6f97", "#ca6702")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 5. Metabolite peak annotations positioned on the bottom Coffea canephora (Robusta) trace
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > metabolite_labels = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x     = c(-8.48, -7.68, -6.72, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y     = c(31.5,  37.5,  30.5,  24.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     label = c("Trigonelline\n(8.30–9.00 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Caffeine\n(7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Chlorogenic Acids\n(6.20–7.50 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +               "Sucrose\n(5.29 ppm)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 6. Leader arrows pointing directly down to the bottom Coffea canephora peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > arrow_df = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     x    = c(-8.55, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     y    = c(27.2,  33.2,  26.2,  20.2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     xend = c(-8.73, -7.68, -6.74, -5.29),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     yend = c(20.5,  29.5,  21.5,  14.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 7. Render Final ACS Figure 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_fig1_robusta_labeled = ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotation_custom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         rasterGrob(img_raster, width = unit(1, "npc"), height = unit(1, "npc"), interpolate = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         xmin = xmin_img, xmax = xmax_img, ymin = 0, ymax = 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_rect(data = fid_masks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               fill = "white", colour = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotate("text", x = -9.70, y = 93.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              label = expression(bold(""^1 * "H NMR (D"[2] * "O, 500 MHz)")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +              size = 3.6, family = "sans", colour = "black", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = sample_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label, colour = col),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               parse = TRUE, size = 3.5, family = "sans", hjust = 0) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = metabolite_labels,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(x = x, y = y, label = label),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               size = 3.4, fontface = "bold", family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               colour = "black", lineheight = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_segment(data = arrow_df,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  aes(x = x, y = y, xend = xend, yend = yend),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  arrow = arrow(length = unit(0.12, "cm"), type = "closed"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  linewidth = 0.45, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_identity() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         breaks       = seq(-9.5, -5.0, by = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         minor_breaks = seq(-9.8, -4.8, by = 0.1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         labels       = function(x) sprintf("%.1f", abs(x)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         guide        = guide_axis(minor.ticks = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     coord_cartesian(xlim = c(-9.8, -4.8), ylim = c(5.5, 96.5), expand = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(x = "f1 (ppm)") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 10, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor          = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.background          = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.background           = element_rect(fill = "white", colour = NA),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border              = element_rect(colour = "black", fill = NA, linewidth = 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.y               = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.y              = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title.x              = element_text(size = 11, colour = "black", margin = margin(t = 6)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.x               = element_text(size = 10, colour = "black", margin = margin(t = 3)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.x              = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.length.x       = unit(0.14, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.minor.ticks.length.x = unit(0.08, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.margin               = margin(t = 6, r = 10, b = 6, l = 10)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(p_fig1_robusta_labeled)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ggsave(file.path(out_dir, "Figure1_ACS_Robusta_Labeled.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +        plot = p_fig1_robusta_labeled, width = 6.5, height = 4.4, units = "in", dpi = 1200)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("\n[SUCCESS] Figure 1 saved to:", out_dir, "\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [SUCCESS] Figure 1 saved to: /Users/annalise.greenlee 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # UCSC CHEM 124 - Unified ACS PCA Score Plots (Figures 2 & 3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Preprocessing: Compound peaks only, 5.10-9.50 ppm (excludes HDO tail),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > #                0.04 ppm binning, total-area normalization, sqrt scaling
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ###############################################################################
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ---- 0. Packages ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > pkgs <- c("ggplot2", "dplyr", "tidyr", "ggrepel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ---- 1. File Selection & Settings -------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > cat("Step 1: Select your combined group CSV file (Sample-10 Arabica & Sample-5 Robusta)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Step 1: Select your combined group CSV file (Sample-10 Arabica & Sample-5 Robusta)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > group_known_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("Step 2: Select your Unknown CSV file (Sample-4.10)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Step 2: Select your Unknown CSV file (Sample-4.10)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > unknown_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("Step 3: Select the full section 'arabica_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Step 3: Select the full section 'arabica_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > sec_arabica_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cat("Step 4: Select the full section 'robusta_raw.csv' file...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Step 4: Select the full section 'robusta_raw.csv' file...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > sec_robusta_file <- file.choose()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > out_dir <- file.path(dirname(unknown_file), "ACS_Final_PCA_Figures")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > dir.create(out_dir, showWarnings = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > bin_width    <- 0.04
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > ppm_range    <- c(5.10, 9.50)   # Clean down-field diagnostic window (avoids HDO water tail)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > keep_classes <- c("Compound", "Unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > max_width    <- 20
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Consistent ACS colorblind-friendly palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > class_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     arabica = "#2a6f97",   # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     robusta = "#ca6702",   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     unknown = "#9a031e"    # Ruby wine red
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > key_labels <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     arabica = "Coffea arabica",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     robusta = "Coffea canephora",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     unknown = "Commercial Unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ---- 2. Encoding-Safe CSV Parser (Preserves peak_class & Sample IDs) --------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > safe_read_nmr <- function(file, default_class = NULL, split_runs = TRUE) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     raw_bytes <- readBin(file, what = "raw", n = 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     if (length(raw_bytes) >= 2 && raw_bytes == as.raw(0x50) && raw_bytes == as.raw(0x4b)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         stop(paste0("'", basename(file), "' is an Apple Numbers/Excel archive! Export it as a .csv first."))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     lines <- readLines(file, warn = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     lines <- iconv(lines, from = "", to = "UTF-8", sub = "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     lines <- sub("^\ufeff", "", lines)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     lines <- lines[nzchar(trimws(gsub("[,\t]", "", lines)))]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     parts <- strsplit(lines, "[\t,]")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     get   <- function(i) vapply(parts, function(x) if (length(x) >= i) trimws(x[i]) else "", "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     col1 <- get(1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     col2 <- get(2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     is_fid     <- grepl("\\.fid", lines, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     run_idx    <- 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     curr_class <- ifelse(is.null(default_class), "arabica", default_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     curr_spec  <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     last_ppm   <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     records <- vector("list", length(lines))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     for (i in seq_along(lines)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +         line_txt <- lines[i]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         # Detect explicit species or sample-number labels (Sample-10 = Arabica, Sample-5 = Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         row_class <- NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         if (grepl("\\barabica\\b|Sample-10\\b", line_txt, ignore.case = TRUE)) row_class <- "arabica"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         if (grepl("\\brobusta\\b|\\bcanephora\\b|Sample-5\\b", line_txt, ignore.case = TRUE)) row_class <- "robusta"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         if (grepl("Sample-4\\b", line_txt, ignore.case = TRUE) && is.null(default_class)) row_class <- "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         if (is_fid[i]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             if (split_runs) run_idx <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             if (!is.na(row_class) && is.null(default_class)) curr_class <- row_class
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             fid_match <- regmatches(line_txt, regexpr("[^,\t]+\\.fid", line_txt, ignore.case = TRUE))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             curr_spec <- if (length(fid_match) > 0) paste0(fid_match, "_", run_idx) else paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             last_ppm  <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             next
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         if (!is.na(row_class) && is.null(default_class) && row_class != curr_class) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             run_idx    <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             curr_class <- row_class
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             curr_spec  <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             last_ppm   <- Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         v1 <- suppressWarnings(as.numeric(col1[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         v2 <- suppressWarnings(as.numeric(col2[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         ppm_val <- NA_real_; wid_val <- NA_real_; are_val <- NA_real_; p_cls <- "Compound"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         if (!is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +             ppm_val <- v1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +             wid_val <- suppressWarnings(as.numeric(get(3)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +             are_val <- suppressWarnings(as.numeric(get(4)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +             p_cls   <- ifelse(get(5)[i] == "", "Compound", get(5)[i])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         } else if (is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             p_cls   <- ifelse(col1[i] == "", "Compound", col1[i])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             ppm_val <- v2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             wid_val <- suppressWarnings(as.numeric(get(4)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             are_val <- suppressWarnings(as.numeric(get(5)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         if (!is.na(ppm_val) && !is.na(are_val)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             if (split_runs && (ppm_val - last_ppm > 2.0)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                 run_idx   <- run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                 curr_spec <- paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             last_ppm <- ppm_val
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             spec_id <- if (split_runs) curr_spec else paste0("Group_", curr_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             records[[i]] <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +                 class = curr_class, spectrum = spec_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +                 ppm = ppm_val, width = wid_val, area = are_val,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +                 peak_class = p_cls, stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +             )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     bind_rows(records) %>% filter(!is.na(ppm), !is.na(area))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Helper function to uniformly bin, normalize, and square-root transform peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > process_spectra <- function(df, breaks, bin_width, ppm_range, max_width, keep_classes) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             peak_class %in% keep_classes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             ppm >= ppm_range, ppm <= ppm_range,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             width <= max_width,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             area > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         ) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             bin     = cut(ppm, breaks = breaks, include.lowest = TRUE, labels = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             bin_mid = round(breaks[bin] + bin_width / 2, 3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         ) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         group_by(class, spectrum, bin_mid) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         summarise(area = sum(area), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         mutate(area = area / sum(area) * 100) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         complete(nesting(class, spectrum), bin_mid, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > breaks <- seq(ppm_range, ppm_range, by = bin_width)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Error in seq.default(ppm_range, ppm_range, by = bin_width) : 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'from' must be of length 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # UCSC CHEM 124 - Unified ACS PCA Score Plots (Figures 2 & 3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Preprocessing: Compound peaks only, 5.10-9.50 ppm (excludes HDO tail),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > #                0.04 ppm binning, total-area normalization, sqrt scaling
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > pkgs = c("ggplot2", "dplyr", "tidyr", "ggrepel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > for (p in pkgs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     if (!requireNamespace(p, quietly = TRUE)) install.packages(p)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     library(p, character.only = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ---- 1. File Selection & Settings -------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > cat("Step 1: Select your combined group CSV file (Sample-10 Arabica & Sample-5 Robusta)...\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Step 1: Select your combined group CSV file (Sample-10 Arabica & Sample-5 Robusta)...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > group_known_file = file.choose()
