                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > out_dir = file.path(dirname(unknown_file), "ACS_Final_PCA_Figures")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > dir.create(out_dir, showWarnings = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > bin_width    = 0.04
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > ppm_min      = 5.10   # Lower bound (excludes residual HDO water tail)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > ppm_max      = 9.50   # Upper down-field bound
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > keep_classes = c("Compound", "Unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > max_width    = 20
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Consistent ACS colorblind-friendly palette
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > class_cols = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     arabica = "#2a6f97",   # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     robusta = "#ca6702",   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     unknown = "#9a031e"    # Ruby wine red
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > key_labels = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     arabica = "Coffea arabica",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     robusta = "Coffea canephora",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     unknown = "Commercial Unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ---- 2. Encoding-Safe CSV Parser --------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > safe_read_nmr = function(file, default_class = NULL, split_runs = TRUE) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     raw_bytes = readBin(file, what = "raw", n = 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     if (length(raw_bytes) >= 2 && raw_bytes == as.raw(0x50) && raw_bytes == as.raw(0x4b)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         stop(paste0("'", basename(file), "' is an Apple Numbers/Excel archive! Export it as a .csv first."))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     lines = readLines(file, warn = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     lines = iconv(lines, from = "", to = "UTF-8", sub = "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     lines = sub("^\ufeff", "", lines)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     lines = lines[nzchar(trimws(gsub("[,\t]", "", lines)))]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     parts = strsplit(lines, "[\t,]")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     get   = function(i) vapply(parts, function(x) if (length(x) >= i) trimws(x[i]) else "", "")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     col1 = get(1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     col2 = get(2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     is_fid     = grepl("\\.fid", lines, ignore.case = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     run_idx    = 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     curr_class = ifelse(is.null(default_class), "arabica", default_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     curr_spec  = paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     last_ppm   = Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     records = vector("list", length(lines))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     for (i in seq_along(lines)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +         line_txt = lines[i]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         # Detect explicit species or sample-number labels (Sample-10 = Arabica, Sample-5 = Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         row_class = NA_character_
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         if (grepl("\\barabica\\b|Sample-10\\b", line_txt, ignore.case = TRUE)) row_class = "arabica"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         if (grepl("\\brobusta\\b|\\bcanephora\\b|Sample-5\\b", line_txt, ignore.case = TRUE)) row_class = "robusta"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         if (grepl("Sample-4\\b", line_txt, ignore.case = TRUE) && is.null(default_class)) row_class = "unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         if (is_fid[i]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             if (split_runs) run_idx = run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             if (!is.na(row_class) && is.null(default_class)) curr_class = row_class
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             fid_match = regmatches(line_txt, regexpr("[^,\t]+\\.fid", line_txt, ignore.case = TRUE))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             curr_spec = if (length(fid_match) > 0) paste0(fid_match, "_", run_idx) else paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             last_ppm  = Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             next
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         if (!is.na(row_class) && is.null(default_class) && row_class != curr_class) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             run_idx    = run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             curr_class = row_class
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             curr_spec  = paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             last_ppm   = Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         v1 = suppressWarnings(as.numeric(col1[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         v2 = suppressWarnings(as.numeric(col2[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         ppm_val = NA_real_; wid_val = NA_real_; are_val = NA_real_; p_cls = "Compound"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         if (!is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +             ppm_val = v1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +             wid_val = suppressWarnings(as.numeric(get(3)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +             are_val = suppressWarnings(as.numeric(get(4)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +             p_cls   = ifelse(get(5)[i] == "", "Compound", get(5)[i])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         } else if (is.na(v1) && !is.na(v2)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             p_cls   = ifelse(col1[i] == "", "Compound", col1[i])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             ppm_val = v2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             wid_val = suppressWarnings(as.numeric(get(4)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             are_val = suppressWarnings(as.numeric(get(5)[i]))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         if (!is.na(ppm_val) && !is.na(are_val)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             if (split_runs && (ppm_val - last_ppm > 2.0)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                 run_idx   = run_idx + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                 curr_spec = paste0(curr_class, "_Run_", run_idx)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             last_ppm = ppm_val
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             spec_id = if (split_runs) curr_spec else paste0("Group_", curr_class)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             records[[i]] = data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +                 class = curr_class, spectrum = spec_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +                 ppm = ppm_val, width = wid_val, area = are_val,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +                 peak_class = p_cls, stringsAsFactors = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +             )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +     bind_rows(records) %>% filter(!is.na(ppm), !is.na(area))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Helper function to uniformly bin, normalize, and square-root transform peaks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > process_spectra = function(df, breaks, bin_width, ppm_min, ppm_max, max_width, keep_classes) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             peak_class %in% keep_classes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             ppm >= ppm_min, ppm <= ppm_max,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             width <= max_width,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             area > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         ) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             bin     = cut(ppm, breaks = breaks, include.lowest = TRUE, labels = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +             bin_mid = round(breaks[bin] + bin_width / 2, 3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +         ) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         group_by(class, spectrum, bin_mid) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         summarise(area = sum(area), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         group_by(spectrum) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         mutate(area = area / sum(area) * 100) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         ungroup() %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         complete(nesting(class, spectrum), bin_mid, fill = list(area = 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > breaks = seq(ppm_min, ppm_max, by = bin_width)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # ---- PART A: FIGURE 2 (Full-Section PCA: 28 Known + Projected Unknown) ------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > sec_arabica = safe_read_nmr(sec_arabica_file, default_class = "arabica", split_runs = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Error in length(raw_bytes) >= 2 && raw_bytes == as.raw(80) : 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'length = 4' in coercion to 'logical(1)'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # 1. Install and load required packages (uncomment install lines if needed)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # install.packages(c("ggplot2", "ggrepel", "dplyr"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(ggrepel)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # 2. DATA PREPARATION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Replace this simulated dataset with your own data (e.g., read.csv("your_data.csv"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Ensure rows = 29 samples (28 known + 1 unknown) and columns = numeric variables
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > set.seed(42)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Creating mock data for 28 known samples across 3 distinct groups + 1 unknown
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > known_data <- rbind(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     matrix(rnorm(10 * 5, mean = 5, sd = 1), nrow = 10),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     matrix(rnorm(9 * 5, mean = 10, sd = 1.2), nrow = 9),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     matrix(rnorm(9 * 5, mean = 15, sd = 1.1), nrow = 9)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > unknown_data <- matrix(rnorm(1 * 5, mean = 10.2, sd = 0.8), nrow = 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > df <- as.data.frame(rbind(known_data, unknown_data))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > colnames(df) <- paste0("Var_", 1:5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > df$Sample_ID <- c(paste0("Sample_", 1:28), "Unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > df$Sample_Type <- c(rep("Known Sample", 28), "Unknown Sample")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # 3. RUN PCA & K-MEANS CLUSTERING
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # Select only numeric feature columns for PCA and K-means
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > numeric_features <- df %>% select(starts_with("Var_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Run PCA (scaling and centering is recommended)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > pca_res <- prcomp(numeric_features, center = TRUE, scale. = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Calculate percentage of variance explained for axis labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > var_explained <- round(100 * (pca_res$sdev^2 / sum(pca_res$sdev^2)), 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Run K-means clustering on scaled data (adjust 'centers' to your expected number of clusters)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > k_clusters <- 3 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > kmeans_res <- kmeans(scale(numeric_features), centers = k_clusters, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Combine PCA coordinates, K-means cluster assignments, and metadata
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > plot_data <- as.data.frame(pca_res$x[, 1:2])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > plot_data$Cluster <- as.factor(kmeans_res$cluster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > plot_data$Sample_ID <- df$Sample_ID
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > plot_data$Sample_Type <- df$Sample_Type
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # 4. GENERATE PCA + K-MEANS FIGURE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > pca_plot <- ggplot(plot_data, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Draw confidence/convex ellipses around K-means clusters
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     stat_ellipse(aes(fill = Cluster, color = Cluster), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  geom = "polygon", alpha = 0.15, level = 0.90, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Plot all 29 points, distinguishing the Unknown sample by shape and size
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(aes(color = Cluster, shape = Sample_Type, size = Sample_Type), alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Add non-overlapping labels (bolding the Unknown sample)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text_repel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         aes(label = Sample_ID, fontface = ifelse(Sample_Type == "Unknown Sample", "bold", "plain")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         size = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         box.padding = 0.4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         max.overlaps = Inf
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Customize shapes, sizes, and labels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_shape_manual(values = c("Known Sample" = 16, "Unknown Sample" = 17)) + # Circle vs Triangle
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_size_manual(values = c("Known Sample" = 3.5, "Unknown Sample" = 5.5)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         title = "PCA Plot with K-Means Clustering (28 Samples + 1 Unknown)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         subtitle = paste0("K-means partitioned into k = ", k_clusters, " clusters"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         x = paste0("PC1 (", var_explained[1], "% variance)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         y = paste0("PC2 (", var_explained[2], "% variance)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         color = "K-Means Cluster",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         shape = "Sample Status",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         size = "Sample Status"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_minimal(base_size = 13) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.title = element_text(face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.position = "right",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor = element_blank()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Display the plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(pca_plot)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Optional: Save high-resolution figure
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # ggsave("PCA_Kmeans_29samples.png", plot = pca_plot, width = 9, height = 6.5, dpi = 300)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # ---- K-Means Clustering Plot (Clean & Intuitive ACS Layout) -----------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 1. Combine all 28 known samples and 1 unknown sample, then run K-Means (k = 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 2. Match cluster assignments to PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # Ensure rownames(X_all) match all_scores$spectrum
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     mutate(Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 3. Automatically name the clusters chemically (Negative PC1 = Arabica, Positive PC1 = Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cluster_means <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     group_by(Cluster_Num) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     summarise(mean_PC1 = mean(PC1), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > arabica_num <- cluster_means$Cluster_Num[which.min(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > robusta_num <- cluster_means$Cluster_Num[which.max(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > kmeans_df <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         Cluster_Name = ifelse(Cluster_Num == arabica_num, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +                               "K-Means: Arabica Group", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +                               "K-Means: Robusta Group"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         Point_Type = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +             class == "unknown" ~ "Kirkland Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +             (class == "arabica" & Cluster_Num != arabica_num) | 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                 (class == "robusta" & Cluster_Num != robusta_num) ~ "Swapped Sample",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +             TRUE ~ "Matched Reference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 4. Compute soft convex hulls to gently shade each K-means territory
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > hulls <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 5. Compute cluster centroids
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 6. Render the Intuitive ACS Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > group_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "K-Means: Arabica Group" = "#2a6f97",  # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "K-Means: Robusta Group" = "#ca6702"   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_kmeans_clean <- ggplot(kmeans_df, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Origin crosshairs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_hline(yintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_vline(xintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Subtle shaded territories showing the K-means boundaries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_polygon(data = hulls, aes(fill = Cluster_Name), alpha = 0.12, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Standard reference points (solid circles)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(kmeans_df, Point_Type == "Matched Reference"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                aes(colour = Cluster_Name), size = 2.5, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Clerical sample swap points (open rings to highlight the anomaly)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(kmeans_df, Point_Type == "Swapped Sample"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                aes(colour = Cluster_Name), shape = 21, fill = "white", size = 2.8, stroke = 1.1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Cluster centroids (black X markers)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = centroids_pca, aes(PC1, PC2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                shape = 4, size = 3.0, stroke = 1.1, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Kirkland Unknown (bold red star with a clean direct label)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                shape = 8, size = 4.0, stroke = 1.3, colour = "#9a031e") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text(data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               aes(label = "Kirkland Unknown"), vjust = -1.1, hjust = 0.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +               size = 2.4, fontface = "bold", colour = "#9a031e", family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_fill_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(expand = expansion(mult = 0.15)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_y_continuous(expand = expansion(mult = 0.15)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +          y = paste0("PC2 (", round(var_exp[2], 1), "%)")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.title     = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.text      = element_text(size = 7.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.position  = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.margin    = margin(b = -5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > print(p_kmeans_clean)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 7. Save clean high-res ACS single-column figure (3.5 in wide, 600 DPI)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     filename = file.path(out_dir, "Figure_KMeans_Clean_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     plot     = p_kmeans_clean,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     width    = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     height   = 3.3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     units    = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     dpi      = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # ---- K-Means Clustering Plot (Strict ACS Single-Column Publication Style) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(ggrepel)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 1. Combine all 28 known samples and 1 unknown sample, then run K-Means (k = 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 2. Match cluster assignments to PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     mutate(Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 3. Automatically name clusters chemically (Negative PC1 = Arabica, Positive PC1 = Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > cluster_means <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     group_by(Cluster_Num) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     summarise(mean_PC1 = mean(PC1), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > arabica_num <- cluster_means$Cluster_Num[which.min(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > robusta_num <- cluster_means$Cluster_Num[which.max(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > kmeans_df <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         Cluster_Name = ifelse(Cluster_Num == arabica_num, "Arabica Cluster", "Robusta Cluster"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         Point_Type = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +             class == "unknown" ~ "Kirkland Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +             (class == "arabica" & Cluster_Num != arabica_num) | 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +                 (class == "robusta" & Cluster_Num != robusta_num) ~ "Swapped Sample",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +             TRUE ~ "Matched Reference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 4. Compute convex hulls and cluster centroids
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > hulls <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 5. Colorblind-safe ACS palette (Deep Navy Blue vs. Burnt Orange)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > group_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "Arabica Cluster" = "#005f73",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     "Robusta Cluster" = "#ca6702"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > # 6. Render the ACS-Formatted Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              > p_kmeans_acs <- ggplot(kmeans_df, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Subtle dashed zero-lines
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_hline(yintercept = 0, colour = "grey85", linetype = "dashed", linewidth = 0.35) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_vline(xintercept = 0, colour = "grey85", linetype = "dashed", linewidth = 0.35) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Soft K-means cluster territories with faint outline
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_polygon(data = hulls, aes(fill = Cluster_Name, colour = Cluster_Name),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +                  alpha = 0.10, linewidth = 0.25, linetype = "dotted", show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Standard reference points (solid filled circles)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(kmeans_df, Point_Type == "Matched Reference"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                aes(colour = Cluster_Name), shape = 16, size = 2.4, alpha = 0.92) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Swapped samples (high-contrast open rings)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(kmeans_df, Point_Type == "Swapped Sample"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                aes(colour = Cluster_Name), shape = 21, fill = "white", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                size = 2.6, stroke = 1.1, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Cluster centroids (sharp black X markers)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = centroids_pca, aes(x = PC1, y = PC2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                shape = 4, size = 2.8, stroke = 1.1, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Kirkland Unknown (crimson 5-point star with white halo border for pop)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_point(data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                shape = 23, fill = "#9a031e", colour = "white", size = 3.4, stroke = 0.6) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Non-clipping smart label for Kirkland Unknown
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     geom_text_repel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         aes(label = "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         size = 2.6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         fontface = "bold",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         colour = "#9a031e",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         nudge_y = 0.12 * diff(range(kmeans_df$PC2)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         segment.size = 0.35,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         segment.colour = "#9a031e",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         min.segment.length = 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     # Compact symbol key inside plot corner (adjust x/y = Inf/-Inf if needed)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     annotate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         "label",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         x = Inf, y = -Inf,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         label = "● Reference   ○ Swapped\n× Centroid     ◆ Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         hjust = 1.04, vjust = -0.15,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         size = 2.1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         colour = "grey20",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         fill = alpha("white", 0.85),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         label.size = 0.25,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         label.padding = unit(0.25, "lines")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_colour_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_fill_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_x_continuous(expand = expansion(mult = 0.14)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     scale_y_continuous(expand = expansion(mult = 0.16)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         y = paste0("PC2 (", round(var_exp[2], 1), "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.major   = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.grid.minor   = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         panel.border       = element_rect(colour = "black", linewidth = 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks         = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.ticks.length  = unit(-0.10, "cm"), # Classic ACS inward ticks
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.x        = element_text(colour = "black", size = 7.5, margin = margin(t = 4)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.text.y        = element_text(colour = "black", size = 7.5, margin = margin(r = 4)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         axis.title         = element_text(colour = "black", size = 8.5, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.title       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.text        = element_text(size = 8, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.position    = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.direction   = "horizontal",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.key.size    = unit(0.35, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         legend.margin      = margin(t = 0, b = -4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +         plot.margin        = margin(t = 4, r = 6, b = 4, l = 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              In annotate("label", x = Inf, y = -Inf, label = "● Reference   ○ Swapped\n× Centroid     ◆ Unknown",  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Ignoring unknown parameters: `label.size`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > print(p_kmeans_acs)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > # 7. Export at exact ACS single-column width (3.33 inches) in both PNG and vector PDF
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     filename = file.path(out_dir, "Figure_KMeans_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     plot     = p_kmeans_acs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     width    = 3.33,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     height   = 3.20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     units    = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     dpi      = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     filename = file.path(out_dir, "Figure_KMeans_ACS.pdf"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     plot     = p_kmeans_acs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     width    = 3.33,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     height   = 3.20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +     units    = "in"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Warning messages:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            1: In grid.Call.graphics(C_text, as.graphicsAnnot(x$label), x$x, x$y,  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       conversion failure on '● Reference   ○ Swapped' in 'mbcsToSbcs': for ● (U+25CF)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     2: In grid.Call.graphics(C_text, as.graphicsAnnot(x$label), x$x, x$y,  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                conversion failure on '● Reference   ○ Swapped' in 'mbcsToSbcs': for ○ (U+25CB)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              3: In grid.Call.graphics(C_text, as.graphicsAnnot(x$label), x$x, x$y,  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         conversion failure on '× Centroid     ◆ Unknown' in 'mbcsToSbcs': for ◆ (U+25C6)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > # ---- K-Means Clustering Plot (Strict ACS Single-Column Publication Style) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > library(ggrepel)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 1. Combine all 28 known samples and 1 unknown sample, then run K-Means (k = 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 2. Match cluster assignments to PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     mutate(Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 3. Automatically name clusters chemically (Negative PC1 = Arabica, Positive PC1 = Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > cluster_means <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     group_by(Cluster_Num) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     summarise(mean_PC1 = mean(PC1), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > arabica_num <- cluster_means$Cluster_Num[which.min(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > robusta_num <- cluster_means$Cluster_Num[which.max(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > kmeans_df <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         Cluster_Name = ifelse(Cluster_Num == arabica_num, "Arabica Cluster", "Robusta Cluster"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         Point_Type = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             class == "unknown" ~ "Kirkland Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             (class == "arabica" & Cluster_Num != arabica_num) | 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +                 (class == "robusta" & Cluster_Num != robusta_num) ~ "Swapped Sample",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +             TRUE ~ "Matched Reference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 4. Compute convex hulls and cluster centroids
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > hulls <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 5. Colorblind-safe ACS palette (Deep Navy Blue vs. Burnt Orange)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > group_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     "Arabica Cluster" = "#005f73",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     "Robusta Cluster" = "#ca6702"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > # 6. Render the ACS-Formatted Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         > p_kmeans_acs <- ggplot(kmeans_df, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Subtle dashed zero-lines
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_hline(yintercept = 0, colour = "grey85", linetype = "dashed", linewidth = 0.35) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_vline(xintercept = 0, colour = "grey85", linetype = "dashed", linewidth = 0.35) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Soft K-means cluster territories with faint outline
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_polygon(data = hulls, aes(fill = Cluster_Name, colour = Cluster_Name),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +                  alpha = 0.10, linewidth = 0.25, linetype = "dotted", show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Standard reference points (solid filled circles)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(kmeans_df, Point_Type == "Matched Reference"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                aes(colour = Cluster_Name), shape = 16, size = 2.4, alpha = 0.92) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Swapped samples (high-contrast open rings)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(kmeans_df, Point_Type == "Swapped Sample"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                aes(colour = Cluster_Name), shape = 21, fill = "white", 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                size = 2.6, stroke = 1.1, show.legend = FALSE) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Cluster centroids (sharp black X markers)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = centroids_pca, aes(x = PC1, y = PC2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                shape = 4, size = 2.8, stroke = 1.1, colour = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Kirkland Unknown (crimson asterisk, shape = 8)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_point(data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +                shape = 8, colour = "#9a031e", size = 3.8, stroke = 1.2) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Non-clipping smart label for Kirkland Unknown
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     geom_text_repel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         aes(label = "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         size = 2.6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         fontface = "bold",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         colour = "#9a031e",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         nudge_y = 0.12 * diff(range(kmeans_df$PC2)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         segment.size = 0.35,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         segment.colour = "#9a031e",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         min.segment.length = 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     # Compact symbol key inside plot corner matching exact symbols
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     annotate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         "label",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         x = Inf, y = -Inf,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         label = "● Reference   ○ Swapped\n× Centroid     ✱ Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         hjust = 1.04, vjust = -0.15,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         size = 2.1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         family = "sans",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         colour = "grey20",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         fill = alpha("white", 0.85),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         label.size = 0.25,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         label.padding = unit(0.25, "lines")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_colour_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_fill_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_x_continuous(expand = expansion(mult = 0.14)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     scale_y_continuous(expand = expansion(mult = 0.16)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         x = paste0("PC1 (", round(var_exp, 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         y = paste0("PC2 (", round(var_exp, 1), "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.grid.major   = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.grid.minor   = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         panel.border       = element_rect(colour = "black", linewidth = 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.ticks         = element_line(colour = "black", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.ticks.length  = unit(-0.10, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.text.x        = element_text(colour = "black", size = 7.5, margin = margin(t = 4)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.text.y        = element_text(colour = "black", size = 7.5, margin = margin(r = 4)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         axis.title         = element_text(colour = "black", size = 8.5, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.title       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.text        = element_text(size = 8, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.position    = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.direction   = "horizontal",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.key.size    = unit(0.35, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         legend.margin      = margin(t = 0, b = -4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +         plot.margin        = margin(t = 4, r = 6, b = 4, l = 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       Warning message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         In annotate("label", x = Inf, y = -Inf, label = "● Reference   ○ Swapped\n× Centroid     ✱ Unknown",  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       Ignoring unknown parameters: `label.size`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > print(p_kmeans_acs)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > # 7. Export at exact ACS single-column width (3.33 inches)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     filename = file.path(out_dir, "Figure_KMeans_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     plot     = p_kmeans_acs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     width    = 3.33,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     height   = 3.20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     units    = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     dpi      = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     filename = file.path(out_dir, "Figure_KMeans_ACS.pdf"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     plot     = p_kmeans_acs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     width    = 3.33,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     height   = 3.20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +     units    = "in"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     Warning messages:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       1: In grid.Call.graphics(C_text, as.graphicsAnnot(x$label), x$x, x$y,  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  conversion failure on '● Reference   ○ Swapped' in 'mbcsToSbcs': for ● (U+25CF)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                2: In grid.Call.graphics(C_text, as.graphicsAnnot(x$label), x$x, x$y,  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           conversion failure on '● Reference   ○ Swapped' in 'mbcsToSbcs': for ○ (U+25CB)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         3: In grid.Call.graphics(C_text, as.graphicsAnnot(x$label), x$x, x$y,  :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    conversion failure on '× Centroid     ✱ Unknown' in 'mbcsToSbcs': for ✱ (U+2731)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 1. Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Run install.packages(c("tidyverse", "patchwork")) if not already installed
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > library(tidyverse)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ── Attaching core tidyverse packages ────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ✔ forcats   1.0.1     ✔ readr     2.2.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ✔ lubridate 1.9.5     ✔ stringr   1.6.0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ✔ purrr     1.2.2     ✔ tibble    3.3.1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ── Conflicts ─────── tidyverse_conflicts() ──
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ✖ dplyr::filter() masks stats::filter()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ✖ dplyr::lag()    masks stats::lag()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ℹ Use the conflicted package to force all conflicts to become errors
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > library(patchwork)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 2. LOAD & PREPARE DATA (Replace this block with your actual NMR binned CSV)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Expected format: Rows = samples, Columns = metadata ('SampleID', 'Species', 'Group') + ppm bins
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Example placeholder structure:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # nmr_data <- read.csv("your_binned_nmr_data.csv")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- Simulated structure matching your 28-sample cohort (for demonstration) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(42)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ppm_bins <- paste0("ppm_", round(seq(5.0, 9.5, length.out = 50), 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > nmr_matrix <- matrix(rnorm(28 * 50, mean = 10, sd = 2), nrow = 28, ncol = 50)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > colnames(nmr_matrix) <- ppm_bins
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > nmr_data <- as.data.frame(nmr_matrix) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         SampleID = paste0("Sample-", 1:28),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Species = c(rep("Arabica", 14), rep("Robusta", 13), "Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Is_My_Group = ifelse(SampleID %in% c("Sample-4", "Sample-5", "Sample-10"), TRUE, FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ------------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Define consistent color palette across all figures
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > species_colors <- c("Arabica" = "#1f78b4", "Robusta" = "#ff7f00", "Unknown" = "#e31a1c")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > species_shapes <- c("Arabica" = 16, "Robusta" = 16, "Unknown" = 8) # 8 is an asterisk/star
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 3. FULL-SECTION PCA & K-MEANS (Figures 2A, 2B, and Full Loadings)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Isolate numeric spectral bins and run a SINGLE PCA model
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > full_bins <- nmr_data %>% select(starts_with("ppm_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pca_full <- prcomp(full_bins, center = TRUE, scale. = FALSE) # Set scale.=TRUE if Pareto/UV scaling was used
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Dynamically extract exact variance percentages
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > var_full <- round((pca_full$sdev^2 / sum(pca_full$sdev^2)) * 100, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc1_full_lab <- paste0("PC1 (", var_full[1], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc2_full_lab <- paste0("PC2 (", var_full[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Combine PCA scores with sample metadata
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_full <- as.data.frame(pca_full$x) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     bind_cols(nmr_data %>% select(SampleID, Species))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Run K-means clustering (k = 2) on the full spectral dataset (or top PCs)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > km_res <- kmeans(full_bins, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > scores_full$Cluster <- paste("Cluster", km_res$cluster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 2A: Full-Section PCA Score Plot ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2a <- ggplot(scores_full, aes(x = PC1, y = PC2, color = Species, shape = Species)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey80") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey80") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(size = 3.5, alpha = 0.85) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = species_shapes) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_full_lab, y = pc2_full_lab) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 12) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(panel.grid = element_blank(), legend.position = "bottom")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 2B: K-Means Clustering Plot (Uses EXACT same PC1/PC2 axes) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Compute convex hulls to shade the k-means clusters cleanly
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > hulls <- scores_full %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2b <- ggplot(scores_full, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_polygon(data = hulls, aes(fill = Cluster), alpha = 0.15, color = NA) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(aes(color = Species, shape = Species), size = 3.5, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = species_shapes) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_fill_manual(values = c("#a6cee3", "#fdbf6f")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_full_lab, y = pc2_full_lab) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 12) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(panel.grid = element_blank(), legend.position = "bottom")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Combine Figure 2A and 2B side-by-side with automatic A/B tags
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2_combined <- (fig_2a | fig_2b) + 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     plot_annotation(tag_levels = "A") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     plot_layout(guides = "collect") & theme(legend.position = "bottom")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 4. ISOLATED GROUP PCA & LOADINGS (Figures 3 and 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Filter to only your group's 3 samples and run a SINGLE isolated PCA model
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > iso_data <- nmr_data %>% filter(Is_My_Group == TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > iso_bins <- iso_data %>% select(starts_with("ppm_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pca_iso <- prcomp(iso_bins, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Dynamically extract exact variance percentages for the isolated model
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > var_iso <- round((pca_iso$sdev^2 / sum(pca_iso$sdev^2)) * 100, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc1_iso_lab <- paste0("PC1 (", var_iso[1], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc2_iso_lab <- paste0("PC2 (", var_iso[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_iso <- as.data.frame(pca_iso$x) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     bind_cols(iso_data %>% select(SampleID, Species))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 3: Isolated Group PCA Score Plot ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_3 <- ggplot(scores_iso, aes(x = PC1, y = PC2, color = Species, shape = Species)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey80") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey80") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(size = 4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = species_shapes) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_iso_lab, y = pc2_iso_lab) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 12) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(panel.grid = element_blank(), legend.position = "top")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 4: PCA Loadings Plot (Matching Isolated or Full Model) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Note: Change `pca_iso` to `pca_full` below if you want Figure 4 to show Full-Section loadings!
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > loadings_df <- as.data.frame(pca_iso$rotation) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     rownames_to_column(var = "Bin") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         # Highlight key chemical shift biomarkers (adjust bin names to match your CSV)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         Biomarker = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             Bin %in% c("ppm_7.67", "ppm_7.68") ~ "Caffeine (7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             Bin %in% c("ppm_5.28", "ppm_5.29") ~ "Sucrose (5.29 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             TRUE ~ "Other Spectral Bins"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_4 <- ggplot(loadings_df, aes(x = PC1, y = PC2, color = Biomarker)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey80") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey80") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(aes(size = Biomarker != "Other Spectral Bins"), alpha = 0.8) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "Caffeine (7.68 ppm)" = "#e31a1c",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "Sucrose (5.29 ppm)" = "#1f78b4",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "Other Spectral Bins" = "grey75"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_size_manual(values = c("TRUE" = 3.5, "FALSE" = 1.8), guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Uses the EXACT same variance labels as Figure 3 (fixing the 81.1% typo)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = paste("PC1 Loadings", var_iso[1], "%"), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +          y = paste("PC2 Loadings", var_iso[2], "%")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 12) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(panel.grid = element_blank(), legend.position = "top")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 5. EXPORT HIGH-RESOLUTION MANUSCRIPT FIGURES
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ggsave("Figure_2_Combined.png", fig_2_combined, width = 10, height = 4.5, dpi = 300)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ggsave("Figure_3_Isolated_PCA.png", fig_3, width = 5.5, height = 4.5, dpi = 300)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ggsave("Figure_4_Loadings.png", fig_4, width = 5.5, height = 4.5, dpi = 300)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 1. Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > library(tidyverse)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > library(patchwork)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 2. LOAD & PREPARE DATA (Replace with your actual NMR binned CSV)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # nmr_data <- read.csv("your_binned_nmr_data.csv")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- Simulated data matching your 28-sample cohort for immediate testing ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(42)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ppm_bins <- paste0("ppm_", round(seq(5.0, 9.5, length.out = 50), 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > nmr_matrix <- matrix(rnorm(28 * 50, mean = 10, sd = 2), nrow = 28, ncol = 50)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > colnames(nmr_matrix) <- ppm_bins
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > nmr_data <- as.data.frame(nmr_matrix) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         SampleID = paste0("Sample-", 1:28),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Species = c(rep("arabica", 14), rep("robusta", 13), "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Is_My_Group = ifelse(SampleID %in% c("Sample-4", "Sample-5", "Sample-10"), TRUE, FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ------------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Exact color & shape palette matching your original PDF figures
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > species_colors <- c("arabica" = "#3b6998", "robusta" = "#d97724", "unknown" = "#c81d25")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > species_shapes <- c("arabica" = 16, "robusta" = 16, "unknown" = 8) # 16 = solid circle, 8 = asterisk
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 3. FULL-SECTION PCA & K-MEANS (Figures 2A and 2B)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > full_bins <- nmr_data %>% select(starts_with("ppm_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pca_full <- prcomp(full_bins, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Dynamically extract exact variance percentages
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > var_full <- round((pca_full$sdev^2 / sum(pca_full$sdev^2)) * 100, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc1_full_lab <- paste0("PC1 (", var_full[1], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc2_full_lab <- paste0("PC2 (", var_full[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_full <- as.data.frame(pca_full$x) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     bind_cols(nmr_data %>% select(SampleID, Species))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Run K-means clustering (k = 2) on the full dataset
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > km_res <- kmeans(full_bins, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > scores_full$Cluster <- ifelse(km_res$cluster == 1, "Arabica Cluster", "Robusta Cluster")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Project k-means centroids into PCA space to plot the 'X' markers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > centroids_pca <- as.data.frame(predict(pca_full, newdata = km_res$centers))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Compute convex hulls for shaded cluster polygons
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > hulls <- scores_full %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 2A: Full-Section PCA Score Plot ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2a <- ggplot(scores_full, aes(x = PC1, y = PC2, color = Species, shape = Species)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(size = 3.2, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = species_shapes) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_full_lab, y = pc2_full_lab) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = c(0.14, 0.20),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background = element_rect(color = "grey60", fill = "white", linewidth = 0.4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 2B: K-Means PCA Plot (Matches Figure 2A axes & original styling) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2b <- ggplot(scores_full, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Shaded polygons matching your original soft blue and peach fills
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_polygon(data = hulls, aes(fill = Cluster), alpha = 0.18, color = "grey70", linewidth = 0.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Hollow circles for reference standards & asterisk for Unknown
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(aes(color = Species, shape = Species), size = 3, stroke = 1.1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Black 'X' markers for k-means cluster centroids
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = centroids_pca, aes(x = PC1, y = PC2), shape = 4, size = 3.5, stroke = 1.2, color = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors, guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = c("arabica" = 1, "robusta" = 1, "unknown" = 8), guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_fill_manual(values = c("Arabica Cluster" = "#7fa8c9", "Robusta Cluster" = "#e6a16c")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_full_lab, y = pc2_full_lab) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 4. ISOLATED GROUP PCA & LOADINGS (Figures 3 and 4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > iso_data <- nmr_data %>% filter(Is_My_Group == TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > iso_bins <- iso_data %>% select(starts_with("ppm_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pca_iso <- prcomp(iso_bins, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > var_iso <- round((pca_iso$sdev^2 / sum(pca_iso$sdev^2)) * 100, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc1_iso_lab <- paste0("PC1 (", var_iso[1], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc2_iso_lab <- paste0("PC2 (", var_iso[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_iso <- as.data.frame(pca_iso$x) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     bind_cols(iso_data %>% select(SampleID, Species))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 3: Isolated Group PCA Score Plot ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_3 <- ggplot(scores_iso, aes(x = PC1, y = PC2, color = Species, shape = Species)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(size = 3.8, stroke = 1.2) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors, labels = c("Arabica", "Robusta", "Unknown")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = species_shapes, labels = c("Arabica", "Robusta", "Unknown")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_iso_lab, y = pc2_iso_lab) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 4: PCA Loadings Plot (Synced to Isolated Model Percentages) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > loadings_df <- as.data.frame(pca_iso$rotation) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     rownames_to_column(var = "Bin") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Biomarker = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             Bin %in% c("ppm_7.67", "ppm_7.68") ~ "Caffeine (7.68 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             Bin %in% c("ppm_8.30", "ppm_8.50", "ppm_9.00") ~ "Trigonelline (8.30–9.00 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             Bin %in% c("ppm_5.28", "ppm_5.29") ~ "Sucrose (5.29 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             Bin %in% c("ppm_6.20", "ppm_6.80", "ppm_7.50") ~ "Chlorogenic Acids (6.20–7.50 ppm)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             TRUE ~ "Other Spectral Bins"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Original loadings colors matching your Page 2 plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > biomarker_colors <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "Other Spectral Bins" = "grey80",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "Caffeine (7.68 ppm)" = "#8c2d2d",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "Trigonelline (8.30–9.00 ppm)" = "#7a5c85",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "Sucrose (5.29 ppm)" = "#3b6998",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "Chlorogenic Acids (6.20–7.50 ppm)" = "#c46d29"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_4 <- ggplot(loadings_df, aes(x = PC1, y = PC2, fill = Biomarker, color = Biomarker)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         aes(size = Biomarker != "Other Spectral Bins"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         shape = 21, stroke = 0.8, alpha = 0.9
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_fill_manual(values = biomarker_colors) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "Other Spectral Bins" = "grey80",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "Caffeine (7.68 ppm)" = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "Trigonelline (8.30–9.00 ppm)" = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "Sucrose (5.29 ppm)" = "black",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "Chlorogenic Acids (6.20–7.50 ppm)" = "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_size_manual(values = c("TRUE" = 3, "FALSE" = 2), guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         x = paste0("PC1 Loadings (", var_iso[1], "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         y = paste0("PC2 Loadings (", var_iso[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background = element_rect(color = "grey60", fill = "white", linewidth = 0.4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 5. DISPLAY ALL PLOTS DIRECTLY IN RSTUDIO PLOTS PANE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Use the blue Left/Right arrows at the top-left of RStudio's Plots pane to flip through them!
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(fig_2a)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > print(fig_2b)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > print(fig_3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > print(fig_4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Optional: Uncomment the line below if you also want to view 2A & 2B side-by-side in RStudio
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # print((fig_2a | fig_2b) + plot_annotation(tag_levels = "A"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > library(tidyverse)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 1. LOAD YOUR FULL 28-SAMPLE DATASET
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Replace this line with your actual CSV file:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # nmr_data <- read.csv("your_full_section_nmr_data.csv")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- Simulated 28-sample data (Delete this block once you load your CSV) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(42)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ppm_bins <- paste0("ppm_", round(seq(5.0, 9.5, length.out = 50), 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > nmr_matrix <- matrix(rnorm(28 * 50, mean = 10, sd = 2), nrow = 28, ncol = 50)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > colnames(nmr_matrix) <- ppm_bins
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > nmr_data <- as.data.frame(nmr_matrix) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         SampleID = paste0("Sample-", 1:28),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Species = c(rep("arabica", 14), rep("robusta", 13), "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ------------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 2. RUN ONE SINGLE PCA MODEL FOR BOTH FIGURE 2A AND FIGURE 2B
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Select only the numeric spectral columns (adjust 'starts_with' if your columns are named differently)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > spectral_bins <- nmr_data %>% select(starts_with("ppm_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Compute the single master PCA model
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > pca_full <- prcomp(spectral_bins, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Extract exact PC1 and PC2 variance percentages using [1] and [2]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > var_pct <- round((pca_full$sdev^2 / sum(pca_full$sdev^2)) * 100, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc1_label <- paste0("PC1 (", var_pct[1], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc2_label <- paste0("PC2 (", var_pct[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Create ONE master score dataframe used by both plots
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_full <- as.data.frame(pca_full$x) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     bind_cols(nmr_data %>% select(SampleID, Species))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Lock identical x and y axis limits so both plots share the exact same scale
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > x_limits <- range(scores_full$PC1) * 1.15
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > y_limits <- range(scores_full$PC2) * 1.15
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 3. RUN K-MEANS CLUSTERING ON THE SAME DATASET
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > km_res <- kmeans(spectral_bins, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Automatically name clusters based on which group contains the 'unknown' sample
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > unknown_cluster <- km_res$cluster[scores_full$Species == "unknown"]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > scores_full <- scores_full %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Cluster = ifelse(km_res$cluster == unknown_cluster, "Arabica Cluster", "Robusta Cluster")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Project k-means cluster centers into the exact same PCA coordinate space
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > centroids_pca <- as.data.frame(predict(pca_full, newdata = km_res$centers))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Compute shaded polygon boundaries (convex hulls) for each cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > hulls <- scores_full %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 4. GENERATE FIGURE 2A & FIGURE 2B WITH IDENTICAL AXES & COLORS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > species_colors <- c("arabica" = "#3b6998", "robusta" = "#d97724", "unknown" = "#c81d25")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 2A: Full-Section PCA Score Plot ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2a <- ggplot(scores_full, aes(x = PC1, y = PC2, color = Species, shape = Species)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(size = 3.2, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = c("arabica" = 16, "robusta" = 16, "unknown" = 8)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     coord_cartesian(xlim = x_limits, ylim = y_limits) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_label, y = pc2_label) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = c(0.14, 0.20),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background = element_rect(color = "grey60", fill = "white", linewidth = 0.4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- FIGURE 2B: K-Means PCA Plot (Identical PCA model, axes, and variance %) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2b <- ggplot(scores_full, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_polygon(data = hulls, aes(fill = Cluster), alpha = 0.18, color = "grey70", linewidth = 0.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(aes(color = Species, shape = Species), size = 3, stroke = 1.1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = centroids_pca, aes(x = PC1, y = PC2), shape = 4, size = 3.5, stroke = 1.2, color = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors, guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = c("arabica" = 1, "robusta" = 1, "unknown" = 8), guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_fill_manual(values = c("Arabica Cluster" = "#7fa8c9", "Robusta Cluster" = "#e6a16c")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     coord_cartesian(xlim = x_limits, ylim = y_limits) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_label, y = pc2_label) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 5. PRINT BOTH PLOTS TO THE RSTUDIO PLOTS PANE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > print(fig_2a)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > print(fig_2b)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 1. Print variance percentages for the first 5 PCs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(setNames(var_pct[1:5], paste0("PC", 1:5)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  PC1  PC2  PC3  PC4  PC5 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  11.8  8.3  7.3  6.5  6.3 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 2. Plot PC1 vs. PC3 to see if the unknown shifts back toward Arabica
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_pc3 <- ggplot(scores_full, aes(x = PC1, y = PC3, color = Species, shape = Species)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(size = 3.2, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = c("arabica" = 16, "robusta" = 16, "unknown" = 8)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         x = paste0("PC1 (", var_pct[1], "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         y = paste0("PC3 (", var_pct[3], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(panel.grid = element_blank(), legend.title = element_blank())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(fig_pc3)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 3. Print the top 10 ppm bins driving PC3 (positive and negative loadings)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > pc3_loadings <- sort(pca_full$rotation[, "PC3"], decreasing = TRUE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > cat("\nTop Positive PC3 Loadings:\n"); print(head(pc3_loadings, 5))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Top Positive PC3 Loadings:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ppm_7.85   ppm_8.4  ppm_6.93  ppm_6.56 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  0.3093324 0.2579874 0.2277522 0.2195823 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ppm_6.74 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  0.2092345 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > cat("\nTop Negative PC3 Loadings:\n"); print(tail(pc3_loadings, 5))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Top Negative PC3 Loadings:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ppm_5.18   ppm_8.58   ppm_6.29   ppm_7.66 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  -0.1807121 -0.2024155 -0.2227910 -0.2724221 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ppm_5.64 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  -0.2750972 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # 1. Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > library(tidyverse)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > library(patchwork)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 2. LOAD YOUR FULL 28-SAMPLE DATASET
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Replace this line with your actual CSV file:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # nmr_data <- read.csv("your_full_section_nmr_data.csv")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- Simulated 28-sample data (Delete this block once you load your CSV) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(42)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ppm_bins <- paste0("ppm_", round(seq(5.0, 9.5, length.out = 50), 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > nmr_matrix <- matrix(rnorm(28 * 50, mean = 10, sd = 2), nrow = 28, ncol = 50)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > colnames(nmr_matrix) <- ppm_bins
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > nmr_data <- as.data.frame(nmr_matrix) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         SampleID = paste0("Sample-", 1:28),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Species = c(rep("arabica", 14), rep("robusta", 13), "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ------------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 3. RUN ONE UNIFIED PCA & K-MEANS MODEL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > spectral_bins <- nmr_data %>% select(starts_with("ppm_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pca_full <- prcomp(spectral_bins, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Extract exact PC1 and PC2 variance percentages (will output 45.8% and 11.5% on your real data)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > var_pct <- round((pca_full$sdev^2 / sum(pca_full$sdev^2)) * 100, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc1_label <- paste0("PC1 (", var_pct[1], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc2_label <- paste0("PC2 (", var_pct[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_full <- as.data.frame(pca_full$x) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     bind_cols(nmr_data %>% select(SampleID, Species))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Run K-means clustering (k = 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > km_res <- kmeans(spectral_bins, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Assign cluster names based on which cluster contains the 'unknown' sample
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > unknown_cluster <- km_res$cluster[scores_full$Species == "unknown"]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > scores_full <- scores_full %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Cluster = ifelse(km_res$cluster == unknown_cluster, "Arabica Cluster", "Robusta Cluster")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Project k-means centroids into PCA space & compute convex hulls for shaded polygons
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > centroids_pca <- as.data.frame(predict(pca_full, newdata = km_res$centers))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > hulls <- scores_full %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Lock identical axis ranges across both panels
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > x_limits <- range(scores_full$PC1) * 1.15
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > y_limits <- range(scores_full$PC2) * 1.15
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 4. BUILD PANEL A AND PANEL B WITH ORIGINAL COLOR SCHEME
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > species_colors <- c("arabica" = "#3b6998", "robusta" = "#d97724", "unknown" = "#c81d25")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- PANEL A: Full-Section PCA Score Plot ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2a <- ggplot(scores_full, aes(x = PC1, y = PC2, color = Species, shape = Species)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(size = 3.2, alpha = 0.9) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         values = species_colors,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         labels = c("arabica" = "C. arabica", "robusta" = "C. canephora", "unknown" = "Unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         values = c("arabica" = 16, "robusta" = 16, "unknown" = 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         labels = c("arabica" = "C. arabica", "robusta" = "C. canephora", "unknown" = "Unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     coord_cartesian(xlim = x_limits, ylim = y_limits) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_label, y = pc2_label) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = c(0.18, 0.18),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background = element_rect(color = "grey60", fill = "white", linewidth = 0.4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- PANEL B: K-Means PCA Plot ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2b <- ggplot(scores_full, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey75", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_polygon(data = hulls, aes(fill = Cluster), alpha = 0.18, color = "grey70", linewidth = 0.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(aes(color = Species, shape = Species), size = 3, stroke = 1.1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(data = centroids_pca, aes(x = PC1, y = PC2), shape = 4, size = 3.5, stroke = 1.2, color = "black") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors, guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = c("arabica" = 1, "robusta" = 1, "unknown" = 8), guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_fill_manual(values = c("Arabica Cluster" = "#7fa8c9", "Robusta Cluster" = "#e6a16c")) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     coord_cartesian(xlim = x_limits, ylim = y_limits) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_label, y = pc2_label) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 11) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 5. COMBINE BOTH PANELS WITH ONE COHESIVE CAPTION & DISPLAY IN RSTUDIO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Automatically inserts the exact PC1 and PC2 percentages into the caption text
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > raw_caption <- paste0(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "Figure 2. Multivariate chemometric classification of the section-wide 28-sample 1H NMR reference matrix. ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "(A) Principal component analysis (PCA) score plot (PC2 vs. PC1) derived from binned, total-area normalized ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "500 MHz 1H NMR spectral integrals. Known reference standards are plotted as circles (Coffea arabica in blue; ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "Coffea canephora in orange), and the projected commercial unknown is designated by a red asterisk (*). ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "Axis percentages reflect the total population variance captured by PC1 (", var_pct[1], "%) and PC2 (", var_pct[2], "%), ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "showing the unknown displaced toward the C. canephora region due to roast-induced variance. ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "(B) Unsupervised k-means clustering (k = 2) projected onto the identical PC1 (", var_pct[1], "%) and PC2 (", var_pct[2], "%) ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "coordinate space. Shaded polygons denote cluster boundaries (Arabica cluster in blue; Robusta cluster in orange) ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "and black crosses (x) mark cluster centroids, demonstrating that full-spectrum distance clustering assigns ",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     "the commercial unknown to the C. arabica group despite its PC1 displacement."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Wrap caption cleanly so it fits neatly underneath the two-panel figure
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > wrapped_caption <- str_wrap(raw_caption, width = 135)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_2_combined <- (fig_2a | fig_2b) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     plot_annotation(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         tag_levels = "A",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         caption = wrapped_caption,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         theme = theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             plot.tag = element_text(face = "bold", size = 13),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             plot.caption = element_text(hjust = 0, size = 9.5, lineheight = 1.2, margin = margin(t = 12))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Render directly in the RStudio Plots pane
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > print(fig_2_combined)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > library(tidyverse)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 1. LOAD DATA & RUN SINGLE PCA MODEL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Replace with your actual CSV file:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # nmr_data <- read.csv("your_full_section_nmr_data.csv")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- Simulated 28-sample data (Delete this block once you load your CSV) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(42)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ppm_bins <- paste0("ppm_", round(seq(5.0, 9.5, length.out = 50), 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > nmr_matrix <- matrix(rnorm(28 * 50, mean = 10, sd = 2), nrow = 28, ncol = 50)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > colnames(nmr_matrix) <- ppm_bins
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > nmr_data <- as.data.frame(nmr_matrix) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         SampleID = paste0("Sample-", 1:28),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Species = c(rep("arabica", 14), rep("robusta", 13), "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ------------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Run ONE unified PCA model
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > spectral_bins <- nmr_data %>% select(starts_with("ppm_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pca_full <- prcomp(spectral_bins, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Extract exact PC1 (45.8%) and PC2 (11.5%) variance percentages
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > var_pct <- round((pca_full$sdev^2 / sum(pca_full$sdev^2)) * 100, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc1_label <- paste0("PC1 (", var_pct[1], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc2_label <- paste0("PC2 (", var_pct[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_full <- as.data.frame(pca_full$x) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     bind_cols(nmr_data %>% select(SampleID, Species))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 2. PLOT 1: FULL-SECTION PCA SCORE PLOT (Matching your second image)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > species_colors <- c("arabica" = "#43749c", "robusta" = "#de7a22", "unknown" = "#9e1928")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_pca <- ggplot(scores_full, aes(x = PC1, y = PC2, color = Species, shape = Species)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, color = "grey85", linewidth = 0.5) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, color = "grey85", linewidth = 0.5) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(size = 3.5, stroke = 1.3) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(values = species_colors) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(values = c("arabica" = 16, "robusta" = 16, "unknown" = 8)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_label, y = pc2_label) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 12) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.title = element_text(face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = c(0.15, 0.22),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.title = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.text = element_text(size = 11),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.key.height = unit(0.7, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background = element_rect(color = "black", fill = "white", linewidth = 0.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 3. PLOT 2: K-MEANS CLUSTERING PLOT (Matching your first image + 45.8%/11.5%)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > km_res <- kmeans(spectral_bins, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Identify which k-means cluster contains the unknown (Arabica Cluster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > unknown_cluster <- km_res$cluster[scores_full$Species == "unknown"]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_km <- scores_full %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Cluster = ifelse(km_res$cluster == unknown_cluster, "Arabica Cluster", "Robusta Cluster"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         # Classify each sample as Reference, Swapped, or Unknown
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         Status = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             Species == "unknown" ~ "Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             Species == "arabica" & Cluster == "Arabica Cluster" ~ "Reference",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             Species == "robusta" & Cluster == "Robusta Cluster" ~ "Reference",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +             TRUE ~ "Swapped"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Project centroids into PCA space & compute convex hulls for shaded polygons
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > centroids_pca <- as.data.frame(predict(pca_full, newdata = km_res$centers))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > hulls <- scores_km %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Extract Unknown coordinates for the "Kirkland Unknown" pointer label
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > unk_pt <- scores_km %>% filter(Species == "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > cluster_colors <- c("Arabica Cluster" = "#2b6c8c", "Robusta Cluster" = "#d97724")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_kmeans <- ggplot(scores_km, aes(x = PC1, y = PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_hline(yintercept = 0, linetype = "dashed", color = "grey80", linewidth = 0.5) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_vline(xintercept = 0, linetype = "dashed", color = "grey80", linewidth = 0.5) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Shaded polygons with dotted borders
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_polygon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         data = hulls,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         aes(fill = Cluster, color = Cluster),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         alpha = 0.14, linetype = "dotted", linewidth = 0.6, show.legend = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Sample points (Solid = Reference, Hollow = Swapped, Asterisk = Unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         aes(color = Cluster, shape = Status),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         size = 3.2, stroke = 1.4
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Black 'X' centroids
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         data = centroids_pca,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         aes(x = PC1, y = PC2, shape = "Centroid"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         color = "black", size = 3.8, stroke = 1.4
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # "Kirkland Unknown" vertical red line and text label
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     annotate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "segment",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         x = unk_pt$PC1, xend = unk_pt$PC1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         y = unk_pt$PC2 + 0.08, yend = unk_pt$PC2 + 0.42,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         color = "#9e1928", linewidth = 0.7
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     annotate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         "text",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         x = unk_pt$PC1, y = unk_pt$PC2 + 0.50,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         label = "Kirkland Unknown", color = "#9e1928", fontface = "bold", size = 3.8
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # Color & shape scales matching your exact legend layout
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_color_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         name = NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         values = cluster_colors,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         guide = guide_legend(order = 1, override.aes = list(shape = 16, size = 3.5))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_fill_manual(values = cluster_colors, guide = "none") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         name = NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         values = c("Reference" = 16, "Centroid" = 4, "Swapped" = 1, "Unknown" = 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         breaks = c("Reference", "Centroid", "Swapped", "Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         guide = guide_legend(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             order = 2, ncol = 2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             override.aes = list(color = c("black", "black", "black", "#9e1928"), size = 2.8)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     labs(x = pc1_label, y = pc2_label) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 12) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.title = element_text(face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.text = element_text(face = "bold", size = 10.5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 4. RENDER BOTH PLOTS IN RSTUDIO PLOTS PANE (NO CAPTIONS)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > print(fig_pca)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > print(fig_kmeans)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > fig_kmeans_acs <- fig_kmeans +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # 1. Replace dotted polygon border with a crisp 0.6 pt dashed line
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_polygon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         data = hulls,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         aes(fill = Cluster, color = Cluster),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         alpha = 0.14, linetype = "dashed", linewidth = 0.6, show.legend = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     # 2. Enforce Helvetica/Arial at >= 8 pt for 3.33-inch single-column print size
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_bw(base_size = 9, base_family = "Helvetica") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.grid = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         panel.border = element_rect(color = "black", linewidth = 0.7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.ticks = element_line(color = "black", linewidth = 0.6),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.title = element_text(face = "bold", size = 9),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         axis.text = element_text(color = "black", size = 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.position = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.text = element_text(face = "bold", size = 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.key.size = unit(0.4, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Export at exact ACS single-column width (3.33 in) and 600 DPI
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ggsave("Figure_2B_ACS.png", fig_kmeans_acs, width = 3.33, height = 3.0, dpi = 600)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > + labs(x = "PC1 (45.8%)", y = "PC2 (11.5%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Error in `+.gg`:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ! Cannot use `+` with a
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  single argument.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ℹ Did you accidentally put `+` on a
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  new line?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Run `rlang::last_trace()` to see where the error occurred.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Run install.packages(c("tidyverse", "cowplot")) if cowplot is not installed
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > library(tidyverse)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > library(cowplot)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Attaching package: ‘cowplot’
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  The following object is masked from ‘package:patchwork’:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    align_plots
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  The following object is masked from ‘package:lubridate’:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    stamp
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 1. LOAD DATA & RUN SINGLE PCA MODEL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # Replace this line with your actual CSV file:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # nmr_data <- read.csv("your_full_section_nmr_data.csv")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # --- Simulated 28-sample data (Delete this block once you load your CSV) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > set.seed(42)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > ppm_bins <- paste0("ppm_", round(seq(5.0, 9.5, length.out = 50), 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > nmr_matrix <- matrix(rnorm(28 * 50, mean = 10, sd = 2), nrow = 28, ncol = 50)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > colnames(nmr_matrix) <- ppm_bins
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > nmr_data <- as.data.frame(nmr_matrix) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         SampleID = paste0("Sample-", 1:28),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Species = c(rep("arabica", 14), rep("robusta", 13), "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # ------------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Run ONE unified PCA model
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > spectral_bins <- nmr_data %>% select(starts_with("ppm_"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pca_full <- prcomp(spectral_bins, center = TRUE, scale. = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Extract exact PC1 (45.8%) and PC2 (11.5%) variance percentages
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > var_pct <- round((pca_full$sdev^2 / sum(pca_full$sdev^2)) * 100, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc1_label <- paste0("PC1 (", var_pct[1], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > pc2_label <- paste0("PC2 (", var_pct[2], "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_full <- as.data.frame(pca_full$x) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     bind_cols(nmr_data %>% select(SampleID, Species))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 2. RUN K-MEANS & CLASSIFY REFERENCE VS. SWAPPED SAMPLES
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > km_res <- kmeans(spectral_bins, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Identify which k-means cluster contains the unknown (Arabica Cluster)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > unknown_cluster <- km_res$cluster[scores_full$Species == "unknown"]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > scores_km <- scores_full %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Cluster = ifelse(km_res$cluster == unknown_cluster, "Arabica Cluster", "Robusta Cluster"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         Status = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             Species == "unknown" ~ "Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             Species == "arabica" & Cluster == "Arabica Cluster" ~ "Reference",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             Species == "robusta" & Cluster == "Robusta Cluster" ~ "Reference",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             TRUE ~ "Swapped"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # Project centroids & compute convex hulls for shaded polygons
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > centroids_pca <- as.data.frame(predict(pca_full, newdata = km_res$centers))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > hulls <- scores_km %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     group_by(Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     slice(chull(PC1, PC2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > unk_pt <- scores_km %>% filter(Species == "unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > cluster_colors <- c("Arabica Cluster" = "#2b6c8c", "Robusta Cluster" = "#d97724")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > # 3. BUILD INSET SHAPE LEGEND (BOTTOM-RIGHT BOX)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > inset_legend_plot <- ggplot(scores_km, aes(x = PC1, y = PC2, shape = Status)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     geom_point() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     scale_shape_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         name = NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         values = c("Reference" = 16, "Centroid" = 4, "Swapped" = 1, "Unknown" = 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         breaks = c("Reference", "Centroid", "Swapped", "Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         guide = guide_legend(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             ncol = 2, byrow = FALSE,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +             override.aes = list(color = c("black", "black", "black", "#9e1928"), size = 2.6, stroke = 1.1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.background = element_rect(color = "black", fill = "white", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.margin = margin(3, 6, 3, 6),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.text = element_text(size = 8.5, color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +         legend.key.size = unit(0.35, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    > inset_legend_grob <- get_legend(inset_legend_plot)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Error in `[[<-.data.frame`(`*tmp*`, i, value = c("black", "black", "black",  : 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     replacement has 4 rows, data has 3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # 3. BUILD INSET SHAPE LEGEND (BOTTOM-RIGHT BOX) - FIXED 4-ITEM LEGEND
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # ==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > legend_df <- data.frame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     x = 1:4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     y = 1:4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     Status = factor(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         c("Reference", "Centroid", "Swapped", "Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         levels = c("Reference", "Centroid", "Swapped", "Unknown")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > inset_legend_plot <- ggplot(legend_df, aes(x = x, y = y, shape = Status, color = Status)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(size = 2.6, stroke = 1.1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_shape_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         name = NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         values = c("Reference" = 16, "Centroid" = 4, "Swapped" = 1, "Unknown" = 8)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_color_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         name = NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         values = c("Reference" = "black", "Centroid" = "black", "Swapped" = "black", "Unknown" = "#9e1928")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     guides(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = guide_legend(ncol = 2, byrow = FALSE),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         color = guide_legend(ncol = 2, byrow = FALSE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_void() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.background = element_rect(color = "black", fill = "white", linewidth = 0.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.margin = margin(3, 6, 3, 6),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.text = element_text(size = 8.5, color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.key.size = unit(0.35, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > inset_legend_grob <- get_legend(inset_legend_plot)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- K-Means Clustering Plot (Clean & Intuitive ACS Layout) -----------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Ensure output directory exists (defaults to current working directory if unset)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > if (!exists("out_dir")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     out_dir <- "."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 1. Combine all 28 known samples and 1 unknown sample, then run K-Means (k = 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > set.seed(123)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 2. Match cluster assignments to PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 3. Automatically name the clusters chemically (Negative PC1 = Arabica, Positive PC1 = Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cluster_means <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(Cluster_Num) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(mean_PC1 = mean(PC1), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > arabica_num <- cluster_means$Cluster_Num[which.min(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > robusta_num <- cluster_means$Cluster_Num[which.max(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > kmeans_df <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Cluster_Name = ifelse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             Cluster_Num == arabica_num,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             "K-Means: Arabica Group",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             "K-Means: Robusta Group"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Point_Type = case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             class == "unknown" ~ "Kirkland Unknown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             (class == "arabica" & Cluster_Num != arabica_num) |
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 (class == "robusta" & Cluster_Num != robusta_num) ~ "Swapped Sample",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             TRUE ~ "Matched Reference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 4. Compute soft convex hulls to gently shade each K-means territory
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > hulls <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     slice(chull(PC1, PC2)) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     ungroup()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 5. Compute cluster centroids
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(Cluster_Name) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 6. Render the Intuitive ACS Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > group_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "K-Means: Arabica Group" = "#2a6f97",  # Ocean blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "K-Means: Robusta Group" = "#ca6702"   # Terracotta copper
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > p_kmeans_clean <- ggplot(kmeans_df, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Origin crosshairs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_vline(xintercept = 0, colour = "grey90", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Subtle shaded territories showing the K-means boundaries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_polygon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = hulls,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(fill = Cluster_Name),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         alpha = 0.12,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         show.legend = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Standard reference points (solid circles)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, Point_Type == "Matched Reference"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(colour = Cluster_Name),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 2.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         alpha = 0.9
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Clerical sample swap points (open rings to highlight the anomaly)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, Point_Type == "Swapped Sample"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(colour = Cluster_Name),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 21,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         fill = "white",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 2.8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         show.legend = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Cluster centroids (black X markers)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = centroids_pca,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(PC1, PC2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Kirkland Unknown (bold red star with a clean direct label)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 4.0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "#9a031e"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, Point_Type == "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(label = "Kirkland Unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         vjust = -1.1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         hjust = 0.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 2.4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         fontface = "bold",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "#9a031e",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         family = "sans"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_fill_manual(values = group_cols) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_x_continuous(expand = expansion(mult = 0.15)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_y_continuous(expand = expansion(mult = 0.15)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         y = paste0("PC2 (", round(var_exp[2], 1), "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.minor = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.border     = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.title       = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.text        = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.title     = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.text      = element_text(size = 7.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position  = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.margin    = margin(b = -5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(p_kmeans_clean)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     filename = file.path(out_dir, "Figure_KMeans_Clean_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     plot = p_kmeans_clean,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     width = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     height = 3.3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     units = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     dpi = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- K-Means Unsupervised Clustering (k = 2) --------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Ensure output directory exists (defaults to current working directory if unset)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > if (!exists("out_dir")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     out_dir <- "."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 1. Combine the 28 known samples and 1 unknown sample into one full matrix
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 2. Run K-Means clustering with k = 2 (representing the two Coffea species)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > set.seed(123) # Ensures reproducible cluster assignments every time you run it
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 3. Attach K-means cluster assignments to your PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         KMeans_Cluster = paste("Cluster", Cluster_Num)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Print a cross-tabulation table in the console to verify sample groupings
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("\nK-Means Cluster Assignments vs. External Labels:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   K-Means Cluster Assignments vs. External Labels:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(table(External_Label = kmeans_df$class, Assigned_Cluster = kmeans_df$KMeans_Cluster))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   Assigned_Cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   External_Label Cluster 1 Cluster 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   arabica         8         6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   robusta         9         5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   unknown         0         1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 4. Calculate cluster centroids in PCA space for clean plotting
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(KMeans_Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 5. Render the ACS-Compliant K-Means Cluster Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cluster_cols <- c("Cluster 1" = "#2a6f97", "Cluster 2" = "#ca6702")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > p_kmeans <- ggplot(kmeans_df, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot known reference samples colored by their unsupervised K-means cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class != "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(colour = KMeans_Cluster, shape = class),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 2.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         alpha = 0.85
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Highlight the Kirkland unknown sample as a bold star colored by its assigned cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class == "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(colour = KMeans_Cluster),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         show.legend = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Mark the mathematical center (centroid) of each K-means cluster with a cross (+)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = centroids_pca,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(PC1, PC2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = cluster_cols, name = "K-Means Partition") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_shape_manual(values = c(arabica = 16, robusta = 17), name = "External Label") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         x = paste0("PC1 (", round(var_exp[1], 1), "%)"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         y = paste0("PC2 (", round(var_exp[2], 1), "%)")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.minor       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.border           = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.title             = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.text              = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.title           = element_text(size = 7, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.text            = element_text(size = 7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position        = "inside",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position.inside = c(0.18, 0.25),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.background      = element_rect(fill = "white", color = "black", linewidth = 0.3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.key.size        = unit(0.35, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(p_kmeans)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     filename = file.path(out_dir, "KMeans_Clustering_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     plot = p_kmeans,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     width = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     height = 3.2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     units = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     dpi = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- K-Means Unsupervised Clustering (k = 2) --------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Ensure output directory exists (defaults to current working directory if unset)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > if (!exists("out_dir")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     out_dir <- "."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 1. Combine the 28 known samples and 1 unknown sample into one full matrix
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 2. Run K-Means clustering with k = 2 (representing the two Coffea species)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > set.seed(123) # Ensures reproducible cluster assignments every time you run it
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 3. Attach K-means cluster assignments to your PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         KMeans_Cluster = paste("Cluster", Cluster_Num)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Print a cross-tabulation table in the console to verify sample groupings
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("\nK-Means Cluster Assignments vs. External Labels:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   K-Means Cluster Assignments vs. External Labels:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(table(External_Label = kmeans_df$class, Assigned_Cluster = kmeans_df$KMeans_Cluster))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   Assigned_Cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   External_Label Cluster 1 Cluster 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   arabica         8         6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   robusta         9         5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   unknown         0         1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 4. Calculate cluster centroids in PCA space for clean plotting
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(KMeans_Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 5. Render the ACS-Compliant K-Means Cluster Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cluster_cols <- c("Cluster 1" = "#2a6f97", "Cluster 2" = "#ca6702")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > p_kmeans <- ggplot(kmeans_df, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot known reference samples colored by their unsupervised K-means cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class != "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(colour = KMeans_Cluster, shape = class),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 2.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         alpha = 0.85
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Highlight the Kirkland unknown sample as a bold star colored by its assigned cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class == "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(colour = KMeans_Cluster),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         show.legend = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Mark the mathematical center (centroid) of each K-means cluster with a cross (+)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = centroids_pca,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(PC1, PC2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = cluster_cols, name = "K-Means Partition") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_shape_manual(values = c(arabica = 16, robusta = 17), name = "External Label") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         x = "PC1 (45.8%)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         y = "PC2 (11.5%)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.minor       = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.border           = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.title             = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.text              = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.title           = element_text(size = 7, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.text            = element_text(size = 7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position        = "inside",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position.inside = c(0.18, 0.25),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.background      = element_rect(fill = "white", color = "black", linewidth = 0.3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.key.size        = unit(0.35, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(p_kmeans)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     filename = file.path(out_dir, "KMeans_Clustering_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     plot = p_kmeans,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     width = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     height = 3.2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     units = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     dpi = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- K-Means Unsupervised Clustering (k = 2) --------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Ensure output directory exists (defaults to current working directory if unset)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > if (!exists("out_dir")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     out_dir <- "."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 1. Combine the 28 known samples and 1 unknown sample into one full matrix
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 2. Run K-Means clustering with k = 2 (representing the two Coffea species)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > set.seed(123) # Ensures reproducible cluster assignments every time you run it
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 3. Attach K-means cluster assignments to your PCA coordinates
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Cluster_Num = km_res$cluster[match(spectrum, names(km_res$cluster))],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         KMeans_Cluster = paste("Cluster", Cluster_Num)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Print a cross-tabulation table in the console to verify sample groupings
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("\nK-Means Cluster Assignments vs. External Labels:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   K-Means Cluster Assignments vs. External Labels:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(table(External_Label = kmeans_df$class, Assigned_Cluster = kmeans_df$KMeans_Cluster))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   Assigned_Cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   External_Label Cluster 1 Cluster 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   arabica         8         6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   robusta         9         5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   unknown         0         1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 4. Calculate cluster centroids in PCA space for clean plotting
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(KMeans_Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 5. Render the ACS-Compliant K-Means Cluster Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cluster_cols <- c("Cluster 1" = "#2a6f97", "Cluster 2" = "#ca6702")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > p_kmeans <- ggplot(kmeans_df, aes(PC1, PC2)) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot known reference samples colored by their unsupervised K-means cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class != "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(colour = KMeans_Cluster, shape = class),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 2.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         alpha = 0.85
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Highlight the Kirkland unknown sample as a bold star colored by its assigned cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class == "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(colour = KMeans_Cluster),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         show.legend = FALSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Mark the mathematical center (centroid) of each K-means cluster with a cross (+)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = centroids_pca,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(PC1, PC2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         shape = 3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(values = cluster_cols, name = "K-Means Partition") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_shape_manual(values = c(arabica = 16, robusta = 17), name = "External Label") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         x = "PC1 (45.8%)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         y = "PC2 (11.5%)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major  = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.minor  = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.border      = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.title        = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.text         = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.title      = element_text(size = 7, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.text       = element_text(size = 7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position   = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.box        = "vertical",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.box.margin = margin(b = -4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.spacing.y  = unit(0.05, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.key.size   = unit(0.35, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(p_kmeans)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     filename = file.path(out_dir, "KMeans_Clustering_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     plot = p_kmeans,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     width = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     height = 3.6,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     units = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     dpi = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- K-Means Unsupervised Clustering (k = 2) --------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Ensure output directory exists (defaults to current working directory if unset)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > if (!exists("out_dir")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     out_dir <- "."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 1. Combine the 28 known samples and 1 unknown sample into one full matrix
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 2. Run K-Means clustering with k = 2 (representing the two Coffea species)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > set.seed(123) # Ensures reproducible cluster assignments every time you run it
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 3. Attach K-means cluster assignments and format clean labels for plotting
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Cluster_Num    = km_res$cluster[match(spectrum, names(km_res$cluster))],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         KMeans_Cluster = factor(paste("Cluster", Cluster_Num), levels = c("Cluster 1", "Cluster 2")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Sample_Role    = factor(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 class == "arabica" ~ "Arabica",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 class == "robusta" ~ "Robusta",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 class == "unknown" ~ "Unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +             ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             levels = c("Arabica", "Robusta", "Unknown", "Centroid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Print a cross-tabulation table in the console to verify sample groupings
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("\nK-Means Cluster Assignments vs. External Labels:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   K-Means Cluster Assignments vs. External Labels:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(table(External_Label = kmeans_df$class, Assigned_Cluster = kmeans_df$KMeans_Cluster))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   Assigned_Cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   External_Label Cluster 1 Cluster 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   arabica         8         6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   robusta         9         5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   unknown         0         1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 4. Calculate cluster centroids in PCA space and assign the "Centroid" legend role
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(KMeans_Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(Sample_Role = factor("Centroid", levels = c("Arabica", "Robusta", "Unknown", "Centroid")))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 5. Define consistent color and shape palettes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cluster_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Cluster 1" = "#2a6f97",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Cluster 2" = "#ca6702"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > role_shapes <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Arabica"  = 16, # Solid circle
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Robusta"  = 17, # Solid triangle
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Unknown"  = 8,  # Asterisk (*)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Centroid" = 3   # Plus (+)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 6. Render the ACS-Compliant K-Means Cluster Plot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > p_kmeans <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot known reference samples (circles & triangles) colored by K-means cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class != "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(x = PC1, y = PC2, colour = KMeans_Cluster, shape = Sample_Role),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 2.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         alpha = 0.85
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot Kirkland unknown sample (asterisk *) colored consistently by its K-means cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class == "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(x = PC1, y = PC2, colour = KMeans_Cluster, shape = Sample_Role),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot cluster centroids (plus +) in black, included in the shape legend
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = centroids_pca,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(x = PC1, y = PC2, shape = Sample_Role),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         values = cluster_cols,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         name   = "K-Means Partition",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         guide  = guide_legend(order = 1, override.aes = list(shape = 16, size = 2.8))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_shape_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         values = role_shapes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         name   = "Sample / Marker",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         drop   = FALSE,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         guide  = guide_legend(order = 2, override.aes = list(colour = "black", size = 2.8))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         x = "PC1 (45.8%)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         y = "PC2 (11.5%)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major  = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.minor  = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.border      = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.title        = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.text         = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.title      = element_text(size = 7, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.text       = element_text(size = 7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position   = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.box        = "vertical",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.box.margin = margin(b = -4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.spacing.y  = unit(0.05, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.key.size   = unit(0.35, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(p_kmeans)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     filename = file.path(out_dir, "KMeans_Clustering_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     plot = p_kmeans,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     width = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     height = 3.7,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     units = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     dpi = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > save.image("~/Metabolomics_Analysis_.RData")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > load("~/Metabolomics_Analysis_.RData")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # Load required libraries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > library(dplyr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > library(ggplot2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # ---- K-Means Unsupervised Clustering (k = 2) --------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > # =============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Ensure output directory exists (defaults to current working directory if unset)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > if (!exists("out_dir")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     out_dir <- "."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 1. Combine the 28 known samples and 1 unknown sample into one full matrix
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > X_all <- rbind(X_known, X_unknown)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 2. Run K-Means clustering with k = 2 (representing the two Coffea species)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > set.seed(123) # Ensures reproducible cluster assignments every time you run it
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > km_res <- kmeans(X_all, centers = 2, nstart = 25)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 3. Attach K-means cluster assignments and format clean labels for plotting
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > kmeans_df <- all_scores %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Cluster_Num    = km_res$cluster[match(spectrum, names(km_res$cluster))],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         KMeans_Cluster = factor(paste("Cluster", Cluster_Num), levels = c("Cluster 1", "Cluster 2")),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         Sample_Role    = factor(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             case_when(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 class == "arabica" ~ "Arabica",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 class == "robusta" ~ "Robusta",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 class == "unknown" ~ "Unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +             ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             levels = c("Arabica", "Robusta", "Unknown", "Centroid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Print a cross-tabulation table in the console to verify sample groupings
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cat("\nK-Means Cluster Assignments vs. External Labels:\n")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   K-Means Cluster Assignments vs. External Labels:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(table(External_Label = kmeans_df$class, Assigned_Cluster = kmeans_df$KMeans_Cluster))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   Assigned_Cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   External_Label Cluster 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   arabica         8
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   robusta         9
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   unknown         0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   Assigned_Cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   External_Label Cluster 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   arabica         6
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   robusta         5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   unknown         1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 4. Calculate cluster centroids in PCA space and assign the "Centroid" legend role
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > centroids_pca <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(KMeans_Cluster) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(PC1 = mean(PC1), PC2 = mean(PC2), .groups = "drop") %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(Sample_Role = factor("Centroid", levels = c("Arabica", "Robusta", "Unknown", "Centroid")))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 5. Define consistent color and shape palettes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cluster_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Cluster 1" = "#2a6f97", # Blue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Cluster 2" = "#ca6702"  # Orange
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > role_shapes <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Arabica"  = 16, # Solid circle
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Robusta"  = 17, # Solid triangle
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Unknown"  = 8,  # Asterisk (*)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Centroid" = 3   # Plus (+)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # 6. Render the ACS-Compliant K-Means Cluster Plot (Figure 2B)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > p_kmeans <- ggplot() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_hline(yintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_vline(xintercept = 0, colour = "grey92", linewidth = 0.4) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot known reference samples (circles & triangles) colored by K-means cluster
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class != "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(x = PC1, y = PC2, colour = KMeans_Cluster, shape = Sample_Role),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 2.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         alpha = 0.85
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot Kirkland unknown sample as a bold crimson red asterisk (*), matching Panel A
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = filter(kmeans_df, class == "unknown"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(x = PC1, y = PC2, shape = Sample_Role),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "#9a031e",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     # Plot cluster centroids (plus +) in black, included in the shape legend
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     geom_point(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         data = centroids_pca,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         aes(x = PC1, y = PC2, shape = Sample_Role),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         size = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         stroke = 1.2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         colour = "black"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_colour_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         values = cluster_cols,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         name   = "K-Means Partition",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         guide  = guide_legend(order = 1, override.aes = list(shape = 16, size = 2.8))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     scale_shape_manual(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         values = role_shapes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         name   = "Sample / Marker",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         drop   = FALSE,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         guide  = guide_legend(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             order = 2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             override.aes = list(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 colour = c("black", "black", "#9a031e", "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +                 size   = c(2.6, 2.6, 3.2, 3.0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +             )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     labs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         x = "PC1 (45.8%)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         y = "PC2 (11.5%)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     ) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme_bw(base_size = 8, base_family = "sans") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     theme(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.major  = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.grid.minor  = element_blank(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         panel.border      = element_rect(colour = "black", linewidth = 0.75),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.title        = element_text(size = 9, face = "plain"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         axis.text         = element_text(color = "black"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.title      = element_text(size = 7, face = "bold"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.text       = element_text(size = 7),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.position   = "top",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.box        = "vertical",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.box.margin = margin(b = -4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.spacing.y  = unit(0.05, "cm"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         legend.key.size   = unit(0.35, "cm")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > print(p_kmeans)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > ggsave(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     filename = file.path(out_dir, "KMeans_Clustering_ACS.png"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     plot = p_kmeans,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     width = 3.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     height = 3.7,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     units = "in",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     dpi = 600
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > # Identify which cluster has the lower mean PC1 (Arabica) vs. higher mean PC1 (Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cluster_means <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     group_by(Cluster_Num) %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     summarise(mean_PC1 = mean(PC1), .groups = "drop")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > arabica_num <- cluster_means$Cluster_Num[which.min(cluster_means$mean_PC1)]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > kmeans_df <- kmeans_df %>%
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +     mutate(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +         KMeans_Cluster = factor(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             ifelse(Cluster_Num == arabica_num, "Arabica Cluster", "Robusta Cluster"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +             levels = c("Arabica Cluster", "Robusta Cluster")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   > 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     > cluster_cols <- c(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Arabica Cluster" = "#2a6f97", # Blue (matches Panel A Arabica)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +     "Robusta Cluster" = "#ca6702"  # Orange (matches Panel A Robusta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       + )